fn q12_direct_lineitem_page_raw_enabled() -> bool {
    std::env::var("DODAM_Q12_ENABLE_DIRECT_LINEITEM_PAGE_RAW")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
}

fn q12_row_group_map_chunk() -> usize {
    std::env::var("DODAM_Q12_ROW_GROUP_MAP_CHUNK")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(4)
}

fn q12_late_materialized_enabled() -> bool {
    std::env::var_os("DODAM_Q12_ENABLE_LATE_MATERIALIZE").is_some()
}

fn q12_late_materialized_row_group_chunk() -> usize {
    std::env::var("DODAM_Q12_LATE_ROW_GROUP_CHUNK")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(2)
}

fn q12_late_materialized_max_selected_ratio() -> f64 {
    std::env::var("DODAM_Q12_LATE_MAX_SELECTED_RATIO")
        .ok()
        .and_then(|value| value.parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(0.20)
}

fn q12_late_materialized_max_selector_run_ratio() -> f64 {
    std::env::var("DODAM_Q12_LATE_MAX_SELECTOR_RUN_RATIO")
        .ok()
        .and_then(|value| value.parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(0.50)
}

fn q12_late_materialized_max_runs_per_selected() -> f64 {
    std::env::var("DODAM_Q12_LATE_MAX_RUNS_PER_SELECTED")
        .ok()
        .and_then(|value| value.parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(1.25)
}

fn q12_receiptdate_pruning_predicates(start_days: i32, end_days: i32) -> Vec<Expr> {
    date_range_pruning_predicates("l_receiptdate", start_days, end_days)
}

#[inline(always)]
fn q12_lineitem_dates_match(
    commitdate: i32,
    receiptdate: i32,
    shipdate: i32,
    start_days: i32,
    end_days: i32,
) -> bool {
    commitdate < receiptdate
        && shipdate < commitdate
        && receiptdate >= start_days
        && receiptdate < end_days
}

fn date_range_pruning_predicates(column: &str, start_days: i32, end_days: i32) -> Vec<Expr> {
    vec![
        Expr::Comparison(ComparisonExpr {
            column: column.to_string(),
            op: ComparisonOp::GtEq,
            value: LiteralValue::Int64(i64::from(start_days)),
        }),
        Expr::Comparison(ComparisonExpr {
            column: column.to_string(),
            op: ComparisonOp::Lt,
            value: LiteralValue::Int64(i64::from(end_days)),
        }),
    ]
}

fn q12_filtered_lineitem_counts_batch_into(
    batch: RecordBatch,
    shipmodes: &[String],
    start_days: i32,
    end_days: i32,
    pending: &mut Q12PendingMap,
) -> Result<()> {
    let orderkeys = batch_column(&batch, "l_orderkey")?;
    let modes = batch_string_column(&batch, "l_shipmode")?;
    let commitdates = batch_column(&batch, "l_commitdate")?;
    let receiptdates = batch_column(&batch, "l_receiptdate")?;
    let shipdates = batch_column(&batch, "l_shipdate")?;
    if q12_typed_loop_enabled()
        && q12_filtered_lineitem_counts_batch_typed_into(
            orderkeys,
            modes,
            commitdates,
            receiptdates,
            shipdates,
            shipmodes,
            start_days,
            end_days,
            pending,
        )
    {
        return Ok(());
    }
    for row in 0..batch.num_rows() {
        if modes.is_null(row) {
            continue;
        }
        let mode = modes.value(row);
        let Some(mode_index) = q12_shipmode_index(shipmodes, mode) else {
            continue;
        };
        let (Some(orderkey), Some(commitdate), Some(receiptdate), Some(shipdate)) = (
            numeric_i64_value(orderkeys, row)?,
            date32_value(commitdates, row)?,
            date32_value(receiptdates, row)?,
            date32_value(shipdates, row)?,
        ) else {
            continue;
        };
        if !q12_lineitem_dates_match(commitdate, receiptdate, shipdate, start_days, end_days) {
            continue;
        }
        q12_pending_increment(pending, orderkey, mode_index);
    }
    Ok(())
}

fn q12_filtered_lineitem_counts_projected_batch(
    batch: RecordBatch,
    shipmodes: &[String],
    start_days: i32,
    end_days: i32,
) -> Result<Q12PendingMap> {
    let mut pending = q12_pending_map_new();
    q12_filtered_lineitem_counts_projected_batch_into(
        batch,
        shipmodes,
        start_days,
        end_days,
        &mut pending,
    )?;
    Ok(pending)
}

fn q12_filtered_lineitem_counts_projected_batch_into(
    batch: RecordBatch,
    shipmodes: &[String],
    start_days: i32,
    end_days: i32,
    pending: &mut Q12PendingMap,
) -> Result<()> {
    let mut consumer = Q12ProjectedLineitemConsumer {
        shipmodes,
        start_days,
        end_days,
        pending,
    };
    consume_record_batch(&mut consumer, &batch)
}

struct Q12ProjectedLineitemConsumer<'a, 'b> {
    shipmodes: &'a [String],
    start_days: i32,
    end_days: i32,
    pending: &'b mut Q12PendingMap,
}

impl BatchConsumer for Q12ProjectedLineitemConsumer<'_, '_> {
    fn consume(&mut self, view: BatchView<'_>) -> Result<()> {
        if q12_filtered_lineitem_counts_projected_view_into(
            view,
            self.shipmodes,
            self.start_days,
            self.end_days,
            self.pending,
        )? {
            return Ok(());
        }
        let Some(batch) = view.try_record_batch() else {
            return Err(DodamError::UnsupportedSql(
                "Q12 consumer lineitem raw vector columns have unsupported types".to_string(),
            ));
        };
        q12_filtered_lineitem_counts_batch_into(
            batch.clone(),
            self.shipmodes,
            self.start_days,
            self.end_days,
            self.pending,
        )
    }
}

fn q12_filtered_lineitem_counts_projected_view_into(
    view: BatchView<'_>,
    shipmodes: &[String],
    start_days: i32,
    end_days: i32,
    pending: &mut Q12PendingMap,
) -> Result<bool> {
    if view.num_columns() != 5 || !q12_typed_loop_enabled() {
        return Ok(false);
    }
    if view.num_columns() == 5
        && let Some(layout) = Q12LineitemDictionaryView::try_new(view)
        && q12_filtered_lineitem_counts_batch_dictionary_typed_into(
            layout, shipmodes, start_days, end_days, pending,
        )
    {
        return Ok(true);
    }
    if let Some(layout) = Q12LineitemStringView::try_new(view)
        && q12_filtered_lineitem_counts_string_view_into(
            layout, shipmodes, start_days, end_days, pending,
        )
    {
        return Ok(true);
    }
    Ok(false)
}

#[allow(clippy::too_many_arguments)]
fn q12_filtered_lineitem_counts_direct_raw_into(
    orderkeys: &[i64],
    mode_ids: &[i32],
    dictionary: &[bytes::Bytes],
    commitdates: &[i32],
    receiptdates: &[i32],
    shipdates: &[i32],
    shipmodes: &[String],
    start_days: i32,
    end_days: i32,
    pending: &mut Q12PendingMap,
) {
    let Some(mode_flags) = q12_dictionary_bytes_match_flags(dictionary, shipmodes) else {
        return;
    };
    let mut accumulator = Q12PendingRunAccumulator::new(pending);
    for row in 0..orderkeys.len() {
        let commitdate = commitdates[row];
        let receiptdate = receiptdates[row];
        if !q12_lineitem_dates_match(
            commitdate,
            receiptdate,
            shipdates[row],
            start_days,
            end_days,
        ) {
            continue;
        }
        let mode_id = mode_ids[row];
        if mode_id < 0 {
            continue;
        }
        let Some(mode_index) = mode_flags
            .get(mode_id as usize)
            .and_then(|mode_index| *mode_index)
        else {
            continue;
        };
        accumulator.increment(orderkeys[row], mode_index);
    }
    accumulator.finish();
}

#[allow(clippy::too_many_arguments)]
fn q12_filtered_lineitem_counts_direct_page_raw_into(
    orderkey_bytes: &[u8],
    mode_ids: &[i32],
    dictionary: &[bytes::Bytes],
    commitdate_bytes: &[u8],
    receiptdate_bytes: &[u8],
    shipdate_bytes: &[u8],
    records: usize,
    shipmodes: &[String],
    start_days: i32,
    end_days: i32,
    pending: &mut Q12PendingMap,
) {
    let Some(mode_flags) = q12_dictionary_bytes_match_flags(dictionary, shipmodes) else {
        return;
    };
    if orderkey_bytes.len() < records.saturating_mul(std::mem::size_of::<i64>())
        || commitdate_bytes.len() < records.saturating_mul(std::mem::size_of::<i32>())
        || receiptdate_bytes.len() < records.saturating_mul(std::mem::size_of::<i32>())
        || shipdate_bytes.len() < records.saturating_mul(std::mem::size_of::<i32>())
        || mode_ids.len() < records
    {
        return;
    }
    let mut accumulator = Q12PendingRunAccumulator::new(pending);
    let mut row = 0usize;
    while row + 8 <= records {
        for offset in 0..8 {
            let row = row + offset;
            let commitdate = read_i32_le_unaligned(commitdate_bytes, row);
            let receiptdate = read_i32_le_unaligned(receiptdate_bytes, row);
            if !q12_lineitem_dates_match(
                commitdate,
                receiptdate,
                read_i32_le_unaligned(shipdate_bytes, row),
                start_days,
                end_days,
            ) {
                continue;
            }
            let mode_id = mode_ids[row];
            if mode_id < 0 {
                continue;
            }
            let Some(mode_index) = mode_flags
                .get(mode_id as usize)
                .and_then(|mode_index| *mode_index)
            else {
                continue;
            };
            accumulator.increment(read_i64_le_unaligned(orderkey_bytes, row), mode_index);
        }
        row += 8;
    }
    while row < records {
        let commitdate = read_i32_le_unaligned(commitdate_bytes, row);
        let receiptdate = read_i32_le_unaligned(receiptdate_bytes, row);
        if q12_lineitem_dates_match(
            commitdate,
            receiptdate,
            read_i32_le_unaligned(shipdate_bytes, row),
            start_days,
            end_days,
        ) {
            let mode_id = mode_ids[row];
            if mode_id >= 0
                && let Some(mode_index) = mode_flags
                    .get(mode_id as usize)
                    .and_then(|mode_index| *mode_index)
            {
                accumulator.increment(read_i64_le_unaligned(orderkey_bytes, row), mode_index);
            }
        }
        row += 1;
    }
    accumulator.finish();
}

fn q12_filtered_lineitem_counts_selected_payload_into(
    orderkeys: &[i64],
    mode_ids: &[i32],
    dictionary: &[bytes::Bytes],
    shipmodes: &[String],
    pending: &mut Q12PendingMap,
) {
    let Some(mode_flags) = q12_dictionary_bytes_match_flags(dictionary, shipmodes) else {
        return;
    };
    let rows = orderkeys.len().min(mode_ids.len());
    let mut accumulator = Q12PendingRunAccumulator::new(pending);
    let mut row = 0usize;
    while row + 8 <= rows {
        for offset in 0..8 {
            let row = row + offset;
            let Some(mode_index) = q12_mode_dictionary_match_index(mode_ids[row], &mode_flags)
            else {
                continue;
            };
            accumulator.increment(orderkeys[row], mode_index);
        }
        row += 8;
    }
    while row < rows {
        if let Some(mode_index) = q12_mode_dictionary_match_index(mode_ids[row], &mode_flags) {
            accumulator.increment(orderkeys[row], mode_index);
        }
        row += 1;
    }
    accumulator.finish();
}

#[allow(clippy::too_many_arguments)]
fn q12_filtered_lineitem_counts_direct_dict_raw_into(
    key_ids: &[i32],
    key_dictionary: &[i64],
    mode_ids: &[i32],
    mode_dictionary: &[bytes::Bytes],
    commitdate_ids: &[i32],
    commitdate_dictionary: &[i32],
    receiptdate_ids: &[i32],
    receiptdate_dictionary: &[i32],
    shipdate_ids: &[i32],
    shipdate_dictionary: &[i32],
    shipmodes: &[String],
    start_days: i32,
    end_days: i32,
    pending: &mut Q12PendingMap,
) {
    let Some(mode_flags) = q12_dictionary_bytes_match_flags(mode_dictionary, shipmodes) else {
        return;
    };
    let records = key_ids
        .len()
        .min(mode_ids.len())
        .min(commitdate_ids.len())
        .min(receiptdate_ids.len())
        .min(shipdate_ids.len());
    let mut accumulator = Q12PendingRunAccumulator::new(pending);
    let mut row = 0usize;
    while row + 8 <= records {
        for offset in 0..8 {
            let row = row + offset;
            let Some(commitdate) =
                q12_i32_dictionary_value(commitdate_ids[row], commitdate_dictionary)
            else {
                continue;
            };
            let Some(receiptdate) =
                q12_i32_dictionary_value(receiptdate_ids[row], receiptdate_dictionary)
            else {
                continue;
            };
            let Some(shipdate) = q12_i32_dictionary_value(shipdate_ids[row], shipdate_dictionary)
            else {
                continue;
            };
            if !q12_lineitem_dates_match(commitdate, receiptdate, shipdate, start_days, end_days) {
                continue;
            }
            let Some(mode_index) = q12_mode_dictionary_match_index(mode_ids[row], &mode_flags)
            else {
                continue;
            };
            let Some(orderkey) = q12_i64_dictionary_value(key_ids[row], key_dictionary) else {
                continue;
            };
            accumulator.increment(orderkey, mode_index);
        }
        row += 8;
    }
    while row < records {
        let Some(commitdate) = q12_i32_dictionary_value(commitdate_ids[row], commitdate_dictionary)
        else {
            row += 1;
            continue;
        };
        let Some(receiptdate) =
            q12_i32_dictionary_value(receiptdate_ids[row], receiptdate_dictionary)
        else {
            row += 1;
            continue;
        };
        let Some(shipdate) = q12_i32_dictionary_value(shipdate_ids[row], shipdate_dictionary)
        else {
            row += 1;
            continue;
        };
        if q12_lineitem_dates_match(commitdate, receiptdate, shipdate, start_days, end_days)
            && let Some(mode_index) = q12_mode_dictionary_match_index(mode_ids[row], &mode_flags)
            && let Some(orderkey) = q12_i64_dictionary_value(key_ids[row], key_dictionary)
        {
            accumulator.increment(orderkey, mode_index);
        }
        row += 1;
    }
    accumulator.finish();
}

#[inline(always)]
fn q12_i32_dictionary_value(id: i32, dictionary: &[i32]) -> Option<i32> {
    let id = usize::try_from(id).ok()?;
    dictionary.get(id).copied()
}

#[inline(always)]
fn q12_i64_dictionary_value(id: i32, dictionary: &[i64]) -> Option<i64> {
    let id = usize::try_from(id).ok()?;
    dictionary.get(id).copied()
}

#[inline(always)]
fn q12_mode_dictionary_match_index(id: i32, flags: &[Option<usize>]) -> Option<usize> {
    let id = usize::try_from(id).ok()?;
    flags.get(id).and_then(|mode_index| *mode_index)
}

fn q12_dictionary_bytes_match_flags(
    dictionary: &[bytes::Bytes],
    shipmodes: &[String],
) -> Option<Vec<Option<usize>>> {
    let [left_mode, right_mode] = shipmodes else {
        return None;
    };
    let left_mode = left_mode.as_bytes();
    let right_mode = right_mode.as_bytes();
    Some(
        dictionary
            .iter()
            .map(|value| {
                if value.as_ref() == left_mode {
                    Some(0)
                } else if value.as_ref() == right_mode {
                    Some(1)
                } else {
                    None
                }
            })
            .collect(),
    )
}

struct Q12LineitemStringView<'a> {
    orderkeys: I64VectorView<'a>,
    modes: Utf8VectorView<'a>,
    commitdates: Date32VectorView<'a>,
    receiptdates: Date32VectorView<'a>,
    shipdates: Date32VectorView<'a>,
}

impl<'a> Q12LineitemStringView<'a> {
    fn try_new(view: BatchView<'a>) -> Option<Self> {
        (view.num_columns() == 5).then_some(Self {
            orderkeys: view.i64_vector(0)?,
            modes: view.utf8_vector(1)?,
            commitdates: view.date32_vector(2)?,
            receiptdates: view.date32_vector(3)?,
            shipdates: view.date32_vector(4)?,
        })
    }
}

struct Q12LineitemDictionaryView<'a> {
    orderkeys: I64VectorView<'a>,
    modes: DictionaryI32View<'a>,
    commitdates: Date32VectorView<'a>,
    receiptdates: Date32VectorView<'a>,
    shipdates: Date32VectorView<'a>,
}

impl<'a> Q12LineitemDictionaryView<'a> {
    fn try_new(view: BatchView<'a>) -> Option<Self> {
        (view.num_columns() == 5).then_some(Self {
            orderkeys: view.i64_vector(0)?,
            modes: view.dictionary_i32_view(1)?,
            commitdates: view.date32_vector(2)?,
            receiptdates: view.date32_vector(3)?,
            shipdates: view.date32_vector(4)?,
        })
    }
}

#[allow(clippy::too_many_arguments)]
fn q12_filtered_lineitem_counts_batch_dictionary_typed_into(
    view: Q12LineitemDictionaryView<'_>,
    shipmodes: &[String],
    start_days: i32,
    end_days: i32,
    pending: &mut Q12PendingMap,
) -> bool {
    let [left_mode, right_mode] = shipmodes else {
        return false;
    };
    let Some(mode_flags) =
        dictionary_i32_view_match_flags(view.modes, &[left_mode.as_bytes(), right_mode.as_bytes()])
    else {
        return false;
    };
    let mode_keys = view.modes.keys();
    if let Some(orderkey_values) = view.orderkeys.values_if_null_free()
        && view.modes.null_count() == 0
        && let (Some(commitdate_values), Some(receiptdate_values), Some(shipdate_values)) = (
            view.commitdates.values_if_null_free(),
            view.receiptdates.values_if_null_free(),
            view.shipdates.values_if_null_free(),
        )
    {
        let mut accumulator = Q12PendingRunAccumulator::new(pending);
        if q12_lineitem_selection_vector_enabled() {
            let mut selected = SelectionVector::with_capacity(orderkey_values.len().min(4096));
            for row in 0..orderkey_values.len() {
                let commitdate = commitdate_values[row];
                let receiptdate = receiptdate_values[row];
                if q12_lineitem_dates_match(
                    commitdate,
                    receiptdate,
                    shipdate_values[row],
                    start_days,
                    end_days,
                ) {
                    selected.push(row);
                }
            }
            if q12_should_use_lineitem_selection_vector(selected.len(), orderkey_values.len()) {
                for &row in selected.as_slice() {
                    let row = row as usize;
                    let Some(mode_index) =
                        dictionary_i32_view_match_index(mode_keys, &mode_flags, row)
                    else {
                        continue;
                    };
                    accumulator.increment(orderkey_values[row], mode_index);
                }
                accumulator.finish();
                return true;
            }
        }
        for row in 0..orderkey_values.len() {
            let commitdate = commitdate_values[row];
            let receiptdate = receiptdate_values[row];
            if !q12_lineitem_dates_match(
                commitdate,
                receiptdate,
                shipdate_values[row],
                start_days,
                end_days,
            ) {
                continue;
            }
            let Some(mode_index) = dictionary_i32_view_match_index(mode_keys, &mode_flags, row)
            else {
                continue;
            };
            accumulator.increment(orderkey_values[row], mode_index);
        }
        accumulator.finish();
        return true;
    }
    let mut accumulator = Q12PendingRunAccumulator::new(pending);
    for row in 0..view.orderkeys.len() {
        if view.orderkeys.is_null(row)
            || view.modes.is_null(row)
            || view.commitdates.is_null(row)
            || view.receiptdates.is_null(row)
            || view.shipdates.is_null(row)
        {
            continue;
        }
        let commitdate = view.commitdates.value(row);
        let receiptdate = view.receiptdates.value(row);
        if !q12_lineitem_dates_match(
            commitdate,
            receiptdate,
            view.shipdates.value(row),
            start_days,
            end_days,
        ) {
            continue;
        }
        let Some(mode_index) = dictionary_i32_view_match_index(mode_keys, &mode_flags, row) else {
            continue;
        };
        accumulator.increment(view.orderkeys.value(row), mode_index);
    }
    accumulator.finish();
    true
}

#[allow(clippy::too_many_arguments)]
fn q12_filtered_lineitem_counts_batch_typed_into(
    orderkeys: &ArrayRef,
    modes: &StringArray,
    commitdates: &ArrayRef,
    receiptdates: &ArrayRef,
    shipdates: &ArrayRef,
    shipmodes: &[String],
    start_days: i32,
    end_days: i32,
    pending: &mut Q12PendingMap,
) -> bool {
    let Some(orderkeys) = orderkeys.as_any().downcast_ref::<Int64Array>() else {
        return false;
    };
    let Some(commitdates) = commitdates.as_any().downcast_ref::<Date32Array>() else {
        return false;
    };
    let Some(receiptdates) = receiptdates.as_any().downcast_ref::<Date32Array>() else {
        return false;
    };
    let Some(shipdates) = shipdates.as_any().downcast_ref::<Date32Array>() else {
        return false;
    };
    q12_filtered_lineitem_counts_string_view_into(
        Q12LineitemStringView {
            orderkeys: I64VectorView::Arrow(orderkeys),
            modes: Utf8VectorView::Arrow(modes),
            commitdates: Date32VectorView::Arrow(commitdates),
            receiptdates: Date32VectorView::Arrow(receiptdates),
            shipdates: Date32VectorView::Arrow(shipdates),
        },
        shipmodes,
        start_days,
        end_days,
        pending,
    )
}

fn q12_filtered_lineitem_counts_string_view_into(
    view: Q12LineitemStringView<'_>,
    shipmodes: &[String],
    start_days: i32,
    end_days: i32,
    pending: &mut Q12PendingMap,
) -> bool {
    let [left_mode, right_mode] = shipmodes else {
        return false;
    };
    let left_mode = left_mode.as_bytes();
    let right_mode = right_mode.as_bytes();
    if let Some(orderkey_values) = view.orderkeys.values_if_null_free()
        && view.modes.null_count() == 0
        && let (Some(commitdate_values), Some(receiptdate_values), Some(shipdate_values)) = (
            view.commitdates.values_if_null_free(),
            view.receiptdates.values_if_null_free(),
            view.shipdates.values_if_null_free(),
        )
    {
        let mut accumulator = Q12PendingRunAccumulator::new(pending);
        if q12_lineitem_selection_vector_enabled() {
            let mut selected = SelectionVector::with_capacity(orderkey_values.len().min(4096));
            for row in 0..orderkey_values.len() {
                let commitdate = commitdate_values[row];
                let receiptdate = receiptdate_values[row];
                if q12_lineitem_dates_match(
                    commitdate,
                    receiptdate,
                    shipdate_values[row],
                    start_days,
                    end_days,
                ) {
                    selected.push(row);
                }
            }
            if q12_should_use_lineitem_selection_vector(selected.len(), orderkey_values.len()) {
                for &row in selected.as_slice() {
                    let row = row as usize;
                    let mode = view.modes.value_bytes(row);
                    let mode_index = if mode == left_mode {
                        0
                    } else if mode == right_mode {
                        1
                    } else {
                        continue;
                    };
                    accumulator.increment(orderkey_values[row], mode_index);
                }
                accumulator.finish();
                return true;
            }
        }
        for row in 0..orderkey_values.len() {
            let commitdate = commitdate_values[row];
            let receiptdate = receiptdate_values[row];
            if !q12_lineitem_dates_match(
                commitdate,
                receiptdate,
                shipdate_values[row],
                start_days,
                end_days,
            ) {
                continue;
            }
            let mode = view.modes.value_bytes(row);
            let mode_index = if mode == left_mode {
                0
            } else if mode == right_mode {
                1
            } else {
                continue;
            };
            accumulator.increment(orderkey_values[row], mode_index);
        }
        accumulator.finish();
        return true;
    }
    let mut accumulator = Q12PendingRunAccumulator::new(pending);
    for row in 0..view.orderkeys.len() {
        if view.orderkeys.is_null(row)
            || view.modes.is_null(row)
            || view.commitdates.is_null(row)
            || view.receiptdates.is_null(row)
            || view.shipdates.is_null(row)
        {
            continue;
        }
        let commitdate = view.commitdates.value(row);
        let receiptdate = view.receiptdates.value(row);
        if !q12_lineitem_dates_match(
            commitdate,
            receiptdate,
            view.shipdates.value(row),
            start_days,
            end_days,
        ) {
            continue;
        }
        let mode = view.modes.value_bytes(row);
        let mode_index = if mode == left_mode {
            0
        } else if mode == right_mode {
            1
        } else {
            continue;
        };
        accumulator.increment(view.orderkeys.value(row), mode_index);
    }
    accumulator.finish();
    true
}

fn q12_lineitem_selection_vector_enabled() -> bool {
    std::env::var("DODAM_Q12_ENABLE_LINEITEM_SELECTION_VECTOR")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
}

fn q12_lineitem_selection_vector_max_ratio() -> f64 {
    std::env::var("DODAM_Q12_LINEITEM_SELECTION_VECTOR_MAX_RATIO")
        .ok()
        .and_then(|value| value.parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(0.50)
}

fn q12_should_use_lineitem_selection_vector(selected_rows: usize, total_rows: usize) -> bool {
    if selected_rows == 0 || total_rows == 0 {
        return selected_rows == 0;
    }
    (selected_rows as f64 / total_rows as f64) <= q12_lineitem_selection_vector_max_ratio()
}

fn q12_shipmode_index(shipmodes: &[String], mode: &str) -> Option<usize> {
    match shipmodes {
        [left, _] if mode == left => Some(0),
        [_, right] if mode == right => Some(1),
        _ => None,
    }
}

fn q12_typed_loop_enabled() -> bool {
    std::env::var_os("DODAM_Q12_DISABLE_TYPED_LOOP").is_none()
}

struct Q12LateState {
    shipmodes: Arc<Vec<String>>,
    start_days: i32,
    end_days: i32,
    selected_modes: Vec<u8>,
    selected_offset: usize,
    pending: Q12PendingMap,
}

fn q12_late_build_selection_batch(
    batch: RecordBatch,
    selection: &mut LateSelectionBuilder,
    state: &mut Q12LateState,
) -> Result<Option<()>> {
    let modes = batch_string_column(&batch, "l_shipmode")?;
    let Some(commitdates) = batch_column(&batch, "l_commitdate")?
        .as_any()
        .downcast_ref::<Date32Array>()
    else {
        return Ok(None);
    };
    let Some(receiptdates) = batch_column(&batch, "l_receiptdate")?
        .as_any()
        .downcast_ref::<Date32Array>()
    else {
        return Ok(None);
    };
    let Some(shipdates) = batch_column(&batch, "l_shipdate")?
        .as_any()
        .downcast_ref::<Date32Array>()
    else {
        return Ok(None);
    };
    let [left_mode, right_mode] = state.shipmodes.as_slice() else {
        return Ok(None);
    };
    if modes.null_count() != 0
        || commitdates.null_count() != 0
        || receiptdates.null_count() != 0
        || shipdates.null_count() != 0
    {
        return Ok(None);
    }
    let left_mode = left_mode.as_bytes();
    let right_mode = right_mode.as_bytes();
    let mode_offsets = modes.value_offsets();
    let mode_data = modes.value_data();
    let commitdate_values = commitdates.values().as_ref();
    let receiptdate_values = receiptdates.values().as_ref();
    let shipdate_values = shipdates.values().as_ref();
    for row in 0..batch.num_rows() {
        let commitdate = commitdate_values[row];
        let receiptdate = receiptdate_values[row];
        if !q12_lineitem_dates_match(
            commitdate,
            receiptdate,
            shipdate_values[row],
            state.start_days,
            state.end_days,
        ) {
            selection.push(false);
            continue;
        }
        let mode = bytes_string_parts(mode_offsets, mode_data, row);
        let mode_index = if mode == left_mode {
            0
        } else if mode == right_mode {
            1
        } else {
            selection.push(false);
            continue;
        };
        state.selected_modes.push(mode_index);
        selection.push(true);
    }
    Ok(Some(()))
}

fn q12_late_build_selection_view(
    view: BatchView<'_>,
    selection: &mut LateSelectionBuilder,
    state: &mut Q12LateState,
) -> Result<Option<()>> {
    if view.num_columns() == 4 {
        let Some(modes) = view.utf8_vector(0) else {
            let Some(batch) = view.try_record_batch() else {
                return Ok(None);
            };
            return q12_late_build_selection_batch(batch.clone(), selection, state);
        };
        let (Some(commitdates), Some(receiptdates), Some(shipdates)) =
            (view.date32(1), view.date32(2), view.date32(3))
        else {
            let Some(batch) = view.try_record_batch() else {
                return Ok(None);
            };
            return q12_late_build_selection_batch(batch.clone(), selection, state);
        };
        let [left_mode, right_mode] = state.shipmodes.as_slice() else {
            return Ok(None);
        };
        if modes.null_count() != 0
            || commitdates.null_count() != 0
            || receiptdates.null_count() != 0
            || shipdates.null_count() != 0
        {
            return Ok(None);
        }
        let left_mode = left_mode.as_bytes();
        let right_mode = right_mode.as_bytes();
        let commitdate_values = commitdates.values().as_ref();
        let receiptdate_values = receiptdates.values().as_ref();
        let shipdate_values = shipdates.values().as_ref();
        for row in 0..view.num_rows() {
            let commitdate = commitdate_values[row];
            let receiptdate = receiptdate_values[row];
            if !q12_lineitem_dates_match(
                commitdate,
                receiptdate,
                shipdate_values[row],
                state.start_days,
                state.end_days,
            ) {
                selection.push(false);
                continue;
            }
            let mode = modes.value_bytes(row);
            let mode_index = if mode == left_mode {
                0
            } else if mode == right_mode {
                1
            } else {
                selection.push(false);
                continue;
            };
            state.selected_modes.push(mode_index);
            selection.push(true);
        }
        return Ok(Some(()));
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(None);
    };
    q12_late_build_selection_batch(batch.clone(), selection, state)
}

fn q12_late_consume_orderkey_payload_batch(
    batch: RecordBatch,
    state: &mut Q12LateState,
) -> Result<Option<()>> {
    let Some(orderkeys) = batch_column(&batch, "l_orderkey")?
        .as_any()
        .downcast_ref::<Int64Array>()
    else {
        return Ok(None);
    };
    if orderkeys.null_count() != 0 {
        return Ok(None);
    }
    for &orderkey in orderkeys.values() {
        let mode_index = *state
            .selected_modes
            .get(state.selected_offset)
            .ok_or_else(|| {
                DodamError::UnsupportedSql("Q12 row selection payload mismatch".to_string())
            })? as usize;
        q12_pending_increment(&mut state.pending, orderkey, mode_index);
        state.selected_offset += 1;
    }
    Ok(Some(()))
}

fn q12_late_consume_orderkey_payload_view(
    view: BatchView<'_>,
    state: &mut Q12LateState,
) -> Result<Option<()>> {
    if view.num_columns() == 1 {
        let Some(orderkeys) = view.i64_vector(0) else {
            let Some(batch) = view.try_record_batch() else {
                return Ok(None);
            };
            return q12_late_consume_orderkey_payload_batch(batch.clone(), state);
        };
        let Some(orderkey_values) = orderkeys.values_if_null_free() else {
            return Ok(None);
        };
        for &orderkey in orderkey_values {
            let mode_index = *state
                .selected_modes
                .get(state.selected_offset)
                .ok_or_else(|| {
                    DodamError::UnsupportedSql("Q12 row selection payload mismatch".to_string())
                })? as usize;
            q12_pending_increment(&mut state.pending, orderkey, mode_index);
            state.selected_offset += 1;
        }
        return Ok(Some(()));
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(None);
    };
    q12_late_consume_orderkey_payload_batch(batch.clone(), state)
}

fn q12_log_late_materialized_profile(metrics: LateMaterializedMetrics, row_group_chunk: usize) {
    if !tpch_profile_enabled() {
        return;
    }
    let ratio = if metrics.total_rows == 0 {
        0.0
    } else {
        metrics.selected_rows as f64 / metrics.total_rows as f64
    };
    eprintln!(
        "[dodam:tpch-profile] Q12 lineitem: late_materialized rows={} selected={} ratio={:.6} selector_runs={} row_group_chunk={}",
        metrics.total_rows, metrics.selected_rows, ratio, metrics.selector_runs, row_group_chunk
    );
}

fn q12_merge_pending_orders(pending: &mut Q12PendingMap, batch_pending: Q12PendingMap) {
    for (orderkey, order) in batch_pending {
        q12_pending_add_order(pending, orderkey, order);
    }
}

async fn q12_shipping_mode_counts_from_orders(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    shipmodes: &[String],
    pending: &Q12PendingMap,
) -> Result<Vec<Q12Row>> {
    if q12_order_direct_column_reader_enabled()
        && let Some(rows) = q12_shipping_mode_counts_from_orders_direct(
            engine,
            path.clone(),
            batch_size,
            shipmodes,
            pending,
        )?
    {
        return Ok(rows);
    }
    if q12_order_late_materialized_enabled()
        && let Some(rows) = q12_shipping_mode_counts_from_orders_late(
            engine,
            path.clone(),
            batch_size,
            shipmodes,
            pending,
        )
        .await?
    {
        return Ok(rows);
    }
    if q12_order_fused_scan_enabled()
        && !q12_order_row_filter_enabled()
        && !q12_order_bloom_filter_enabled()
        && let Some(rows) = q12_shipping_mode_counts_from_orders_fused(
            engine,
            path.clone(),
            batch_size,
            shipmodes,
            pending,
        )
        .await?
    {
        return Ok(rows);
    }
    if q12_order_sorted_pending_lookup_enabled() {
        return q12_shipping_mode_counts_from_orders_sorted(
            engine, path, batch_size, shipmodes, pending,
        )
        .await;
    }
    let projection = Projection::Columns(vec![
        "o_orderkey".to_string(),
        "o_orderpriority".to_string(),
    ]);
    let mut stream = if q12_order_row_filter_enabled() {
        engine
            .scan_parquet_batches_i64_set_filtered(
                path,
                batch_size,
                projection,
                "o_orderkey",
                pending.keys().copied().collect(),
            )
            .await?
    } else if q12_order_bloom_filter_enabled() {
        engine
            .scan_parquet_batches_i64_bloom_filtered(
                path,
                batch_size,
                projection,
                "o_orderkey",
                pending.keys().copied().collect(),
            )
            .await?
    } else if q12_order_dictionary_priority_enabled() {
        engine
            .scan_parquet_batches_dictionary_columns(
                path,
                batch_size,
                projection,
                vec!["o_orderpriority".to_string()],
            )
            .await?
    } else {
        engine
            .scan_parquet_batches(path, batch_size, None, projection, None)
            .await?
    };
    let pending = Arc::new(AdaptiveI64Map::from_hash((*pending).clone()));
    let collect_profile = tpch_profile_enabled();
    let partial = parallel_batch_fold_view_chunks(
        &mut stream,
        q12_order_chunk_size(),
        Q12OrdersPartial::default,
        move |view, partial| {
            q12_merge_orders_partial(
                partial,
                q12_shipping_mode_counts_projected_view_partial(view, &pending, collect_profile)?,
            );
            Ok(Some(()))
        },
        Ok,
        Q12OrdersPartial::default(),
        q12_merge_orders_partial,
        "Q12 orders aggregate",
    )?;
    q12_log_orders_profile(&partial.profile);
    let groups = partial.groups;
    let rows = groups
        .into_iter()
        .enumerate()
        .map(|(index, state)| Q12Row {
            shipmode: shipmodes[index].clone(),
            high_line_count: state.high_line_count,
            low_line_count: state.low_line_count,
        })
        .collect::<Vec<_>>();
    Ok(rows)
}

async fn q12_shipping_mode_counts_from_orders_sorted(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    shipmodes: &[String],
    pending: &Q12PendingMap,
) -> Result<Vec<Q12Row>> {
    let projection = Projection::Columns(vec![
        "o_orderkey".to_string(),
        "o_orderpriority".to_string(),
    ]);
    let mut stream = engine
        .scan_parquet_batches(path, batch_size, None, projection, None)
        .await?;
    let pending = Arc::new(SortedI64Lookup::from_hash_map(pending));
    let groups = parallel_batch_fold_view_chunks(
        &mut stream,
        q12_order_chunk_size(),
        || [Q12State::default(); 2],
        move |view, groups| {
            q12_merge_shipping_mode_counts(
                groups,
                q12_shipping_mode_counts_projected_view_sorted(view, &pending)?,
            );
            Ok(Some(()))
        },
        Ok,
        [Q12State::default(); 2],
        q12_merge_shipping_mode_counts,
        "Q12 orders sorted aggregate",
    )?;
    Ok(groups
        .into_iter()
        .enumerate()
        .map(|(index, state)| Q12Row {
            shipmode: shipmodes[index].clone(),
            high_line_count: state.high_line_count,
            low_line_count: state.low_line_count,
        })
        .collect())
}

async fn q12_shipping_mode_counts_from_orders_fused(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    shipmodes: &[String],
    pending: &Q12PendingMap,
) -> Result<Option<Vec<Q12Row>>> {
    let pending = Arc::new(AdaptiveI64Map::from_hash((*pending).clone()));
    let projection = Projection::Columns(vec![
        "o_orderkey".to_string(),
        "o_orderpriority".to_string(),
    ]);
    let build_state = || [Q12State::default(); 2];
    let finish = |groups| Ok(Some(groups));
    let partials = if q12_order_fused_dictionary_priority_enabled() {
        engine
            .parquet_row_group_map_dictionary_columns_pruned_view(
                path,
                batch_size,
                projection,
                vec!["o_orderpriority".to_string()],
                Vec::new(),
                q12_order_fused_row_group_chunk(),
                build_state,
                {
                    let pending = pending.clone();
                    move |view, groups: &mut [Q12State; 2]| {
                        q12_merge_shipping_mode_counts(
                            groups,
                            q12_shipping_mode_counts_projected_view(view, &pending)?,
                        );
                        Ok(Some(()))
                    }
                },
                finish,
            )
            .await?
    } else {
        engine
            .parquet_row_group_map_view(
                path,
                batch_size,
                projection,
                q12_order_fused_row_group_chunk(),
                build_state,
                {
                    let pending = pending.clone();
                    move |view, groups: &mut [Q12State; 2]| {
                        q12_merge_shipping_mode_counts(
                            groups,
                            q12_shipping_mode_counts_projected_view(view, &pending)?,
                        );
                        Ok(Some(()))
                    }
                },
                finish,
            )
            .await?
    };
    let Some(partials) = partials else {
        return Ok(None);
    };
    let mut groups = [Q12State::default(); 2];
    for partial in partials {
        q12_merge_shipping_mode_counts(&mut groups, partial);
    }
    Ok(Some(
        groups
            .into_iter()
            .enumerate()
            .map(|(index, state)| Q12Row {
                shipmode: shipmodes[index].clone(),
                high_line_count: state.high_line_count,
                low_line_count: state.low_line_count,
            })
            .collect(),
    ))
}

fn q12_shipping_mode_counts_from_orders_direct(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    shipmodes: &[String],
    pending: &Q12PendingMap,
) -> Result<Option<Vec<Q12Row>>> {
    let started = tpch_profile_start();
    let row_groups = (0..engine.parquet_row_group_count(&path)?).collect::<Vec<_>>();
    let pending = Arc::new(AdaptiveI64Map::from_hash(pending.clone()));
    let chunks = row_groups
        .chunks(q12_order_direct_row_group_chunk())
        .map(|chunk| chunk.to_vec())
        .collect::<Vec<_>>();
    let profile = tpch_profile_enabled();
    let partials = chunks
        .into_par_iter()
        .map(|row_groups| {
            q12_order_direct_row_group_chunk_scan(
                engine,
                path.clone(),
                batch_size,
                row_groups,
                pending.clone(),
                profile,
            )
        })
        .collect::<Result<Vec<_>>>()?;
    let mut groups = [Q12State::default(); 2];
    let mut metrics = Q12OrderDirectMetrics::default();
    for partial in partials {
        let Some(partial) = partial else {
            return Ok(None);
        };
        q12_merge_shipping_mode_counts(&mut groups, partial.groups);
        metrics.add(partial.metrics);
    }
    if let Some(started) = started {
        eprintln!(
            "[dodam:tpch-profile] Q12 orders direct_column_reader: total={:.3} ms row_groups={} batches={} rows={} hits={} misses={} payload_runs={} selective_batches={} full_batches={} read={:.3} ms consume={:.3} ms",
            started.elapsed().as_secs_f64() * 1000.0,
            metrics.row_groups,
            metrics.batches,
            metrics.rows,
            metrics.hits,
            metrics.misses,
            metrics.payload_runs,
            metrics.selective_batches,
            metrics.full_batches,
            sql_nanos_to_millis(metrics.read_nanos),
            sql_nanos_to_millis(metrics.consume_nanos),
        );
    }
    Ok(Some(
        groups
            .into_iter()
            .enumerate()
            .map(|(index, state)| Q12Row {
                shipmode: shipmodes[index].clone(),
                high_line_count: state.high_line_count,
                low_line_count: state.low_line_count,
            })
            .collect(),
    ))
}

fn q12_order_direct_row_group_chunk() -> usize {
    std::env::var("DODAM_Q12_ORDER_DIRECT_ROW_GROUP_CHUNK")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(4)
}

#[derive(Default)]
struct Q12OrderDirectPartial {
    groups: [Q12State; 2],
    metrics: Q12OrderDirectMetrics,
}

#[derive(Default)]
struct Q12OrderDirectMetrics {
    row_groups: usize,
    batches: usize,
    rows: usize,
    hits: usize,
    misses: usize,
    payload_runs: usize,
    selective_batches: usize,
    full_batches: usize,
    read_nanos: u64,
    consume_nanos: u64,
}

impl Q12OrderDirectMetrics {
    fn add_scan_metrics(&mut self, metrics: DirectColumnScanMetrics) {
        self.row_groups = self.row_groups.saturating_add(metrics.row_groups);
        self.batches = self.batches.saturating_add(metrics.batches);
        self.rows = self.rows.saturating_add(metrics.rows);
        self.read_nanos = self.read_nanos.saturating_add(metrics.read_nanos);
        self.consume_nanos = self.consume_nanos.saturating_add(metrics.consume_nanos);
    }

    fn add(&mut self, other: Self) {
        self.row_groups = self.row_groups.saturating_add(other.row_groups);
        self.batches = self.batches.saturating_add(other.batches);
        self.rows = self.rows.saturating_add(other.rows);
        self.hits = self.hits.saturating_add(other.hits);
        self.misses = self.misses.saturating_add(other.misses);
        self.payload_runs = self.payload_runs.saturating_add(other.payload_runs);
        self.selective_batches = self
            .selective_batches
            .saturating_add(other.selective_batches);
        self.full_batches = self.full_batches.saturating_add(other.full_batches);
        self.read_nanos = self.read_nanos.saturating_add(other.read_nanos);
        self.consume_nanos = self.consume_nanos.saturating_add(other.consume_nanos);
    }
}

fn q12_order_direct_row_group_chunk_scan(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    row_groups: Vec<usize>,
    pending: Arc<AdaptiveI64Map<Q12PendingOrder>>,
    profile: bool,
) -> Result<Option<Q12OrderDirectPartial>> {
    let started = profile.then(Instant::now);
    let mut partial = Q12OrderDirectPartial::default();
    let mut priorities = Vec::<parquet::data_type::ByteArray>::with_capacity(batch_size);
    let mut priority_def_levels = Vec::<i16>::with_capacity(batch_size);
    let mut hits = Vec::<(usize, Q12PendingOrder)>::with_capacity(batch_size.min(1024));
    let Some(scan_metrics) = engine.scan_parquet_i64_byte_array_payload_columns(
        &path,
        batch_size,
        &row_groups,
        ["o_orderkey", "o_orderpriority"],
        |orderkeys, priority_reader| {
            priorities.clear();
            priority_def_levels.clear();
            hits.clear();
            let order_records = orderkeys.len();
            for row in 0..orderkeys.len() {
                let Some(order) = pending.get(orderkeys[row]) else {
                    partial.metrics.misses += 1;
                    continue;
                };
                partial.metrics.hits += 1;
                hits.push((row, order));
            }
            if hits.is_empty() {
                let skipped = priority_reader.skip_records(order_records)?;
                if skipped != order_records {
                    return Ok(None);
                }
                return Ok(Some(()));
            }
            let payload_runs = q12_order_direct_payload_runs(&hits);
            partial.metrics.payload_runs =
                partial.metrics.payload_runs.saturating_add(payload_runs);
            if payload_runs > q12_order_direct_max_selective_runs_per_batch() {
                partial.metrics.full_batches = partial.metrics.full_batches.saturating_add(1);
                priorities.clear();
                priority_def_levels.clear();
                let (priority_records, priority_values, priority_levels) = priority_reader
                    .read_records(order_records, &mut priority_def_levels, &mut priorities)?;
                if priority_records != order_records || priority_levels != order_records {
                    return Ok(None);
                }
                if priority_values == order_records {
                    for &(row, order) in &hits {
                        let is_high_priority = q12_is_high_priority_bytes(priorities[row].data());
                        q12_apply_pending_order(&mut partial.groups, order, is_high_priority);
                    }
                } else {
                    let mut value_row = vec![None; order_records];
                    let mut value_index = 0usize;
                    for row in 0..order_records {
                        let Some(level) = priority_def_levels.get(row) else {
                            return Ok(None);
                        };
                        if *level == 0 {
                            continue;
                        }
                        value_row[row] = Some(value_index);
                        value_index += 1;
                    }
                    if value_index != priority_values {
                        return Ok(None);
                    }
                    for &(row, order) in &hits {
                        let Some(value_index) = value_row[row] else {
                            continue;
                        };
                        let Some(priority) = priorities.get(value_index) else {
                            return Ok(None);
                        };
                        let is_high_priority = q12_is_high_priority_bytes(priority.data());
                        q12_apply_pending_order(&mut partial.groups, order, is_high_priority);
                    }
                }
                return Ok(Some(()));
            }
            partial.metrics.selective_batches = partial.metrics.selective_batches.saturating_add(1);
            let mut cursor = 0usize;
            let mut hit_index = 0usize;
            while hit_index < hits.len() {
                let start = hits[hit_index].0;
                let mut end_index = hit_index + 1;
                while end_index < hits.len() && hits[end_index].0 == hits[end_index - 1].0 + 1 {
                    end_index += 1;
                }
                let run_len = end_index - hit_index;
                if start > cursor {
                    let skipped = priority_reader.skip_records(start - cursor)?;
                    if skipped != start - cursor {
                        return Ok(None);
                    }
                }
                priorities.clear();
                priority_def_levels.clear();
                let (priority_records, priority_values, priority_levels) = priority_reader
                    .read_records(run_len, &mut priority_def_levels, &mut priorities)?;
                if priority_records != run_len || priority_levels != run_len {
                    return Ok(None);
                }
                if priority_values == run_len {
                    for (offset, hit) in hits[hit_index..end_index].iter().enumerate() {
                        let is_high_priority =
                            q12_is_high_priority_bytes(priorities[offset].data());
                        q12_apply_pending_order(&mut partial.groups, hit.1, is_high_priority);
                    }
                } else {
                    let mut value_index = 0usize;
                    for hit in &hits[hit_index..end_index] {
                        let Some(level) = priority_def_levels.get(hit.0 - start) else {
                            return Ok(None);
                        };
                        if *level == 0 {
                            continue;
                        }
                        let Some(priority) = priorities.get(value_index) else {
                            return Ok(None);
                        };
                        value_index += 1;
                        let is_high_priority = q12_is_high_priority_bytes(priority.data());
                        q12_apply_pending_order(&mut partial.groups, hit.1, is_high_priority);
                    }
                    if value_index != priority_values {
                        return Ok(None);
                    }
                }
                cursor = start + run_len;
                hit_index = end_index;
            }
            if cursor < order_records {
                let skipped = priority_reader.skip_records(order_records - cursor)?;
                if skipped != order_records - cursor {
                    return Ok(None);
                }
            }
            Ok(Some(()))
        },
    )?
    else {
        return Ok(None);
    };
    partial.metrics.add_scan_metrics(scan_metrics);
    if let Some(started) = started {
        eprintln!(
            "[dodam:tpch-profile] Q12 orders direct_column_chunk: row_groups={} rows={} hits={} misses={} payload_runs={} selective_batches={} full_batches={} elapsed={:.3} ms read={:.3} ms consume={:.3} ms",
            partial.metrics.row_groups,
            partial.metrics.rows,
            partial.metrics.hits,
            partial.metrics.misses,
            partial.metrics.payload_runs,
            partial.metrics.selective_batches,
            partial.metrics.full_batches,
            started.elapsed().as_secs_f64() * 1000.0,
            sql_nanos_to_millis(partial.metrics.read_nanos),
            sql_nanos_to_millis(partial.metrics.consume_nanos),
        );
    }
    Ok(Some(partial))
}

fn q12_order_direct_payload_runs(hits: &[(usize, Q12PendingOrder)]) -> usize {
    if hits.is_empty() {
        return 0;
    }
    let mut runs = 1usize;
    for index in 1..hits.len() {
        if hits[index].0 != hits[index - 1].0 + 1 {
            runs += 1;
        }
    }
    runs
}

fn q12_order_direct_max_selective_runs_per_batch() -> usize {
    std::env::var("DODAM_Q12_ORDER_DIRECT_MAX_SELECTIVE_RUNS_PER_BATCH")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap_or(64)
}

async fn q12_shipping_mode_counts_from_orders_late(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    shipmodes: &[String],
    pending: &Q12PendingMap,
) -> Result<Option<Vec<Q12Row>>> {
    let pending = Arc::new(AdaptiveI64Map::from_hash((*pending).clone()));
    let Some(chunks) = engine
        .late_materialized_parquet_map_pruned_with_policy_view(
            path,
            batch_size,
            Projection::Columns(vec!["o_orderkey".to_string()]),
            Projection::Columns(vec!["o_orderpriority".to_string()]),
            Vec::new(),
            q12_order_late_materialized_row_group_chunk(),
            LateMaterializationPolicy::always(),
            {
                let pending = pending.clone();
                move || Q12OrderLateState {
                    pending: pending.clone(),
                    selected_orders: Vec::new(),
                    selected_offset: 0,
                    groups: [Q12State::default(); 2],
                }
            },
            q12_order_late_build_selection_view,
            q12_order_late_consume_priority_view,
            |state, _metrics| {
                if state.selected_offset != state.selected_orders.len() {
                    return Err(DodamError::UnsupportedSql(
                        "Q12 order priority payload mismatch".to_string(),
                    ));
                }
                Ok(Some(state.groups))
            },
        )
        .await?
    else {
        return Ok(None);
    };
    let mut groups = [Q12State::default(); 2];
    let mut metrics = LateMaterializedMetrics::default();
    for chunk in chunks {
        q12_merge_shipping_mode_counts(&mut groups, chunk.output);
        metrics.add(chunk.metrics);
    }
    q12_log_order_late_materialized_profile(metrics, q12_order_late_materialized_row_group_chunk());
    Ok(Some(
        groups
            .into_iter()
            .enumerate()
            .map(|(index, state)| Q12Row {
                shipmode: shipmodes[index].clone(),
                high_line_count: state.high_line_count,
                low_line_count: state.low_line_count,
            })
            .collect(),
    ))
}

