async fn q07_order_customers(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    customer_nations: &FastHashMap<i64, i64>,
) -> Result<FastHashMap<i64, i64>> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec!["o_orderkey".to_string(), "o_custkey".to_string()]),
            None,
        )
        .await?;
    let customer_nations = Arc::new(AdaptiveI64Map::from_hash(customer_nations.clone()));
    parallel_batch_fold_view_chunks(
        &mut stream,
        4,
        || fast_hash_map::<i64, i64>(),
        move |view, orders| {
            merge_maps(orders, q07_order_customers_view(view, &customer_nations)?);
            Ok(Some(()))
        },
        Ok,
        fast_hash_map::<i64, i64>(),
        merge_maps,
        "Q07 order customer nations",
    )
}

fn q07_order_customers_batch(
    batch: RecordBatch,
    customer_nations: &AdaptiveI64Map<i64>,
) -> Result<FastHashMap<i64, i64>> {
    let orderkeys = batch_column(&batch, "o_orderkey")?;
    let custkeys = batch_column(&batch, "o_custkey")?;
    if let Some(orders) = q07_order_customers_batch_typed(orderkeys, custkeys, customer_nations) {
        return Ok(orders);
    }
    let mut orders = fast_hash_map::<i64, i64>();
    for row in 0..batch.num_rows() {
        let (Some(orderkey), Some(custkey)) = (
            numeric_i64_value(orderkeys, row)?,
            numeric_i64_value(custkeys, row)?,
        ) else {
            continue;
        };
        if let Some(nationkey) = customer_nations.get(custkey) {
            orders.insert(orderkey, nationkey);
        }
    }
    Ok(orders)
}

fn q07_order_customers_view(
    view: BatchView<'_>,
    customer_nations: &AdaptiveI64Map<i64>,
) -> Result<FastHashMap<i64, i64>> {
    if view.num_columns() == 2
        && let (Some(orderkeys), Some(custkeys)) = (view.i64_vector(0), view.i64_vector(1))
        && let Some(orders) =
            q07_order_customers_vector_typed(orderkeys, custkeys, customer_nations)
    {
        return Ok(orders);
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(fast_hash_map());
    };
    q07_order_customers_batch(batch.clone(), customer_nations)
}

fn q07_order_customers_batch_typed(
    orderkeys: &ArrayRef,
    custkeys: &ArrayRef,
    customer_nations: &AdaptiveI64Map<i64>,
) -> Option<FastHashMap<i64, i64>> {
    let (Some(orderkeys), Some(custkeys)) = (
        orderkeys.as_any().downcast_ref::<Int64Array>(),
        custkeys.as_any().downcast_ref::<Int64Array>(),
    ) else {
        return None;
    };
    let mut orders = fast_hash_map::<i64, i64>();
    if orderkeys.null_count() == 0 && custkeys.null_count() == 0 {
        for row in 0..orderkeys.len() {
            if let Some(nationkey) = customer_nations.get(custkeys.value(row)) {
                orders.insert(orderkeys.value(row), nationkey);
            }
        }
        return Some(orders);
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row) || custkeys.is_null(row) {
            continue;
        }
        if let Some(nationkey) = customer_nations.get(custkeys.value(row)) {
            orders.insert(orderkeys.value(row), nationkey);
        }
    }
    Some(orders)
}

fn q07_order_customers_vector_typed(
    orderkeys: I64VectorView<'_>,
    custkeys: I64VectorView<'_>,
    customer_nations: &AdaptiveI64Map<i64>,
) -> Option<FastHashMap<i64, i64>> {
    let mut orders = fast_hash_map::<i64, i64>();
    if let (Some(orderkey_values), Some(custkey_values)) = (
        orderkeys.values_if_null_free(),
        custkeys.values_if_null_free(),
    ) {
        for row in 0..orderkey_values.len() {
            if let Some(nationkey) = customer_nations.get(custkey_values[row]) {
                orders.insert(orderkey_values[row], nationkey);
            }
        }
        return Some(orders);
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row) || custkeys.is_null(row) {
            continue;
        }
        if let Some(nationkey) = customer_nations.get(custkeys.value(row)) {
            orders.insert(orderkeys.value(row), nationkey);
        }
    }
    Some(orders)
}

struct Q07Row {
    supp_nation: String,
    cust_nation: String,
    l_year: i32,
    revenue: f64,
}

async fn q07_volume_rows(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    supplier_nations: &FastHashMap<i64, i64>,
    order_customer_nations: &FastHashMap<i64, i64>,
    nation_names: &HashMap<i64, String>,
    start_days: i32,
    end_days: i32,
) -> Result<Vec<Q07Row>> {
    let projection = Projection::Columns(vec![
        "l_orderkey".to_string(),
        "l_suppkey".to_string(),
        "l_shipdate".to_string(),
        "l_extendedprice".to_string(),
        "l_discount".to_string(),
    ]);
    let mut pruning_predicates = if let Some((min_key, max_key)) =
        selective_i64_key_range(order_customer_nations.keys().copied())
    {
        i64_range_pruning_predicates("l_orderkey", min_key, max_key)
    } else {
        Vec::new()
    };
    pruning_predicates.push(Expr::Comparison(ComparisonExpr {
        column: "l_shipdate".to_string(),
        op: ComparisonOp::GtEq,
        value: LiteralValue::Int64(i64::from(start_days)),
    }));
    pruning_predicates.push(Expr::Comparison(ComparisonExpr {
        column: "l_shipdate".to_string(),
        op: ComparisonOp::LtEq,
        value: LiteralValue::Int64(i64::from(end_days)),
    }));
    let supplier_nations = Arc::new(AdaptiveI64Map::from_hash(supplier_nations.clone()));
    let order_customer_nations = Arc::new(order_customer_nations.clone());
    let groups = if q07_late_materialized_enabled()
        && let Some(groups) = q07_volume_rows_late_materialized(
            engine,
            path.clone(),
            batch_size,
            supplier_nations.clone(),
            order_customer_nations.clone(),
            start_days,
            end_days,
            pruning_predicates.clone(),
        )
        .await?
    {
        groups
    } else if q07_row_group_map_enabled() {
        let supplier_nations_for_scan = supplier_nations.clone();
        let order_customer_nations_for_scan = order_customer_nations.clone();
        if let Some(partials) = engine
            .parquet_row_group_map_pruned_view(
                path.clone(),
                batch_size,
                projection.clone(),
                pruning_predicates.clone(),
                q07_row_group_map_chunk(),
                fast_hash_map::<(i64, i64, i32), f64>,
                move |view, groups| {
                    merge_f64_groups(
                        groups,
                        q07_volume_projected_view(
                            view,
                            &supplier_nations_for_scan,
                            &order_customer_nations_for_scan,
                            start_days,
                            end_days,
                        )?,
                    );
                    Ok(Some(()))
                },
                |groups| Ok(Some(groups)),
            )
            .await?
        {
            let mut groups = fast_hash_map::<(i64, i64, i32), f64>();
            for partial in partials {
                merge_f64_groups(&mut groups, partial);
            }
            groups
        } else {
            q07_volume_rows_stream(
                engine,
                path,
                batch_size,
                projection,
                pruning_predicates,
                supplier_nations,
                order_customer_nations,
                start_days,
                end_days,
            )
            .await?
        }
    } else {
        q07_volume_rows_stream(
            engine,
            path,
            batch_size,
            projection,
            pruning_predicates,
            supplier_nations,
            order_customer_nations,
            start_days,
            end_days,
        )
        .await?
    };
    let mut rows = groups
        .into_iter()
        .filter_map(|((supp_nation_key, cust_nation_key, l_year), revenue)| {
            Some(Q07Row {
                supp_nation: nation_names.get(&supp_nation_key)?.clone(),
                cust_nation: nation_names.get(&cust_nation_key)?.clone(),
                l_year,
                revenue,
            })
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        left.supp_nation
            .cmp(&right.supp_nation)
            .then_with(|| left.cust_nation.cmp(&right.cust_nation))
            .then_with(|| left.l_year.cmp(&right.l_year))
    });
    Ok(rows)
}

#[allow(clippy::too_many_arguments)]
async fn q07_volume_rows_late_materialized(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    supplier_nations: Arc<AdaptiveI64Map<i64>>,
    order_customer_nations: Arc<FastHashMap<i64, i64>>,
    start_days: i32,
    end_days: i32,
    pruning_predicates: Vec<Expr>,
) -> Result<Option<FastHashMap<(i64, i64, i32), f64>>> {
    let Some(chunks) = engine
        .late_materialized_parquet_map_pruned_with_policy_view(
            path,
            batch_size,
            Projection::Columns(vec![
                "l_orderkey".to_string(),
                "l_suppkey".to_string(),
                "l_shipdate".to_string(),
            ]),
            Projection::Columns(vec![
                "l_extendedprice".to_string(),
                "l_discount".to_string(),
            ]),
            pruning_predicates,
            q07_late_materialized_row_group_chunk(),
            LateMaterializationPolicy::selective_with_selector_run_ratio(
                q07_late_materialized_max_selected_ratio(),
                q07_late_materialized_max_selector_run_ratio(),
            ),
            {
                let supplier_nations = supplier_nations.clone();
                let order_customer_nations = order_customer_nations.clone();
                move || Q07LateState {
                    supplier_nations: supplier_nations.clone(),
                    order_customer_nations: order_customer_nations.clone(),
                    selected_rows: Vec::new(),
                    payload_offset: 0,
                    groups: fast_hash_map(),
                    year_cache: Date32YearCache::default(),
                }
            },
            move |view, selection, state| {
                q07_late_build_selection_view(view, selection, state, start_days, end_days)
            },
            q07_late_consume_payload_view,
            |state, metrics| {
                if state.payload_offset != state.selected_rows.len() {
                    return Err(DodamError::UnsupportedSql(
                        "Q07 payload row mismatch".to_string(),
                    ));
                }
                Ok(Some((state.groups, metrics)))
            },
        )
        .await?
    else {
        return Ok(None);
    };
    let mut groups = fast_hash_map::<(i64, i64, i32), f64>();
    let mut metrics = LateMaterializedMetrics::default();
    for chunk in chunks {
        let (chunk_groups, chunk_metrics) = chunk.output;
        metrics.add(chunk_metrics);
        merge_f64_groups(&mut groups, chunk_groups);
    }
    q07_log_late_materialized_profile(metrics, q07_late_materialized_row_group_chunk());
    Ok(Some(groups))
}

fn q07_late_materialized_enabled() -> bool {
    if std::env::var("DODAM_Q07_DISABLE_LATE_MATERIALIZE")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
    {
        return false;
    }
    true
}

fn q07_late_materialized_row_group_chunk() -> usize {
    std::env::var("DODAM_Q07_LATE_ROW_GROUP_CHUNK")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(2)
}

fn q07_late_materialized_max_selected_ratio() -> f64 {
    std::env::var("DODAM_Q07_LATE_MAX_SELECTED_RATIO")
        .ok()
        .and_then(|value| value.parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(0.10)
}

fn q07_late_materialized_max_selector_run_ratio() -> f64 {
    std::env::var("DODAM_Q07_LATE_MAX_SELECTOR_RUN_RATIO")
        .ok()
        .and_then(|value| value.parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(0.60)
}

#[derive(Clone, Copy)]
struct Q07LateSelectedRow {
    supp_nation_key: i64,
    cust_nation_key: i64,
    shipdate: i32,
}

struct Q07LateState {
    supplier_nations: Arc<AdaptiveI64Map<i64>>,
    order_customer_nations: Arc<FastHashMap<i64, i64>>,
    selected_rows: Vec<Q07LateSelectedRow>,
    payload_offset: usize,
    groups: FastHashMap<(i64, i64, i32), f64>,
    year_cache: Date32YearCache,
}

fn q07_late_build_selection_batch(
    batch: RecordBatch,
    selection: &mut LateSelectionBuilder,
    state: &mut Q07LateState,
    start_days: i32,
    end_days: i32,
) -> Result<Option<()>> {
    let orderkeys = batch_column(&batch, "l_orderkey")?;
    let suppkeys = batch_column(&batch, "l_suppkey")?;
    let shipdates = batch_column(&batch, "l_shipdate")?;
    if let (Some(orderkeys), Some(suppkeys), Some(shipdates)) = (
        orderkeys.as_any().downcast_ref::<Int64Array>(),
        suppkeys.as_any().downcast_ref::<Int64Array>(),
        shipdates.as_any().downcast_ref::<Date32Array>(),
    ) && orderkeys.null_count() == 0
        && suppkeys.null_count() == 0
        && shipdates.null_count() == 0
    {
        let orderkey_values = orderkeys.values().as_ref();
        let suppkey_values = suppkeys.values().as_ref();
        let shipdate_values = shipdates.values().as_ref();
        for row in 0..orderkey_values.len() {
            let shipdate = shipdate_values[row];
            let selected = if shipdate < start_days || shipdate > end_days {
                None
            } else {
                let supp_nation_key = state.supplier_nations.get(suppkey_values[row]);
                let cust_nation_key = state.order_customer_nations.get(&orderkey_values[row]);
                match (supp_nation_key, cust_nation_key) {
                    (Some(supp_nation_key), Some(cust_nation_key))
                        if supp_nation_key != *cust_nation_key =>
                    {
                        Some(Q07LateSelectedRow {
                            supp_nation_key,
                            cust_nation_key: *cust_nation_key,
                            shipdate,
                        })
                    }
                    _ => None,
                }
            };
            if let Some(row) = selected {
                selection.push(true);
                state.selected_rows.push(row);
            } else {
                selection.push(false);
            }
        }
        return Ok(Some(()));
    }
    for row in 0..batch.num_rows() {
        let selected = match (
            numeric_i64_value(orderkeys, row)?,
            numeric_i64_value(suppkeys, row)?,
            date32_value(shipdates, row)?,
        ) {
            (Some(orderkey), Some(suppkey), Some(shipdate))
                if shipdate >= start_days && shipdate <= end_days =>
            {
                let supp_nation_key = state.supplier_nations.get(suppkey);
                let cust_nation_key = state.order_customer_nations.get(&orderkey);
                match (supp_nation_key, cust_nation_key) {
                    (Some(supp_nation_key), Some(cust_nation_key))
                        if supp_nation_key != *cust_nation_key =>
                    {
                        Some(Q07LateSelectedRow {
                            supp_nation_key,
                            cust_nation_key: *cust_nation_key,
                            shipdate,
                        })
                    }
                    _ => None,
                }
            }
            _ => None,
        };
        if let Some(row) = selected {
            selection.push(true);
            state.selected_rows.push(row);
        } else {
            selection.push(false);
        }
    }
    Ok(Some(()))
}

fn q07_late_build_selection_view(
    view: BatchView<'_>,
    selection: &mut LateSelectionBuilder,
    state: &mut Q07LateState,
    start_days: i32,
    end_days: i32,
) -> Result<Option<()>> {
    if view.num_columns() == 3
        && let (Some(orderkeys), Some(suppkeys), Some(shipdates)) = (
            view.i64_vector(0),
            view.i64_vector(1),
            view.date32_vector(2),
        )
    {
        if let (Some(orderkey_values), Some(suppkey_values), Some(shipdate_values)) = (
            orderkeys.values_if_null_free(),
            suppkeys.values_if_null_free(),
            shipdates.values_if_null_free(),
        ) {
            for row in 0..orderkey_values.len() {
                let selected = q07_late_selected_row(
                    orderkey_values[row],
                    suppkey_values[row],
                    shipdate_values[row],
                    state,
                    start_days,
                    end_days,
                );
                if let Some(row) = selected {
                    selection.push(true);
                    state.selected_rows.push(row);
                } else {
                    selection.push(false);
                }
            }
            return Ok(Some(()));
        }
        for row in 0..orderkeys.len() {
            let selected =
                if orderkeys.is_null(row) || suppkeys.is_null(row) || shipdates.is_null(row) {
                    None
                } else {
                    q07_late_selected_row(
                        orderkeys.value(row),
                        suppkeys.value(row),
                        shipdates.value(row),
                        state,
                        start_days,
                        end_days,
                    )
                };
            if let Some(row) = selected {
                selection.push(true);
                state.selected_rows.push(row);
            } else {
                selection.push(false);
            }
        }
        return Ok(Some(()));
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(None);
    };
    q07_late_build_selection_batch(batch.clone(), selection, state, start_days, end_days)
}

fn q07_late_selected_row(
    orderkey: i64,
    suppkey: i64,
    shipdate: i32,
    state: &Q07LateState,
    start_days: i32,
    end_days: i32,
) -> Option<Q07LateSelectedRow> {
    if shipdate < start_days || shipdate > end_days {
        return None;
    }
    let supp_nation_key = state.supplier_nations.get(suppkey)?;
    let cust_nation_key = *state.order_customer_nations.get(&orderkey)?;
    (supp_nation_key != cust_nation_key).then_some(Q07LateSelectedRow {
        supp_nation_key,
        cust_nation_key,
        shipdate,
    })
}

fn q07_late_consume_payload_batch(
    batch: RecordBatch,
    state: &mut Q07LateState,
) -> Result<Option<()>> {
    let extendedprices = batch_column(&batch, "l_extendedprice")?;
    let discounts = batch_column(&batch, "l_discount")?;
    if let (Some(extendedprices), Some(discounts)) =
        (decimal_input(extendedprices)?, decimal_input(discounts)?)
    {
        if extendedprices.null_count() == 0 && discounts.null_count() == 0 {
            let extendedprice_values = extendedprices.raw_values();
            let discount_values = discounts.raw_values();
            let (discount_scale, revenue_scale) =
                decimal_discounted_revenue_scales(extendedprices, discounts);
            for row in 0..extendedprice_values.len() {
                let Some(selected) = state.selected_rows.get(state.payload_offset).copied() else {
                    return Err(DodamError::UnsupportedSql(
                        "Q07 payload row overflow".to_string(),
                    ));
                };
                state.payload_offset += 1;
                *state
                    .groups
                    .entry((
                        selected.supp_nation_key,
                        selected.cust_nation_key,
                        state.year_cache.year(selected.shipdate)?,
                    ))
                    .or_insert(0.0) += decimal_discounted_revenue_raw(
                    extendedprice_values[row],
                    discount_values[row],
                    discount_scale,
                    revenue_scale,
                );
            }
            return Ok(Some(()));
        }
    }
    for row in 0..batch.num_rows() {
        let Some(selected) = state.selected_rows.get(state.payload_offset).copied() else {
            return Err(DodamError::UnsupportedSql(
                "Q07 payload row overflow".to_string(),
            ));
        };
        state.payload_offset += 1;
        let (Some(extendedprice), Some(discount)) = (
            numeric_f64_value(extendedprices, row)?,
            numeric_f64_value(discounts, row)?,
        ) else {
            continue;
        };
        *state
            .groups
            .entry((
                selected.supp_nation_key,
                selected.cust_nation_key,
                state.year_cache.year(selected.shipdate)?,
            ))
            .or_insert(0.0) += extendedprice * (1.0 - discount);
    }
    Ok(Some(()))
}

fn q07_late_consume_payload_view(
    view: BatchView<'_>,
    state: &mut Q07LateState,
) -> Result<Option<()>> {
    if view.num_columns() == 2
        && let (Some(extendedprices), Some(discounts)) =
            (view.decimal128_vector(0), view.decimal128_vector(1))
    {
        q07_late_consume_payload_vector(extendedprices, discounts, state)?;
        return Ok(Some(()));
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(None);
    };
    q07_late_consume_payload_batch(batch.clone(), state)
}

fn q07_late_consume_payload_vector(
    extendedprices: Decimal128VectorView<'_>,
    discounts: Decimal128VectorView<'_>,
    state: &mut Q07LateState,
) -> Result<()> {
    if extendedprices.null_count() == 0 && discounts.null_count() == 0 {
        let extendedprice_values = extendedprices.raw_values();
        let discount_values = discounts.raw_values();
        let discount_scale = discounts.scale();
        let revenue_scale = 1.0 / (extendedprices.scale() * discounts.scale());
        for row in 0..extendedprice_values.len() {
            let Some(selected) = state.selected_rows.get(state.payload_offset).copied() else {
                return Err(DodamError::UnsupportedSql(
                    "Q07 payload row overflow".to_string(),
                ));
            };
            state.payload_offset += 1;
            *state
                .groups
                .entry((
                    selected.supp_nation_key,
                    selected.cust_nation_key,
                    state.year_cache.year(selected.shipdate)?,
                ))
                .or_insert(0.0) += decimal_discounted_revenue_raw(
                extendedprice_values[row],
                discount_values[row],
                discount_scale,
                revenue_scale,
            );
        }
        return Ok(());
    }
    for row in 0..extendedprices.raw_values().len() {
        let Some(selected) = state.selected_rows.get(state.payload_offset).copied() else {
            return Err(DodamError::UnsupportedSql(
                "Q07 payload row overflow".to_string(),
            ));
        };
        state.payload_offset += 1;
        if extendedprices.is_null(row) || discounts.is_null(row) {
            continue;
        }
        *state
            .groups
            .entry((
                selected.supp_nation_key,
                selected.cust_nation_key,
                state.year_cache.year(selected.shipdate)?,
            ))
            .or_insert(0.0) += extendedprices.value(row) * (1.0 - discounts.value(row));
    }
    Ok(())
}

fn q07_log_late_materialized_profile(metrics: LateMaterializedMetrics, row_group_chunk: usize) {
    if !tpch_profile_enabled() {
        return;
    }
    let ratio = if metrics.total_rows == 0 {
        0.0
    } else {
        metrics.selected_rows as f64 / metrics.total_rows as f64
    };
    eprintln!(
        "[dodam:tpch-profile] Q07 lineitem: late_materialized rows={} selected={} ratio={:.6} selector_runs={} row_group_chunk={}",
        metrics.total_rows, metrics.selected_rows, ratio, metrics.selector_runs, row_group_chunk
    );
}

#[allow(clippy::too_many_arguments)]
async fn q07_volume_rows_stream(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    projection: Projection,
    pruning_predicates: Vec<Expr>,
    supplier_nations: Arc<AdaptiveI64Map<i64>>,
    order_customer_nations: Arc<FastHashMap<i64, i64>>,
    start_days: i32,
    end_days: i32,
) -> Result<FastHashMap<(i64, i64, i32), f64>> {
    let mut stream = if pruning_predicates.is_empty() {
        engine
            .scan_parquet_batches(path, batch_size, None, projection, None)
            .await?
    } else {
        engine
            .scan_parquet_batches_pruned(path, batch_size, projection, pruning_predicates)
            .await?
    };
    parallel_batch_fold_view_chunks(
        &mut stream,
        join_aggregate_chunk_size(),
        || fast_hash_map::<(i64, i64, i32), f64>(),
        move |view, groups| {
            merge_f64_groups(
                groups,
                q07_volume_projected_view(
                    view,
                    &supplier_nations,
                    &order_customer_nations,
                    start_days,
                    end_days,
                )?,
            );
            Ok(Some(()))
        },
        Ok,
        fast_hash_map::<(i64, i64, i32), f64>(),
        merge_f64_groups,
        "Q07 volume aggregate",
    )
}

fn q07_row_group_map_enabled() -> bool {
    std::env::var_os("DODAM_Q07_DISABLE_ROW_GROUP_MAP").is_none()
}

fn q07_row_group_map_chunk() -> usize {
    std::env::var("DODAM_Q07_ROW_GROUP_MAP_CHUNK")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(2)
}

fn q07_volume_batch(
    batch: RecordBatch,
    supplier_nations: &AdaptiveI64Map<i64>,
    order_customer_nations: &FastHashMap<i64, i64>,
    start_days: i32,
    end_days: i32,
) -> Result<FastHashMap<(i64, i64, i32), f64>> {
    let orderkeys = batch_column(&batch, "l_orderkey")?;
    let suppkeys = batch_column(&batch, "l_suppkey")?;
    let shipdates = batch_column(&batch, "l_shipdate")?;
    let extendedprices = batch_column(&batch, "l_extendedprice")?;
    let discounts = batch_column(&batch, "l_discount")?;
    if let Some(groups) = q07_volume_batch_typed(
        orderkeys,
        suppkeys,
        shipdates,
        extendedprices,
        discounts,
        supplier_nations,
        order_customer_nations,
        start_days,
        end_days,
    )? {
        return Ok(groups);
    }
    let mut groups = fast_hash_map::<(i64, i64, i32), f64>();
    let mut year_cache = Date32YearCache::default();
    for row in 0..batch.num_rows() {
        let (Some(orderkey), Some(suppkey), Some(shipdate)) = (
            numeric_i64_value(orderkeys, row)?,
            numeric_i64_value(suppkeys, row)?,
            date32_value(shipdates, row)?,
        ) else {
            continue;
        };
        if shipdate < start_days || shipdate > end_days {
            continue;
        }
        let (Some(supp_nation_key), Some(cust_nation_key)) = (
            supplier_nations.get(suppkey),
            order_customer_nations.get(&orderkey).copied(),
        ) else {
            continue;
        };
        if supp_nation_key == cust_nation_key {
            continue;
        }
        let (Some(extendedprice), Some(discount)) = (
            numeric_f64_value(extendedprices, row)?,
            numeric_f64_value(discounts, row)?,
        ) else {
            continue;
        };
        *groups
            .entry((supp_nation_key, cust_nation_key, year_cache.year(shipdate)?))
            .or_insert(0.0) += extendedprice * (1.0 - discount);
    }
    Ok(groups)
}

#[allow(dead_code)]
fn q07_volume_projected_batch(
    batch: RecordBatch,
    supplier_nations: &AdaptiveI64Map<i64>,
    order_customer_nations: &FastHashMap<i64, i64>,
    start_days: i32,
    end_days: i32,
) -> Result<FastHashMap<(i64, i64, i32), f64>> {
    if batch.num_columns() == 5
        && let Some(groups) = q07_volume_batch_typed(
            batch.column(0),
            batch.column(1),
            batch.column(2),
            batch.column(3),
            batch.column(4),
            supplier_nations,
            order_customer_nations,
            start_days,
            end_days,
        )?
    {
        return Ok(groups);
    }
    q07_volume_batch(
        batch,
        supplier_nations,
        order_customer_nations,
        start_days,
        end_days,
    )
}

fn q07_volume_projected_view(
    view: BatchView<'_>,
    supplier_nations: &AdaptiveI64Map<i64>,
    order_customer_nations: &FastHashMap<i64, i64>,
    start_days: i32,
    end_days: i32,
) -> Result<FastHashMap<(i64, i64, i32), f64>> {
    if view.num_columns() == 5
        && let (
            Some(orderkeys),
            Some(suppkeys),
            Some(shipdates),
            Some(extendedprices),
            Some(discounts),
        ) = (
            view.i64_vector(0),
            view.i64_vector(1),
            view.date32_vector(2),
            view.decimal128_vector(3),
            view.decimal128_vector(4),
        )
    {
        return q07_volume_vector(
            orderkeys,
            suppkeys,
            shipdates,
            extendedprices,
            discounts,
            supplier_nations,
            order_customer_nations,
            start_days,
            end_days,
        );
    }
    let Some(batch) = view.try_record_batch() else {
        return Err(DodamError::UnsupportedSql(
            "Q07 volume raw vector columns have unsupported types".to_string(),
        ));
    };
    q07_volume_batch(
        batch.clone(),
        supplier_nations,
        order_customer_nations,
        start_days,
        end_days,
    )
}

#[allow(clippy::too_many_arguments)]
fn q07_volume_vector(
    orderkeys: I64VectorView<'_>,
    suppkeys: I64VectorView<'_>,
    shipdates: Date32VectorView<'_>,
    extendedprices: Decimal128VectorView<'_>,
    discounts: Decimal128VectorView<'_>,
    supplier_nations: &AdaptiveI64Map<i64>,
    order_customer_nations: &FastHashMap<i64, i64>,
    start_days: i32,
    end_days: i32,
) -> Result<FastHashMap<(i64, i64, i32), f64>> {
    let mut groups = fast_hash_map::<(i64, i64, i32), f64>();
    let mut year_cache = Date32YearCache::default();
    if let (Some(orderkey_values), Some(suppkey_values), Some(shipdate_values)) = (
        orderkeys.values_if_null_free(),
        suppkeys.values_if_null_free(),
        shipdates.values_if_null_free(),
    ) && extendedprices.null_count() == 0
        && discounts.null_count() == 0
    {
        let extendedprice_values = extendedprices.raw_values();
        let discount_values = discounts.raw_values();
        let discount_scale = discounts.scale();
        let revenue_scale = 1.0 / (extendedprices.scale() * discounts.scale());
        if let Some((supplier_nation_values, supplier_nation_present)) =
            supplier_nations.dense_slices()
        {
            for row in 0..orderkey_values.len() {
                let shipdate = shipdate_values[row];
                if shipdate < start_days || shipdate > end_days {
                    continue;
                }
                let Ok(suppkey) = usize::try_from(suppkey_values[row]) else {
                    continue;
                };
                if !supplier_nation_present
                    .get(suppkey)
                    .copied()
                    .unwrap_or(false)
                {
                    continue;
                }
                let Some(cust_nation_key) =
                    order_customer_nations.get(&orderkey_values[row]).copied()
                else {
                    continue;
                };
                let supp_nation_key = supplier_nation_values[suppkey];
                if supp_nation_key == cust_nation_key {
                    continue;
                }
                *groups
                    .entry((supp_nation_key, cust_nation_key, year_cache.year(shipdate)?))
                    .or_insert(0.0) += decimal_discounted_revenue_raw(
                    extendedprice_values[row],
                    discount_values[row],
                    discount_scale,
                    revenue_scale,
                );
            }
            return Ok(groups);
        }
        for row in 0..orderkey_values.len() {
            let shipdate = shipdate_values[row];
            if shipdate < start_days || shipdate > end_days {
                continue;
            }
            let (Some(supp_nation_key), Some(cust_nation_key)) = (
                supplier_nations.get(suppkey_values[row]),
                order_customer_nations.get(&orderkey_values[row]).copied(),
            ) else {
                continue;
            };
            if supp_nation_key == cust_nation_key {
                continue;
            }
            *groups
                .entry((supp_nation_key, cust_nation_key, year_cache.year(shipdate)?))
                .or_insert(0.0) += decimal_discounted_revenue_raw(
                extendedprice_values[row],
                discount_values[row],
                discount_scale,
                revenue_scale,
            );
        }
        return Ok(groups);
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row)
            || suppkeys.is_null(row)
            || shipdates.is_null(row)
            || extendedprices.is_null(row)
            || discounts.is_null(row)
        {
            continue;
        }
        let shipdate = shipdates.value(row);
        if shipdate < start_days || shipdate > end_days {
            continue;
        }
        let (Some(supp_nation_key), Some(cust_nation_key)) = (
            supplier_nations.get(suppkeys.value(row)),
            order_customer_nations.get(&orderkeys.value(row)).copied(),
        ) else {
            continue;
        };
        if supp_nation_key == cust_nation_key {
            continue;
        }
        *groups
            .entry((supp_nation_key, cust_nation_key, year_cache.year(shipdate)?))
            .or_insert(0.0) += extendedprices.value(row) * (1.0 - discounts.value(row));
    }
    Ok(groups)
}

fn q07_volume_batch_typed(
    orderkeys: &ArrayRef,
    suppkeys: &ArrayRef,
    shipdates: &ArrayRef,
    extendedprices: &ArrayRef,
    discounts: &ArrayRef,
    supplier_nations: &AdaptiveI64Map<i64>,
    order_customer_nations: &FastHashMap<i64, i64>,
    start_days: i32,
    end_days: i32,
) -> Result<Option<FastHashMap<(i64, i64, i32), f64>>> {
    let (Some(orderkeys), Some(suppkeys), Some(shipdates), Some(extendedprices), Some(discounts)) = (
        orderkeys.as_any().downcast_ref::<Int64Array>(),
        suppkeys.as_any().downcast_ref::<Int64Array>(),
        shipdates.as_any().downcast_ref::<Date32Array>(),
        decimal_input(extendedprices)?,
        decimal_input(discounts)?,
    ) else {
        return Ok(None);
    };
    let mut groups = fast_hash_map::<(i64, i64, i32), f64>();
    let mut year_cache = Date32YearCache::default();
    if orderkeys.null_count() == 0
        && suppkeys.null_count() == 0
        && shipdates.null_count() == 0
        && extendedprices.null_count() == 0
        && discounts.null_count() == 0
    {
        let orderkey_values = orderkeys.values().as_ref();
        let suppkey_values = suppkeys.values().as_ref();
        let shipdate_values = shipdates.values().as_ref();
        let extendedprice_values = extendedprices.raw_values();
        let discount_values = discounts.raw_values();
        let (discount_scale, revenue_scale) =
            decimal_discounted_revenue_scales(extendedprices, discounts);
        for row in 0..orderkeys.len() {
            let shipdate = shipdate_values[row];
            if shipdate < start_days || shipdate > end_days {
                continue;
            }
            let (Some(supp_nation_key), Some(cust_nation_key)) = (
                supplier_nations.get(suppkey_values[row]),
                order_customer_nations.get(&orderkey_values[row]).copied(),
            ) else {
                continue;
            };
            if supp_nation_key == cust_nation_key {
                continue;
            }
            *groups
                .entry((supp_nation_key, cust_nation_key, year_cache.year(shipdate)?))
                .or_insert(0.0) += decimal_discounted_revenue_raw(
                extendedprice_values[row],
                discount_values[row],
                discount_scale,
                revenue_scale,
            );
        }
        return Ok(Some(groups));
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row)
            || suppkeys.is_null(row)
            || shipdates.is_null(row)
            || extendedprices.is_null(row)
            || discounts.is_null(row)
        {
            continue;
        }
        let shipdate = shipdates.value(row);
        if shipdate < start_days || shipdate > end_days {
            continue;
        }
        let (Some(supp_nation_key), Some(cust_nation_key)) = (
            supplier_nations.get(suppkeys.value(row)),
            order_customer_nations.get(&orderkeys.value(row)).copied(),
        ) else {
            continue;
        };
        if supp_nation_key == cust_nation_key {
            continue;
        }
        *groups
            .entry((supp_nation_key, cust_nation_key, year_cache.year(shipdate)?))
            .or_insert(0.0) += extendedprices.value(row) * (1.0 - discounts.value(row));
    }
    Ok(Some(groups))
}

fn q07_output(rows: Vec<Q07Row>) -> Result<QueryOutput> {
    let batch = RecordBatch::try_new(
        Arc::new(Schema::new(vec![
            Field::new("supp_nation", DataType::Utf8, false),
            Field::new("cust_nation", DataType::Utf8, false),
            Field::new("l_year", DataType::Int64, false),
            Field::new("revenue", DataType::Float64, false),
        ])),
        vec![
            Arc::new(StringArray::from_iter_values(
                rows.iter().map(|row| row.supp_nation.as_str()),
            )),
            Arc::new(StringArray::from_iter_values(
                rows.iter().map(|row| row.cust_nation.as_str()),
            )),
            Arc::new(Int64Array::from_iter_values(
                rows.iter().map(|row| i64::from(row.l_year)),
            )),
            Arc::new(Float64Array::from_iter_values(
                rows.iter().map(|row| row.revenue),
            )),
        ],
    )?;
    Ok(QueryOutput::Aggregate {
        metrics: AggregateMetrics::default(),
        batches: vec![batch],
    })
}

fn q08_outer_shape(select: &Select, query: &Query) -> bool {
    let projection = select
        .projection
        .iter()
        .map(|item| item.to_string().to_ascii_lowercase())
        .collect::<Vec<_>>()
        .join(", ");
    let group_by = select.group_by.to_string().to_ascii_lowercase();
    let order_by = query
        .order_by
        .as_ref()
        .map(|order_by| order_by.to_string().to_ascii_lowercase())
        .unwrap_or_default();
    select.from.len() == 1
        && projection.contains("o_year")
        && projection.contains("mkt_share")
        && projection.contains("nation = 'brazil'")
        && group_by.contains("o_year")
        && order_by.contains("o_year")
}

fn q08_inner_shape(select: &Select, selection: &SqlExpr) -> bool {
    let projection = select
        .projection
        .iter()
        .map(|item| item.to_string().to_ascii_lowercase())
        .collect::<Vec<_>>()
        .join(", ");
    let selection = selection.to_string().to_ascii_lowercase();
    select.from.len() == 8
        && projection.contains("extract(year from o_orderdate)")
        && projection.contains("l_extendedprice * (1 - l_discount)")
        && projection.contains("n2.n_name as nation")
        && selection.contains("p_partkey = l_partkey")
        && selection.contains("s_suppkey = l_suppkey")
        && selection.contains("l_orderkey = o_orderkey")
        && selection.contains("o_custkey = c_custkey")
        && selection.contains("c_nationkey = n1.n_nationkey")
        && selection.contains("n1.n_regionkey = r_regionkey")
        && selection.contains("s_nationkey = n2.n_nationkey")
        && selection.contains("o_orderdate between")
        && selection.contains("p_type")
}

async fn try_execute_nation_market_share_sql(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(None);
    };
    if !q08_outer_shape(select, query) {
        return Ok(None);
    }
    reject_query_features(query)?;
    reject_select_features(select)?;
    let Some((inner_query, _alias)) = parse_derived_from(select)? else {
        return Ok(None);
    };
    let SetExpr::Select(inner_select) = inner_query.body.as_ref() else {
        return Ok(None);
    };
    let Some(selection) = inner_select.selection.as_ref() else {
        return Ok(None);
    };
    if !q08_inner_shape(inner_select, selection) {
        return Ok(None);
    }
    reject_query_features(inner_query)?;
    reject_select_features(inner_select)?;
    let Some(tables) = parse_comma_join_table_refs(inner_select)? else {
        return Ok(None);
    };
    if tables.len() != 8 {
        return Ok(None);
    }
    let mut part = None;
    let mut supplier = None;
    let mut lineitem = None;
    let mut orders = None;
    let mut customer = None;
    let mut nation = None;
    let mut region = None;
    for table in tables {
        let alias = table_ref_alias_or_name(&table);
        if alias.eq_ignore_ascii_case("part") {
            part = Some(table);
        } else if alias.eq_ignore_ascii_case("supplier") {
            supplier = Some(table);
        } else if alias.eq_ignore_ascii_case("lineitem") {
            lineitem = Some(table);
        } else if alias.eq_ignore_ascii_case("orders") {
            orders = Some(table);
        } else if alias.eq_ignore_ascii_case("customer") {
            customer = Some(table);
        } else if alias.eq_ignore_ascii_case("n1") || alias.eq_ignore_ascii_case("n2") {
            nation.get_or_insert(table);
        } else if alias.eq_ignore_ascii_case("region") {
            region = Some(table);
        }
    }
    let (
        Some(part),
        Some(supplier),
        Some(lineitem),
        Some(orders),
        Some(customer),
        Some(nation),
        Some(region),
    ) = (part, supplier, lineitem, orders, customer, nation, region)
    else {
        return Ok(None);
    };
    let mut conjuncts = Vec::new();
    collect_sql_and_conjuncts(selection, &mut conjuncts);
    let Some(region_name) = string_equality_literal(&conjuncts, "r_name")? else {
        return Ok(None);
    };
    let Some(part_type) = string_equality_literal(&conjuncts, "p_type")? else {
        return Ok(None);
    };
    let Some((start_days, end_days)) = date_between_bounds(&conjuncts, "o_orderdate")? else {
        return Ok(None);
    };

    let region_keys = q05_region_keys(engine, region.path, batch_size, &region_name).await?;
    if region_keys.is_empty() {
        return Ok(Some(q08_output(Vec::new())?));
    }
    let customer_nation_names =
        q05_nation_names(engine, nation.path.clone(), batch_size, &region_keys).await?;
    if customer_nation_names.is_empty() {
        return Ok(Some(q08_output(Vec::new())?));
    }
    let customer_nations =
        q07_customer_nations(engine, customer.path, batch_size, &customer_nation_names).await?;
    if customer_nations.is_empty() {
        return Ok(Some(q08_output(Vec::new())?));
    }
    let order_years = q08_order_years(
        engine,
        orders.path,
        batch_size,
        &customer_nations,
        start_days,
        end_days,
    )
    .await?;
    if order_years.is_empty() {
        return Ok(Some(q08_output(Vec::new())?));
    }
    let part_keys = q08_part_keys(engine, part.path, batch_size, &part_type).await?;
    if part_keys.is_empty() {
        return Ok(Some(q08_output(Vec::new())?));
    }
    let all_nation_names = q10_nation_names(engine, nation.path, batch_size).await?;
    let supplier_is_brazil =
        q08_supplier_is_brazil(engine, supplier.path, batch_size, &all_nation_names).await?;
    if supplier_is_brazil.is_empty() {
        return Ok(Some(q08_output(Vec::new())?));
    }
    let mut rows = q08_market_share_rows(
        engine,
        lineitem.path,
        batch_size,
        &order_years,
        &part_keys,
        &supplier_is_brazil,
    )
    .await?;
    rows.sort_by(|left, right| left.o_year.cmp(&right.o_year));
    Ok(Some(q08_output(rows)?))
}

async fn q08_part_keys(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    part_type: &str,
) -> Result<HashSet<i64>> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec!["p_partkey".to_string(), "p_type".to_string()]),
            None,
        )
        .await?;
    let mut keys = HashSet::new();
    while let Some(batch) = stream.next() {
        let batch = batch?;
        q08_part_keys_view_into(BatchView::new(&batch), part_type, &mut keys)?;
    }
    Ok(keys)
}

fn q08_part_keys_view_into(
    view: BatchView<'_>,
    part_type: &str,
    keys: &mut HashSet<i64>,
) -> Result<()> {
    if view.num_columns() == 2
        && let (Ok(partkeys), Ok(types)) = (view.required_i64(0), view.required_utf8(1))
    {
        for row in 0..view.num_rows() {
            if partkeys.is_valid(row) && types.is_valid(row) && types.value(row) == part_type {
                keys.insert(partkeys.value(row));
            }
        }
        return Ok(());
    }
    let Some(batch) = view.try_record_batch() else {
        return Err(DodamError::UnsupportedSql(
            "Q08 part-key raw vector columns have unsupported types".to_string(),
        ));
    };
    let partkeys = batch_column(batch, "p_partkey")?;
    let types = batch_string_column(batch, "p_type")?;
    for row in 0..batch.num_rows() {
        if types.is_valid(row)
            && types.value(row) == part_type
            && let Some(partkey) = numeric_i64_value(partkeys, row)?
        {
            keys.insert(partkey);
        }
    }
    Ok(())
}

async fn q08_order_years(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    customer_nations: &FastHashMap<i64, i64>,
    start_days: i32,
    end_days: i32,
) -> Result<HashMap<i64, i32>> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec![
                "o_orderkey".to_string(),
                "o_custkey".to_string(),
                "o_orderdate".to_string(),
            ]),
            None,
        )
        .await?;
    let customer_nations = Arc::new(AdaptiveI64Map::from_hash(customer_nations.clone()));
    parallel_batch_fold_view_chunks(
        &mut stream,
        4,
        HashMap::<i64, i32>::new,
        move |view, orders| {
            merge_maps(
                orders,
                q08_order_years_view(view, &customer_nations, start_days, end_days)?,
            );
            Ok(Some(()))
        },
        Ok,
        HashMap::<i64, i32>::new(),
        merge_maps,
        "Q08 order years",
    )
}

fn q08_order_years_batch(
    batch: RecordBatch,
    customer_nations: &AdaptiveI64Map<i64>,
    start_days: i32,
    end_days: i32,
) -> Result<HashMap<i64, i32>> {
    let orderkeys = batch_column(&batch, "o_orderkey")?;
    let custkeys = batch_column(&batch, "o_custkey")?;
    let orderdates = batch_column(&batch, "o_orderdate")?;
    if let Some(orders) = q08_order_years_batch_typed(
        orderkeys,
        custkeys,
        orderdates,
        customer_nations,
        start_days,
        end_days,
    )? {
        return Ok(orders);
    }
    let mut orders = HashMap::new();
    let mut year_cache = Date32YearCache::default();
    for row in 0..batch.num_rows() {
        let (Some(orderkey), Some(custkey), Some(orderdate)) = (
            numeric_i64_value(orderkeys, row)?,
            numeric_i64_value(custkeys, row)?,
            date32_value(orderdates, row)?,
        ) else {
            continue;
        };
        if orderdate >= start_days
            && orderdate <= end_days
            && customer_nations.get(custkey).is_some()
        {
            orders.insert(orderkey, year_cache.year(orderdate)?);
        }
    }
    Ok(orders)
}

fn q08_order_years_view(
    view: BatchView<'_>,
    customer_nations: &AdaptiveI64Map<i64>,
    start_days: i32,
    end_days: i32,
) -> Result<HashMap<i64, i32>> {
    if view.num_columns() == 3
        && let (Some(orderkeys), Some(custkeys), Some(orderdates)) = (
            view.i64_vector(0),
            view.i64_vector(1),
            view.date32_vector(2),
        )
    {
        return q08_order_years_vector(
            orderkeys,
            custkeys,
            orderdates,
            customer_nations,
            start_days,
            end_days,
        );
    }
    let Some(batch) = view.try_record_batch() else {
        return Err(DodamError::UnsupportedSql(
            "Q08 order year raw vector columns have unsupported types".to_string(),
        ));
    };
    q08_order_years_batch(batch.clone(), customer_nations, start_days, end_days)
}

fn q08_order_years_vector(
    orderkeys: I64VectorView<'_>,
    custkeys: I64VectorView<'_>,
    orderdates: Date32VectorView<'_>,
    customer_nations: &AdaptiveI64Map<i64>,
    start_days: i32,
    end_days: i32,
) -> Result<HashMap<i64, i32>> {
    let mut orders = HashMap::new();
    let mut year_cache = Date32YearCache::default();
    if let (Some(orderkey_values), Some(custkey_values), Some(orderdate_values)) = (
        orderkeys.values_if_null_free(),
        custkeys.values_if_null_free(),
        orderdates.values_if_null_free(),
    ) {
        if let Some((_nation_values, nation_present)) = customer_nations.dense_slices() {
            for row in 0..orderkey_values.len() {
                let orderdate = orderdate_values[row];
                if orderdate < start_days || orderdate > end_days {
                    continue;
                }
                let Ok(custkey) = usize::try_from(custkey_values[row]) else {
                    continue;
                };
                if nation_present.get(custkey).copied().unwrap_or(false) {
                    orders.insert(orderkey_values[row], year_cache.year(orderdate)?);
                }
            }
            return Ok(orders);
        }
        for row in 0..orderkey_values.len() {
            let orderdate = orderdate_values[row];
            if orderdate >= start_days
                && orderdate <= end_days
                && customer_nations.get(custkey_values[row]).is_some()
            {
                orders.insert(orderkey_values[row], year_cache.year(orderdate)?);
            }
        }
        return Ok(orders);
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row) || custkeys.is_null(row) || orderdates.is_null(row) {
            continue;
        }
        let orderdate = orderdates.value(row);
        if orderdate >= start_days
            && orderdate <= end_days
            && customer_nations.get(custkeys.value(row)).is_some()
        {
            orders.insert(orderkeys.value(row), year_cache.year(orderdate)?);
        }
    }
    Ok(orders)
}

fn q08_order_years_batch_typed(
    orderkeys: &ArrayRef,
    custkeys: &ArrayRef,
    orderdates: &ArrayRef,
    customer_nations: &AdaptiveI64Map<i64>,
    start_days: i32,
    end_days: i32,
) -> Result<Option<HashMap<i64, i32>>> {
    let (Some(orderkeys), Some(custkeys), Some(orderdates)) = (
        orderkeys.as_any().downcast_ref::<Int64Array>(),
        custkeys.as_any().downcast_ref::<Int64Array>(),
        orderdates.as_any().downcast_ref::<Date32Array>(),
    ) else {
        return Ok(None);
    };
    let mut orders = HashMap::new();
    let mut year_cache = Date32YearCache::default();
    if orderkeys.null_count() == 0 && custkeys.null_count() == 0 && orderdates.null_count() == 0 {
        for row in 0..orderkeys.len() {
            let orderdate = orderdates.value(row);
            if orderdate >= start_days
                && orderdate <= end_days
                && customer_nations.get(custkeys.value(row)).is_some()
            {
                orders.insert(orderkeys.value(row), year_cache.year(orderdate)?);
            }
        }
        return Ok(Some(orders));
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row) || custkeys.is_null(row) || orderdates.is_null(row) {
            continue;
        }
        let orderdate = orderdates.value(row);
        if orderdate >= start_days
            && orderdate <= end_days
            && customer_nations.get(custkeys.value(row)).is_some()
        {
            orders.insert(orderkeys.value(row), year_cache.year(orderdate)?);
        }
    }
    Ok(Some(orders))
}

async fn q08_supplier_is_brazil(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    nation_names: &HashMap<i64, String>,
) -> Result<HashMap<i64, bool>> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec!["s_suppkey".to_string(), "s_nationkey".to_string()]),
            None,
        )
        .await?;
    let mut suppliers = HashMap::new();
    while let Some(batch) = stream.next() {
        let batch = batch?;
        q08_supplier_is_brazil_view_into(BatchView::new(&batch), nation_names, &mut suppliers)?;
    }
    Ok(suppliers)
}

fn q08_supplier_is_brazil_view_into(
    view: BatchView<'_>,
    nation_names: &HashMap<i64, String>,
    suppliers: &mut HashMap<i64, bool>,
) -> Result<()> {
    if view.num_columns() == 2
        && let (Ok(suppkeys), Ok(nationkeys)) = (view.required_i64(0), view.required_i64(1))
    {
        for row in 0..view.num_rows() {
            if suppkeys.is_null(row) || nationkeys.is_null(row) {
                continue;
            }
            if let Some(name) = nation_names.get(&nationkeys.value(row)) {
                suppliers.insert(suppkeys.value(row), name == "BRAZIL");
            }
        }
        return Ok(());
    }
    let Some(batch) = view.try_record_batch() else {
        return Err(DodamError::UnsupportedSql(
            "Q08 supplier raw vector columns have unsupported types".to_string(),
        ));
    };
    let suppkeys = batch_column(batch, "s_suppkey")?;
    let nationkeys = batch_column(batch, "s_nationkey")?;
    for row in 0..batch.num_rows() {
        let (Some(suppkey), Some(nationkey)) = (
            numeric_i64_value(suppkeys, row)?,
            numeric_i64_value(nationkeys, row)?,
        ) else {
            continue;
        };
        if let Some(name) = nation_names.get(&nationkey) {
            suppliers.insert(suppkey, name == "BRAZIL");
        }
    }
    Ok(())
}

struct Q08Row {
    o_year: i32,
    mkt_share: f64,
}

async fn q08_market_share_rows(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    order_years: &HashMap<i64, i32>,
    part_keys: &HashSet<i64>,
    supplier_is_brazil: &HashMap<i64, bool>,
) -> Result<Vec<Q08Row>> {
    if q08_late_materialized_enabled()
        && let Some(rows) = q08_market_share_rows_late_materialized(
            engine,
            path.clone(),
            batch_size,
            order_years,
            part_keys,
            supplier_is_brazil,
        )
        .await?
    {
        return Ok(rows);
    }
    let projection = Projection::Columns(vec![
        "l_orderkey".to_string(),
        "l_partkey".to_string(),
        "l_suppkey".to_string(),
        "l_extendedprice".to_string(),
        "l_discount".to_string(),
    ]);
    let mut pruning_predicates = Vec::new();
    if let Some((min_key, max_key)) = selective_i64_key_range(order_years.keys().copied()) {
        pruning_predicates.extend(i64_range_pruning_predicates("l_orderkey", min_key, max_key));
    }
    if let Some((min_key, max_key)) = selective_i64_key_range(part_keys.iter().copied()) {
        pruning_predicates.extend(i64_range_pruning_predicates("l_partkey", min_key, max_key));
    }
    let mut stream = if should_use_i64_set_row_filter_for_keys(
        true,
        "DODAM_Q08_DISABLE_PARTKEY_ROW_FILTER",
        None,
        part_keys,
        projection_column_count(&projection),
    ) {
        engine
            .scan_parquet_batches_i64_set_filtered_with_row_group_chunk(
                path,
                batch_size,
                projection,
                "l_partkey",
                part_keys.clone(),
                q08_partkey_row_filter_row_group_chunk(),
            )
            .await?
    } else if !pruning_predicates.is_empty() {
        engine
            .scan_parquet_batches_pruned(path, batch_size, projection, pruning_predicates)
            .await?
    } else {
        engine
            .scan_parquet_batches(path, batch_size, None, projection, None)
            .await?
    };
    let order_years = Arc::new(AdaptiveI64Map::from_hash(order_years.clone()));
    let part_keys = Arc::new(AdaptiveI64Set::from_hash(part_keys.clone()));
    let supplier_is_brazil = Arc::new(AdaptiveI64Map::from_hash(supplier_is_brazil.clone()));
    let groups = parallel_batch_fold_view_chunks(
        &mut stream,
        join_aggregate_chunk_size(),
        HashMap::<i32, (f64, f64)>::new,
        move |view, groups| {
            q08_merge_market_share_groups(
                groups,
                q08_market_share_view(view, &order_years, &part_keys, &supplier_is_brazil)?,
            );
            Ok(Some(()))
        },
        Ok,
        HashMap::<i32, (f64, f64)>::new(),
        q08_merge_market_share_groups,
        "Q08 market share aggregate",
    )?;
    Ok(groups
        .into_iter()
        .filter_map(|(o_year, (brazil_volume, total_volume))| {
            (total_volume > 0.0).then_some(Q08Row {
                o_year,
                mkt_share: brazil_volume / total_volume,
            })
        })
        .collect())
}

async fn q08_market_share_rows_late_materialized(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    order_years: &HashMap<i64, i32>,
    part_keys: &HashSet<i64>,
    supplier_is_brazil: &HashMap<i64, bool>,
) -> Result<Option<Vec<Q08Row>>> {
    let order_years = Arc::new(AdaptiveI64Map::from_hash(order_years.clone()));
    let part_keys = Arc::new(AdaptiveI64Set::from_hash(part_keys.clone()));
    let supplier_is_brazil = Arc::new(AdaptiveI64Map::from_hash(supplier_is_brazil.clone()));
    let Some(chunks) = engine
        .late_materialized_parquet_map_pruned_with_policy_view(
            path,
            batch_size,
            Projection::Columns(vec!["l_partkey".to_string()]),
            Projection::Columns(vec![
                "l_orderkey".to_string(),
                "l_suppkey".to_string(),
                "l_extendedprice".to_string(),
                "l_discount".to_string(),
            ]),
            Vec::new(),
            q08_late_row_group_chunk(),
            LateMaterializationPolicy::selective_with_selector_run_ratio(
                q08_late_max_selected_ratio(),
                q08_late_max_selector_run_ratio(),
            ),
            {
                let order_years = order_years.clone();
                let part_keys = part_keys.clone();
                let supplier_is_brazil = supplier_is_brazil.clone();
                move || Q08LateMarketState {
                    order_years: order_years.clone(),
                    part_keys: part_keys.clone(),
                    supplier_is_brazil: supplier_is_brazil.clone(),
                    groups: HashMap::new(),
                }
            },
            q08_late_build_partkey_selection_view,
            q08_late_consume_market_payload_view,
            |state, _metrics| Ok(Some(state.groups)),
        )
        .await?
    else {
        return Ok(None);
    };
    let mut metrics = LateMaterializedMetrics::default();
    let mut groups = HashMap::<i32, (f64, f64)>::new();
    for chunk in chunks {
        metrics.add(chunk.metrics);
        q08_merge_market_share_groups(&mut groups, chunk.output);
    }
    q08_log_late_market_profile(metrics, q08_late_row_group_chunk());
    Ok(Some(
        groups
            .into_iter()
            .filter_map(|(o_year, (brazil_volume, total_volume))| {
                (total_volume > 0.0).then_some(Q08Row {
                    o_year,
                    mkt_share: brazil_volume / total_volume,
                })
            })
            .collect(),
    ))
}

fn q08_late_materialized_enabled() -> bool {
    std::env::var_os("DODAM_Q08_DISABLE_LATE").is_none()
}

fn q08_partkey_row_filter_row_group_chunk() -> usize {
    std::env::var("DODAM_Q08_PARTKEY_ROW_FILTER_ROW_GROUP_CHUNK")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(8)
}

fn q08_late_row_group_chunk() -> usize {
    std::env::var("DODAM_Q08_LATE_ROW_GROUP_CHUNK")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(4)
}

fn q08_late_max_selected_ratio() -> f64 {
    std::env::var("DODAM_Q08_LATE_MAX_SELECTED_RATIO")
        .ok()
        .and_then(|value| value.parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(0.05)
}

fn q08_late_max_selector_run_ratio() -> f64 {
    std::env::var("DODAM_Q08_LATE_MAX_SELECTOR_RUN_RATIO")
        .ok()
        .and_then(|value| value.parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(0.05)
}

struct Q08LateMarketState {
    order_years: Arc<AdaptiveI64Map<i32>>,
    part_keys: Arc<AdaptiveI64Set>,
    supplier_is_brazil: Arc<AdaptiveI64Map<bool>>,
    groups: HashMap<i32, (f64, f64)>,
}

fn q08_late_build_partkey_selection_batch(
    batch: RecordBatch,
    selection: &mut LateSelectionBuilder,
    state: &mut Q08LateMarketState,
) -> Result<Option<()>> {
    let partkeys = batch_column(&batch, "l_partkey")?;
    let Some(partkeys) = partkeys.as_any().downcast_ref::<Int64Array>() else {
        return Ok(None);
    };
    if partkeys.null_count() == 0 {
        for &partkey in partkeys.values().as_ref() {
            selection.push(state.part_keys.contains(partkey));
        }
        return Ok(Some(()));
    }
    for row in 0..partkeys.len() {
        selection.push(partkeys.is_valid(row) && state.part_keys.contains(partkeys.value(row)));
    }
    Ok(Some(()))
}

fn q08_late_build_partkey_selection_view(
    view: BatchView<'_>,
    selection: &mut LateSelectionBuilder,
    state: &mut Q08LateMarketState,
) -> Result<Option<()>> {
    if view.num_columns() == 1 {
        let Some(partkeys) = view.i64_vector(0) else {
            return Ok(None);
        };
        let dense_part_keys = state.part_keys.dense_contains_slice();
        if let Some(partkey_values) = partkeys.values_if_null_free() {
            for &partkey in partkey_values {
                selection.push(state.part_keys.contains_cached(dense_part_keys, partkey));
            }
            return Ok(Some(()));
        }
        for row in 0..partkeys.len() {
            selection.push(
                !partkeys.is_null(row)
                    && state
                        .part_keys
                        .contains_cached(dense_part_keys, partkeys.value(row)),
            );
        }
        return Ok(Some(()));
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(None);
    };
    q08_late_build_partkey_selection_batch(batch.clone(), selection, state)
}

fn q08_late_consume_market_payload_batch(
    batch: RecordBatch,
    state: &mut Q08LateMarketState,
) -> Result<Option<()>> {
    let orderkeys = batch_column(&batch, "l_orderkey")?;
    let suppkeys = batch_column(&batch, "l_suppkey")?;
    let extendedprices = batch_column(&batch, "l_extendedprice")?;
    let discounts = batch_column(&batch, "l_discount")?;
    let (Some(orderkeys), Some(suppkeys), Some(extendedprices), Some(discounts)) = (
        orderkeys.as_any().downcast_ref::<Int64Array>(),
        suppkeys.as_any().downcast_ref::<Int64Array>(),
        decimal_input(extendedprices)?,
        decimal_input(discounts)?,
    ) else {
        return Ok(None);
    };
    if orderkeys.null_count() == 0
        && suppkeys.null_count() == 0
        && extendedprices.null_count() == 0
        && discounts.null_count() == 0
    {
        let orderkey_values = orderkeys.values().as_ref();
        let suppkey_values = suppkeys.values().as_ref();
        let extendedprice_values = extendedprices.raw_values();
        let discount_values = discounts.raw_values();
        let (discount_scale, revenue_scale) =
            decimal_discounted_revenue_scales(extendedprices, discounts);
        for row in 0..orderkey_values.len() {
            let Some(o_year) = state.order_years.get(orderkey_values[row]) else {
                continue;
            };
            let Some(is_brazil) = state.supplier_is_brazil.get(suppkey_values[row]) else {
                continue;
            };
            let volume = decimal_discounted_revenue_raw(
                extendedprice_values[row],
                discount_values[row],
                discount_scale,
                revenue_scale,
            );
            let group = state.groups.entry(o_year).or_insert((0.0, 0.0));
            if is_brazil {
                group.0 += volume;
            }
            group.1 += volume;
        }
        return Ok(Some(()));
    }
    for row in 0..batch.num_rows() {
        if orderkeys.is_null(row)
            || suppkeys.is_null(row)
            || extendedprices.is_null(row)
            || discounts.is_null(row)
        {
            continue;
        }
        let Some(o_year) = state.order_years.get(orderkeys.value(row)) else {
            continue;
        };
        let Some(is_brazil) = state.supplier_is_brazil.get(suppkeys.value(row)) else {
            continue;
        };
        let volume = extendedprices.value(row) * (1.0 - discounts.value(row));
        let group = state.groups.entry(o_year).or_insert((0.0, 0.0));
        if is_brazil {
            group.0 += volume;
        }
        group.1 += volume;
    }
    Ok(Some(()))
}

fn q08_late_consume_market_payload_view(
    view: BatchView<'_>,
    state: &mut Q08LateMarketState,
) -> Result<Option<()>> {
    if view.num_columns() == 4
        && let (Some(orderkeys), Some(suppkeys), Some(extendedprices), Some(discounts)) = (
            view.i64_vector(0),
            view.i64_vector(1),
            view.decimal128_vector(2),
            view.decimal128_vector(3),
        )
    {
        q08_late_consume_market_payload_vector(
            orderkeys,
            suppkeys,
            extendedprices,
            discounts,
            state,
        );
        return Ok(Some(()));
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(None);
    };
    q08_late_consume_market_payload_batch(batch.clone(), state)
}

fn q08_late_consume_market_payload_vector(
    orderkeys: I64VectorView<'_>,
    suppkeys: I64VectorView<'_>,
    extendedprices: Decimal128VectorView<'_>,
    discounts: Decimal128VectorView<'_>,
    state: &mut Q08LateMarketState,
) {
    if let (Some(orderkey_values), Some(suppkey_values)) = (
        orderkeys.values_if_null_free(),
        suppkeys.values_if_null_free(),
    ) && extendedprices.null_count() == 0
        && discounts.null_count() == 0
    {
        let extendedprice_values = extendedprices.raw_values();
        let discount_values = discounts.raw_values();
        let discount_scale = discounts.scale();
        let revenue_scale = 1.0 / (extendedprices.scale() * discounts.scale());
        for row in 0..orderkey_values.len() {
            let Some(o_year) = state.order_years.get(orderkey_values[row]) else {
                continue;
            };
            let Some(is_brazil) = state.supplier_is_brazil.get(suppkey_values[row]) else {
                continue;
            };
            let volume = decimal_discounted_revenue_raw(
                extendedprice_values[row],
                discount_values[row],
                discount_scale,
                revenue_scale,
            );
            let group = state.groups.entry(o_year).or_insert((0.0, 0.0));
            if is_brazil {
                group.0 += volume;
            }
            group.1 += volume;
        }
        return;
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row)
            || suppkeys.is_null(row)
            || extendedprices.is_null(row)
            || discounts.is_null(row)
        {
            continue;
        }
        let Some(o_year) = state.order_years.get(orderkeys.value(row)) else {
            continue;
        };
        let Some(is_brazil) = state.supplier_is_brazil.get(suppkeys.value(row)) else {
            continue;
        };
        let volume = extendedprices.value(row) * (1.0 - discounts.value(row));
        let group = state.groups.entry(o_year).or_insert((0.0, 0.0));
        if is_brazil {
            group.0 += volume;
        }
        group.1 += volume;
    }
}

fn q08_log_late_market_profile(metrics: LateMaterializedMetrics, row_group_chunk: usize) {
    if !tpch_profile_enabled() {
        return;
    }
    let ratio = if metrics.total_rows == 0 {
        0.0
    } else {
        metrics.selected_rows as f64 / metrics.total_rows as f64
    };
    eprintln!(
        "[dodam:tpch-profile] Q08 market share: late_materialized rows={} selected={} ratio={:.6} selector_runs={} row_group_chunk={}",
        metrics.total_rows, metrics.selected_rows, ratio, metrics.selector_runs, row_group_chunk
    );
}

fn q08_market_share_batch(
    batch: RecordBatch,
    order_years: &AdaptiveI64Map<i32>,
    part_keys: &AdaptiveI64Set,
    supplier_is_brazil: &AdaptiveI64Map<bool>,
) -> Result<HashMap<i32, (f64, f64)>> {
    let orderkeys = batch_column(&batch, "l_orderkey")?;
    let partkeys = batch_column(&batch, "l_partkey")?;
    let suppkeys = batch_column(&batch, "l_suppkey")?;
    let extendedprices = batch_column(&batch, "l_extendedprice")?;
    let discounts = batch_column(&batch, "l_discount")?;
    if let Some(groups) = q08_market_share_batch_typed(
        orderkeys,
        partkeys,
        suppkeys,
        extendedprices,
        discounts,
        order_years,
        part_keys,
        supplier_is_brazil,
    )? {
        return Ok(groups);
    }
    let mut groups = HashMap::<i32, (f64, f64)>::new();
    for row in 0..batch.num_rows() {
        let (Some(orderkey), Some(partkey), Some(suppkey)) = (
            numeric_i64_value(orderkeys, row)?,
            numeric_i64_value(partkeys, row)?,
            numeric_i64_value(suppkeys, row)?,
        ) else {
            continue;
        };
        if !part_keys.contains(partkey) {
            continue;
        }
        let Some(o_year) = order_years.get(orderkey) else {
            continue;
        };
        let Some(is_brazil) = supplier_is_brazil.get(suppkey) else {
            continue;
        };
        let (Some(extendedprice), Some(discount)) = (
            numeric_f64_value(extendedprices, row)?,
            numeric_f64_value(discounts, row)?,
        ) else {
            continue;
        };
        let volume = extendedprice * (1.0 - discount);
        let group = groups.entry(o_year).or_insert((0.0, 0.0));
        if is_brazil {
            group.0 += volume;
        }
        group.1 += volume;
    }
    Ok(groups)
}

fn q08_market_share_view(
    view: BatchView<'_>,
    order_years: &AdaptiveI64Map<i32>,
    part_keys: &AdaptiveI64Set,
    supplier_is_brazil: &AdaptiveI64Map<bool>,
) -> Result<HashMap<i32, (f64, f64)>> {
    if view.num_columns() == 5
        && let (
            Some(orderkeys),
            Some(partkeys),
            Some(suppkeys),
            Some(extendedprices),
            Some(discounts),
        ) = (
            view.i64_vector(0),
            view.i64_vector(1),
            view.i64_vector(2),
            view.decimal128_vector(3),
            view.decimal128_vector(4),
        )
    {
        return Ok(q08_market_share_vector(
            orderkeys,
            partkeys,
            suppkeys,
            extendedprices,
            discounts,
            order_years,
            part_keys,
            supplier_is_brazil,
        ));
    }
    let Some(batch) = view.try_record_batch() else {
        return Err(DodamError::UnsupportedSql(
            "Q08 market share raw vector columns have unsupported types".to_string(),
        ));
    };
    q08_market_share_batch(batch.clone(), order_years, part_keys, supplier_is_brazil)
}

fn q08_market_share_vector(
    orderkeys: I64VectorView<'_>,
    partkeys: I64VectorView<'_>,
    suppkeys: I64VectorView<'_>,
    extendedprices: Decimal128VectorView<'_>,
    discounts: Decimal128VectorView<'_>,
    order_years: &AdaptiveI64Map<i32>,
    part_keys: &AdaptiveI64Set,
    supplier_is_brazil: &AdaptiveI64Map<bool>,
) -> HashMap<i32, (f64, f64)> {
    let mut groups = HashMap::<i32, (f64, f64)>::new();
    if let (Some(orderkey_values), Some(partkey_values), Some(suppkey_values)) = (
        orderkeys.values_if_null_free(),
        partkeys.values_if_null_free(),
        suppkeys.values_if_null_free(),
    ) && extendedprices.null_count() == 0
        && discounts.null_count() == 0
    {
        let extendedprice_values = extendedprices.raw_values();
        let discount_values = discounts.raw_values();
        let discount_scale = discounts.scale();
        let revenue_scale = 1.0 / (extendedprices.scale() * discounts.scale());
        let part_contains = part_keys.dense_contains_slice();
        if let (
            Some((order_year_values, order_year_present)),
            Some((brazil_values, brazil_present)),
        ) = (
            order_years.dense_slices(),
            supplier_is_brazil.dense_slices(),
        ) {
            for row in 0..orderkey_values.len() {
                if !part_keys.contains_cached(part_contains, partkey_values[row]) {
                    continue;
                }
                let Ok(orderkey) = usize::try_from(orderkey_values[row]) else {
                    continue;
                };
                if !order_year_present.get(orderkey).copied().unwrap_or(false) {
                    continue;
                }
                let Ok(suppkey) = usize::try_from(suppkey_values[row]) else {
                    continue;
                };
                if !brazil_present.get(suppkey).copied().unwrap_or(false) {
                    continue;
                }
                let volume = decimal_discounted_revenue_raw(
                    extendedprice_values[row],
                    discount_values[row],
                    discount_scale,
                    revenue_scale,
                );
                let group = groups
                    .entry(order_year_values[orderkey])
                    .or_insert((0.0, 0.0));
                if brazil_values[suppkey] {
                    group.0 += volume;
                }
                group.1 += volume;
            }
            return groups;
        }
        for row in 0..orderkey_values.len() {
            if !part_keys.contains_cached(part_contains, partkey_values[row]) {
                continue;
            }
            let Some(o_year) = order_years.get(orderkey_values[row]) else {
                continue;
            };
            let Some(is_brazil) = supplier_is_brazil.get(suppkey_values[row]) else {
                continue;
            };
            let volume = decimal_discounted_revenue_raw(
                extendedprice_values[row],
                discount_values[row],
                discount_scale,
                revenue_scale,
            );
            let group = groups.entry(o_year).or_insert((0.0, 0.0));
            if is_brazil {
                group.0 += volume;
            }
            group.1 += volume;
        }
        return groups;
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row)
            || partkeys.is_null(row)
            || suppkeys.is_null(row)
            || extendedprices.is_null(row)
            || discounts.is_null(row)
        {
            continue;
        }
        if !part_keys.contains(partkeys.value(row)) {
            continue;
        }
        let Some(o_year) = order_years.get(orderkeys.value(row)) else {
            continue;
        };
        let Some(is_brazil) = supplier_is_brazil.get(suppkeys.value(row)) else {
            continue;
        };
        let volume = extendedprices.value(row) * (1.0 - discounts.value(row));
        let group = groups.entry(o_year).or_insert((0.0, 0.0));
        if is_brazil {
            group.0 += volume;
        }
        group.1 += volume;
    }
    groups
}

fn q08_market_share_batch_typed(
    orderkeys: &ArrayRef,
    partkeys: &ArrayRef,
    suppkeys: &ArrayRef,
    extendedprices: &ArrayRef,
    discounts: &ArrayRef,
    order_years: &AdaptiveI64Map<i32>,
    part_keys: &AdaptiveI64Set,
    supplier_is_brazil: &AdaptiveI64Map<bool>,
) -> Result<Option<HashMap<i32, (f64, f64)>>> {
    let (Some(orderkeys), Some(partkeys), Some(suppkeys), Some(extendedprices), Some(discounts)) = (
        orderkeys.as_any().downcast_ref::<Int64Array>(),
        partkeys.as_any().downcast_ref::<Int64Array>(),
        suppkeys.as_any().downcast_ref::<Int64Array>(),
        decimal_input(extendedprices)?,
        decimal_input(discounts)?,
    ) else {
        return Ok(None);
    };
    let mut groups = HashMap::<i32, (f64, f64)>::new();
    if orderkeys.null_count() == 0
        && partkeys.null_count() == 0
        && suppkeys.null_count() == 0
        && extendedprices.null_count() == 0
        && discounts.null_count() == 0
    {
        for row in 0..orderkeys.len() {
            if !part_keys.contains(partkeys.value(row)) {
                continue;
            }
            let Some(o_year) = order_years.get(orderkeys.value(row)) else {
                continue;
            };
            let Some(is_brazil) = supplier_is_brazil.get(suppkeys.value(row)) else {
                continue;
            };
            let volume = extendedprices.value(row) * (1.0 - discounts.value(row));
            let group = groups.entry(o_year).or_insert((0.0, 0.0));
            if is_brazil {
                group.0 += volume;
            }
            group.1 += volume;
        }
        return Ok(Some(groups));
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row)
            || partkeys.is_null(row)
            || suppkeys.is_null(row)
            || extendedprices.is_null(row)
            || discounts.is_null(row)
        {
            continue;
        }
        if !part_keys.contains(partkeys.value(row)) {
            continue;
        }
        let Some(o_year) = order_years.get(orderkeys.value(row)) else {
            continue;
        };
        let Some(is_brazil) = supplier_is_brazil.get(suppkeys.value(row)) else {
            continue;
        };
        let volume = extendedprices.value(row) * (1.0 - discounts.value(row));
        let group = groups.entry(o_year).or_insert((0.0, 0.0));
        if is_brazil {
            group.0 += volume;
        }
        group.1 += volume;
    }
    Ok(Some(groups))
}

fn q08_merge_market_share_groups<S>(
    groups: &mut HashMap<i32, (f64, f64), S>,
    batch_groups: HashMap<i32, (f64, f64), S>,
) where
    S: BuildHasher,
{
    for (year, (brazil, total)) in batch_groups {
        let group = groups.entry(year).or_insert((0.0, 0.0));
        group.0 += brazil;
        group.1 += total;
    }
}

fn q08_output(rows: Vec<Q08Row>) -> Result<QueryOutput> {
    let batch = RecordBatch::try_new(
        Arc::new(Schema::new(vec![
            Field::new("o_year", DataType::Int64, false),
            Field::new("mkt_share", DataType::Float64, false),
        ])),
        vec![
            Arc::new(Int64Array::from_iter_values(
                rows.iter().map(|row| i64::from(row.o_year)),
            )),
            Arc::new(Float64Array::from_iter_values(
                rows.iter().map(|row| row.mkt_share),
            )),
        ],
    )?;
    Ok(QueryOutput::Aggregate {
        metrics: AggregateMetrics::default(),
        batches: vec![batch],
    })
}

fn correlated_avg_threshold_projection_shape(select: &Select) -> bool {
    select.projection.len() == 1
        && select.projection.first().is_some_and(|item| {
            item.to_string()
                .to_ascii_lowercase()
                .contains("sum(l_extendedprice) / 7")
        })
}

fn correlated_avg_threshold_filter_shape(selection: &SqlExpr) -> bool {
    let text = selection.to_string().to_ascii_lowercase();
    text.contains("p_partkey = l_partkey")
        && text.contains("p_brand")
        && text.contains("p_container")
        && text.contains("l_quantity <")
        && text.contains("0.2 * avg(l_quantity)")
        && text.contains("l_partkey = p_partkey")
}

fn select_item_alias(item: &SelectItem) -> Option<String> {
    match item {
        SelectItem::ExprWithAlias { alias, .. } => Some(alias.value.clone()),
        _ => None,
    }
}

fn string_equality_literal(conjuncts: &[SqlExpr], column: &str) -> Result<Option<String>> {
    for conjunct in conjuncts {
        let SqlExpr::BinaryOp { left, op, right } = conjunct else {
            continue;
        };
        if *op != BinaryOperator::Eq {
            continue;
        }
        if sql_expr_column_matches(left, column) {
            if let LiteralValue::Utf8(value) = sql_literal_value(right)? {
                return Ok(Some(value));
            }
        } else if sql_expr_column_matches(right, column)
            && let LiteralValue::Utf8(value) = sql_literal_value(left)?
        {
            return Ok(Some(value));
        }
    }
    Ok(None)
}

fn sql_expr_column_matches(expr: &SqlExpr, column: &str) -> bool {
    match expr {
        SqlExpr::Identifier(ident) => ident.value.eq_ignore_ascii_case(column),
        SqlExpr::CompoundIdentifier(parts) => parts
            .last()
            .is_some_and(|ident| ident.value.eq_ignore_ascii_case(column)),
        SqlExpr::Nested(expr) => sql_expr_column_matches(expr, column),
        _ => false,
    }
}

async fn q17_matching_part_keys(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    brand: &str,
    container: &str,
) -> Result<HashSet<i64>> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec![
                "p_partkey".to_string(),
                "p_brand".to_string(),
                "p_container".to_string(),
            ]),
            None,
        )
        .await?;
    let mut keys = HashSet::new();
    while let Some(batch) = stream.next() {
        let batch = batch?;
        let key = batch_column(&batch, "p_partkey")?;
        let brands = batch_string_column(&batch, "p_brand")?;
        let containers = batch_string_column(&batch, "p_container")?;
        for row in 0..batch.num_rows() {
            if brands.is_valid(row)
                && containers.is_valid(row)
                && brands.value(row) == brand
                && containers.value(row) == container
                && let Some(value) = numeric_i64_value(key, row)?
            {
                keys.insert(value);
            }
        }
    }
    Ok(keys)
}

async fn q17_lineitem_revenue_from_matching_parts(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    part_keys: &HashSet<i64>,
) -> Result<Option<f64>> {
    if q17_late_materialized_enabled()
        && let Some(sum) =
            q17_lineitem_revenue_late_materialized(engine, path.clone(), batch_size, part_keys)
                .await?
    {
        return Ok(sum);
    }
    let part_key_count = part_keys.len();
    let part_keys = Arc::new(AdaptiveI64Set::from_hash(part_keys.clone()));
    let Some(partials) = engine
        .parquet_row_group_map_view(
            path,
            batch_size,
            Projection::Columns(vec![
                "l_partkey".to_string(),
                "l_quantity".to_string(),
                "l_extendedprice".to_string(),
            ]),
            q17_lineitem_chunk_size(),
            {
                let part_key_count = part_key_count;
                move || q17_lineitem_partial_new(part_key_count)
            },
            {
                let part_keys = part_keys.clone();
                move |view, partial| {
                    q17_lineitem_revenue_view_into(view, &part_keys, partial)?;
                    Ok(Some(()))
                }
            },
            |partial| Ok(Some(partial)),
        )
        .await?
    else {
        return Err(DodamError::UnsupportedSql(
            "Q17 lineitem row-group map is unavailable".to_string(),
        ));
    };
    let mut merged = q17_lineitem_partial_new(part_key_count);
    for partial in partials {
        q17_merge_lineitem_revenue_batch(&mut merged, partial);
    }
    let (states, candidate_rows) = merged;
    if candidate_rows.is_empty() {
        return Ok(None);
    }
    let mut sum = 0.0;
    let mut count = 0_usize;
    for (partkey, quantity, extendedprice) in candidate_rows {
        if let Some((quantity_sum, quantity_count)) = states.get(&partkey) {
            let average = quantity_sum / *quantity_count as f64;
            if quantity < 0.2 * average {
                sum += extendedprice;
                count += 1;
            }
        }
    }
    Ok((count > 0).then_some(sum))
}

type Q17LineitemPartial = (HashMap<i64, (f64, u64)>, Vec<(i64, f64, f64)>);

struct Q17LateLineitemState {
    part_keys: Arc<AdaptiveI64Set>,
    quantity_state: HashMap<i64, (f64, u64)>,
    selected_partkeys: Vec<i64>,
    selected_quantities: Vec<f64>,
    payload_offset: usize,
    candidate_rows: Vec<(i64, f64, f64)>,
}

async fn q17_lineitem_revenue_late_materialized(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    part_keys: &HashSet<i64>,
) -> Result<Option<Option<f64>>> {
    let part_keys = Arc::new(AdaptiveI64Set::from_hash(part_keys.clone()));
    let Some(chunks) = engine
        .late_materialized_parquet_map_pruned_with_policy_view(
            path,
            batch_size,
            Projection::Columns(vec!["l_partkey".to_string(), "l_quantity".to_string()]),
            Projection::Columns(vec!["l_extendedprice".to_string()]),
            Vec::new(),
            q17_late_materialized_row_group_chunk(),
            LateMaterializationPolicy::selective_with_selector_run_ratio(
                q17_late_materialized_max_selected_ratio(),
                q17_late_materialized_max_selector_run_ratio(),
            ),
            {
                let part_keys = part_keys.clone();
                move || Q17LateLineitemState {
                    part_keys: part_keys.clone(),
                    quantity_state: HashMap::new(),
                    selected_partkeys: Vec::new(),
                    selected_quantities: Vec::new(),
                    payload_offset: 0,
                    candidate_rows: Vec::new(),
                }
            },
            q17_late_build_quantity_selection_view,
            q17_late_consume_extendedprice_payload_view,
            |state, _metrics| {
                if state.payload_offset != state.selected_partkeys.len()
                    || state.payload_offset != state.selected_quantities.len()
                {
                    return Err(DodamError::UnsupportedSql(
                        "Q17 row selection payload mismatch".to_string(),
                    ));
                }
                Ok(Some((state.quantity_state, state.candidate_rows)))
            },
        )
        .await?
    else {
        return Ok(None);
    };
    let mut quantity_state = HashMap::<i64, (f64, u64)>::new();
    let mut candidate_rows = Vec::<(i64, f64, f64)>::new();
    let mut metrics = LateMaterializedMetrics::default();
    for chunk in chunks {
        let (chunk_state, chunk_candidates) = chunk.output;
        q17_merge_quantity_state(&mut quantity_state, chunk_state);
        candidate_rows.extend(chunk_candidates);
        metrics.add(chunk.metrics);
    }
    q17_log_late_materialized_profile(metrics, q17_late_materialized_row_group_chunk());
    if candidate_rows.is_empty() {
        return Ok(Some(None));
    }
    let mut sum = 0.0;
    let mut count = 0_usize;
    for (partkey, quantity, extendedprice) in candidate_rows {
        if let Some((quantity_sum, quantity_count)) = quantity_state.get(&partkey) {
            let average = quantity_sum / *quantity_count as f64;
            if quantity < 0.2 * average {
                sum += extendedprice;
                count += 1;
            }
        }
    }
    Ok(Some((count > 0).then_some(sum)))
}

fn q17_late_build_quantity_selection_view(
    view: BatchView<'_>,
    selection: &mut LateSelectionBuilder,
    state: &mut Q17LateLineitemState,
) -> Result<Option<()>> {
    if view.num_columns() == 2
        && let (Some(partkeys), Some(quantities)) = (view.i64_vector(0), view.decimal128_vector(1))
    {
        q17_late_build_quantity_selection_typed(partkeys, quantities, selection, state);
        return Ok(Some(()));
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(None);
    };
    let partkeys = batch_column(batch, "l_partkey")?;
    let quantities = batch_column(batch, "l_quantity")?;
    let (Some(partkeys), Some(quantities)) = (
        partkeys.as_any().downcast_ref::<Int64Array>(),
        decimal_input(quantities)?,
    ) else {
        return Ok(None);
    };
    for row in 0..partkeys.len() {
        let selected = !partkeys.is_null(row)
            && !quantities.is_null(row)
            && state.part_keys.contains(partkeys.value(row));
        selection.push(selected);
        if selected {
            let partkey = partkeys.value(row);
            let quantity = quantities.value(row);
            let aggregate = state.quantity_state.entry(partkey).or_insert((0.0, 0));
            aggregate.0 += quantity;
            aggregate.1 += 1;
            state.selected_partkeys.push(partkey);
            state.selected_quantities.push(quantity);
        }
    }
    Ok(Some(()))
}

fn q17_late_build_quantity_selection_typed(
    partkeys: I64VectorView<'_>,
    quantities: Decimal128VectorView<'_>,
    selection: &mut LateSelectionBuilder,
    state: &mut Q17LateLineitemState,
) {
    let dense_part_keys = state.part_keys.dense_contains_slice();
    if let Some(partkey_values) = partkeys.values_if_null_free()
        && quantities.null_count() == 0
    {
        let quantity_values = quantities.raw_values();
        let quantity_scale = 1.0 / quantities.scale();
        for row in 0..partkey_values.len() {
            let partkey = partkey_values[row];
            let selected = state.part_keys.contains_cached(dense_part_keys, partkey);
            selection.push(selected);
            if selected {
                let quantity = quantity_values[row] as f64 * quantity_scale;
                let aggregate = state.quantity_state.entry(partkey).or_insert((0.0, 0));
                aggregate.0 += quantity;
                aggregate.1 += 1;
                state.selected_partkeys.push(partkey);
                state.selected_quantities.push(quantity);
            }
        }
        return;
    }
    for row in 0..partkeys.len() {
        let selected = !partkeys.is_null(row)
            && !quantities.is_null(row)
            && state
                .part_keys
                .contains_cached(dense_part_keys, partkeys.value(row));
        selection.push(selected);
        if selected {
            let partkey = partkeys.value(row);
            let quantity = quantities.value(row);
            let aggregate = state.quantity_state.entry(partkey).or_insert((0.0, 0));
            aggregate.0 += quantity;
            aggregate.1 += 1;
            state.selected_partkeys.push(partkey);
            state.selected_quantities.push(quantity);
        }
    }
}

fn q17_late_consume_extendedprice_payload_view(
    view: BatchView<'_>,
    state: &mut Q17LateLineitemState,
) -> Result<Option<()>> {
    if view.num_columns() == 1
        && let Some(extendedprices) = view.decimal128_vector(0)
    {
        q17_late_consume_extendedprice_payload_typed(extendedprices, state)?;
        return Ok(Some(()));
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(None);
    };
    let extendedprices = batch_column(batch, "l_extendedprice")?;
    let Some(extendedprices) = decimal_input(extendedprices)? else {
        return Ok(None);
    };
    for row in 0..batch.num_rows() {
        let (Some(&partkey), Some(&quantity)) = (
            state.selected_partkeys.get(state.payload_offset),
            state.selected_quantities.get(state.payload_offset),
        ) else {
            return Err(DodamError::UnsupportedSql(
                "Q17 row selection payload overflow".to_string(),
            ));
        };
        state.payload_offset += 1;
        if extendedprices.is_null(row) {
            continue;
        }
        state
            .candidate_rows
            .push((partkey, quantity, extendedprices.value(row)));
    }
    Ok(Some(()))
}

fn q17_late_consume_extendedprice_payload_typed(
    extendedprices: Decimal128VectorView<'_>,
    state: &mut Q17LateLineitemState,
) -> Result<()> {
    if extendedprices.null_count() == 0 {
        let values = extendedprices.raw_values();
        let scale = 1.0 / extendedprices.scale();
        for &raw in values {
            let (Some(&partkey), Some(&quantity)) = (
                state.selected_partkeys.get(state.payload_offset),
                state.selected_quantities.get(state.payload_offset),
            ) else {
                return Err(DodamError::UnsupportedSql(
                    "Q17 row selection payload overflow".to_string(),
                ));
            };
            state.payload_offset += 1;
            state
                .candidate_rows
                .push((partkey, quantity, raw as f64 * scale));
        }
        return Ok(());
    }
    for row in 0..extendedprices.len() {
        let (Some(&partkey), Some(&quantity)) = (
            state.selected_partkeys.get(state.payload_offset),
            state.selected_quantities.get(state.payload_offset),
        ) else {
            return Err(DodamError::UnsupportedSql(
                "Q17 row selection payload overflow".to_string(),
            ));
        };
        state.payload_offset += 1;
        if extendedprices.is_null(row) {
            continue;
        }
        state
            .candidate_rows
            .push((partkey, quantity, extendedprices.value(row)));
    }
    Ok(())
}

fn q17_merge_quantity_state(
    output: &mut HashMap<i64, (f64, u64)>,
    input: HashMap<i64, (f64, u64)>,
) {
    for (partkey, (sum, count)) in input {
        let aggregate = output.entry(partkey).or_insert((0.0, 0));
        aggregate.0 += sum;
        aggregate.1 += count;
    }
}

fn q17_late_materialized_enabled() -> bool {
    !std::env::var("DODAM_DISABLE_Q17_LATE_MATERIALIZATION")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
}

fn q17_late_materialized_row_group_chunk() -> usize {
    std::env::var("DODAM_Q17_LATE_ROW_GROUP_CHUNK")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(2)
}

fn q17_late_materialized_max_selected_ratio() -> f64 {
    std::env::var("DODAM_Q17_LATE_MAX_SELECTED_RATIO")
        .ok()
        .and_then(|value| value.parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(0.20)
}

fn q17_late_materialized_max_selector_run_ratio() -> f64 {
    std::env::var("DODAM_Q17_LATE_MAX_SELECTOR_RUN_RATIO")
        .ok()
        .and_then(|value| value.parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(0.20)
}

fn q17_log_late_materialized_profile(metrics: LateMaterializedMetrics, row_group_chunk: usize) {
    if !tpch_profile_enabled() {
        return;
    }
    let ratio = if metrics.total_rows == 0 {
        0.0
    } else {
        metrics.selected_rows as f64 / metrics.total_rows as f64
    };
    eprintln!(
        "[dodam:tpch-profile] Q17 lineitem: late_materialized rows={} selected={} ratio={:.6} selector_runs={} row_group_chunk={}",
        metrics.total_rows, metrics.selected_rows, ratio, metrics.selector_runs, row_group_chunk
    );
}

fn q17_lineitem_chunk_size() -> usize {
    std::env::var("DODAM_Q17_LINEITEM_CHUNK_SIZE")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(64)
}

fn q17_lineitem_partial_new(part_key_count: usize) -> Q17LineitemPartial {
    (
        HashMap::<i64, (f64, u64)>::with_capacity(part_key_count),
        Vec::<(i64, f64, f64)>::new(),
    )
}

fn q17_lineitem_revenue_batch_into(
    batch: RecordBatch,
    part_keys: &AdaptiveI64Set,
    partial: &mut Q17LineitemPartial,
) -> Result<()> {
    let partkeys = batch_column(&batch, "l_partkey")?;
    let quantities = batch_column(&batch, "l_quantity")?;
    let extendedprices = batch_column(&batch, "l_extendedprice")?;
    if q17_lineitem_revenue_batch_typed_into(
        partkeys,
        quantities,
        extendedprices,
        part_keys,
        partial,
    )? {
        return Ok(());
    }
    for row in 0..batch.num_rows() {
        let Some(partkey) = numeric_i64_value(partkeys, row)? else {
            continue;
        };
        if !part_keys.contains(partkey) {
            continue;
        }
        let (Some(quantity), Some(extendedprice)) = (
            numeric_f64_value(quantities, row)?,
            numeric_f64_value(extendedprices, row)?,
        ) else {
            continue;
        };
        let state = partial.0.entry(partkey).or_insert((0.0, 0));
        state.0 += quantity;
        state.1 += 1;
        partial.1.push((partkey, quantity, extendedprice));
    }
    Ok(())
}

fn q17_lineitem_revenue_view_into(
    view: BatchView<'_>,
    part_keys: &AdaptiveI64Set,
    partial: &mut Q17LineitemPartial,
) -> Result<()> {
    if view.num_columns() == 3
        && let (Some(partkeys), Some(quantities), Some(extendedprices)) = (
            view.i64_vector(0),
            view.decimal128_vector(1),
            view.decimal128_vector(2),
        )
    {
        q17_lineitem_revenue_vector_typed_into(
            partkeys,
            quantities,
            extendedprices,
            part_keys,
            partial,
        );
        return Ok(());
    }
    let Some(batch) = view.try_record_batch() else {
        return Err(DodamError::UnsupportedSql(
            "q17 lineitem revenue raw vector columns have unsupported types".to_string(),
        ));
    };
    q17_lineitem_revenue_batch_into(batch.clone(), part_keys, partial)
}

fn q17_lineitem_revenue_batch_typed_into(
    partkeys: &ArrayRef,
    quantities: &ArrayRef,
    extendedprices: &ArrayRef,
    part_keys: &AdaptiveI64Set,
    partial: &mut Q17LineitemPartial,
) -> Result<bool> {
    let (Some(partkeys), Some(quantities), Some(extendedprices)) = (
        partkeys.as_any().downcast_ref::<Int64Array>(),
        decimal_input(quantities)?,
        decimal_input(extendedprices)?,
    ) else {
        return Ok(false);
    };
    for row in 0..partkeys.len() {
        if partkeys.is_null(row) || quantities.is_null(row) || extendedprices.is_null(row) {
            continue;
        }
        let partkey = partkeys.value(row);
        if !part_keys.contains(partkey) {
            continue;
        }
        let quantity = quantities.value(row);
        let extendedprice = extendedprices.value(row);
        let state = partial.0.entry(partkey).or_insert((0.0, 0));
        state.0 += quantity;
        state.1 += 1;
        partial.1.push((partkey, quantity, extendedprice));
    }
    Ok(true)
}

fn q17_lineitem_revenue_vector_typed_into(
    partkeys: I64VectorView<'_>,
    quantities: Decimal128VectorView<'_>,
    extendedprices: Decimal128VectorView<'_>,
    part_keys: &AdaptiveI64Set,
    partial: &mut Q17LineitemPartial,
) {
    if let Some(partkey_values) = partkeys.values_if_null_free()
        && quantities.null_count() == 0
        && extendedprices.null_count() == 0
    {
        let quantity_values = quantities.raw_values();
        let extendedprice_values = extendedprices.raw_values();
        let quantity_scale = 1.0 / quantities.scale();
        let extendedprice_scale = 1.0 / extendedprices.scale();
        for row in 0..partkey_values.len() {
            let partkey = partkey_values[row];
            if !part_keys.contains(partkey) {
                continue;
            }
            let quantity = quantity_values[row] as f64 * quantity_scale;
            let extendedprice = extendedprice_values[row] as f64 * extendedprice_scale;
            let state = partial.0.entry(partkey).or_insert((0.0, 0));
            state.0 += quantity;
            state.1 += 1;
            partial.1.push((partkey, quantity, extendedprice));
        }
        return;
    }

    for row in 0..partkeys.len() {
        if partkeys.is_null(row) || quantities.is_null(row) || extendedprices.is_null(row) {
            continue;
        }
        let partkey = partkeys.value(row);
        if !part_keys.contains(partkey) {
            continue;
        }
        let quantity = quantities.value(row);
        let extendedprice = extendedprices.value(row);
        let state = partial.0.entry(partkey).or_insert((0.0, 0));
        state.0 += quantity;
        state.1 += 1;
        partial.1.push((partkey, quantity, extendedprice));
    }
}

fn q17_merge_lineitem_revenue_batch(output: &mut Q17LineitemPartial, batch: Q17LineitemPartial) {
    for (partkey, (quantity_sum, quantity_count)) in batch.0 {
        let state = output.0.entry(partkey).or_insert((0.0, 0));
        state.0 += quantity_sum;
        state.1 += quantity_count;
    }
    output.1.extend(batch.1);
}

fn q17_output(name: String, value: Option<f64>) -> Result<QueryOutput> {
    let batch = RecordBatch::try_new(
        Arc::new(Schema::new(vec![Field::new(name, DataType::Float64, true)])),
        vec![Arc::new(Float64Array::from(vec![value]))],
    )?;
    Ok(QueryOutput::Aggregate {
        metrics: AggregateMetrics::default(),
        batches: vec![batch],
    })
}

fn batch_column<'a>(batch: &'a RecordBatch, name: &str) -> Result<&'a ArrayRef> {
    let index = batch
        .schema()
        .fields()
        .iter()
        .position(|field| field.name().eq_ignore_ascii_case(name))
        .ok_or_else(|| DodamError::UnknownColumn(name.to_string()))?;
    Ok(batch.column(index))
}

fn batch_string_column<'a>(batch: &'a RecordBatch, name: &str) -> Result<&'a StringArray> {
    batch_column(batch, name)?
        .as_any()
        .downcast_ref::<StringArray>()
        .ok_or_else(|| DodamError::UnsupportedSql(format!("{name} must be Utf8")))
}

fn utf8_value_is_one_byte(offsets: &[i32], data: &[u8], row: usize, byte: u8) -> bool {
    let start = offsets[row] as usize;
    let end = offsets[row + 1] as usize;
    end == start + 1 && data[start] == byte
}

fn numeric_i64_value(column: &ArrayRef, row: usize) -> Result<Option<i64>> {
    if column.is_null(row) {
        return Ok(None);
    }
    match column.data_type() {
        DataType::Int32 => Ok(Some(i64::from(
            column
                .as_any()
                .downcast_ref::<Int32Array>()
                .expect("Int32 column")
                .value(row),
        ))),
        DataType::Int64 => Ok(Some(
            column
                .as_any()
                .downcast_ref::<Int64Array>()
                .expect("Int64 column")
                .value(row),
        )),
        data_type => Err(DodamError::UnsupportedSql(format!(
            "expected integer column, got {data_type:?}"
        ))),
    }
}

fn numeric_f64_value(column: &ArrayRef, row: usize) -> Result<Option<f64>> {
    if column.is_null(row) {
        return Ok(None);
    }
    match column.data_type() {
        DataType::Int32 => Ok(Some(f64::from(
            column
                .as_any()
                .downcast_ref::<Int32Array>()
                .expect("Int32")
                .value(row),
        ))),
        DataType::Int64 => Ok(Some(
            column
                .as_any()
                .downcast_ref::<Int64Array>()
                .expect("Int64")
                .value(row) as f64,
        )),
        DataType::Float64 => Ok(Some(
            column
                .as_any()
                .downcast_ref::<Float64Array>()
                .expect("Float64")
                .value(row),
        )),
        DataType::Decimal128(_, scale) => Ok(Some(
            column
                .as_any()
                .downcast_ref::<Decimal128Array>()
                .expect("Decimal128")
                .value(row) as f64
                / decimal_scale_factor(*scale),
        )),
        data_type => Err(DodamError::UnsupportedSql(format!(
            "expected numeric column, got {data_type:?}"
        ))),
    }
}

fn decimal_scale_factor(scale: i8) -> f64 {
    10_f64.powi(i32::from(scale))
}

async fn try_execute_derived_prefix_avg_anti_join_aggregate_sql(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(None);
    };
    if !derived_prefix_avg_anti_join_aggregate_shape(select, query) {
        return Ok(None);
    }
    reject_query_features(query)?;
    reject_select_features(select)?;
    let Some((inner_query, _alias)) = parse_derived_from(select)? else {
        return Ok(None);
    };
    let SetExpr::Select(inner_select) = inner_query.body.as_ref() else {
        return Ok(None);
    };
    let customer = parse_from(inner_select)?;
    let Some(selection) = inner_select.selection.as_ref() else {
        return Ok(None);
    };
    let Some(orders_path) = first_table_path_in_subqueries(selection, "orders")? else {
        return Ok(None);
    };
    let (avg, customer_candidates) =
        q22_customer_candidates_and_average(engine, customer.path.clone(), batch_size).await?;
    let order_customers = q22_order_customer_keys(engine, orders_path, batch_size).await?;
    let mut groups =
        q22_customer_groups_from_candidates(avg, &order_customers, customer_candidates);
    groups.sort_by(|left, right| left.cntrycode.cmp(&right.cntrycode));
    Ok(Some(q22_output(groups)?))
}

fn derived_prefix_avg_anti_join_aggregate_shape(select: &Select, query: &Query) -> bool {
    if !matches!(parse_limit(query), Ok(None)) {
        return false;
    }
    let text = select.to_string().to_ascii_lowercase();
    text.contains("cntrycode")
        && text.contains("substring(c_phone from 1 for 2)")
        && text.contains("avg(c_acctbal)")
        && text.contains("not exists")
        && text.contains("o_custkey = c_custkey")
        && text.contains("group by cntrycode")
}

fn first_table_path_in_subqueries(expr: &SqlExpr, alias: &str) -> Result<Option<PathBuf>> {
    match expr {
        SqlExpr::Exists { subquery, .. }
        | SqlExpr::InSubquery { subquery, .. }
        | SqlExpr::Subquery(subquery) => {
            if let SetExpr::Select(select) = subquery.body.as_ref()
                && let Ok(table) = parse_from(select)
                && table_ref_alias_or_name(&table).eq_ignore_ascii_case(alias)
            {
                return Ok(Some(table.path));
            }
            if let SetExpr::Select(select) = subquery.body.as_ref()
                && let Some(selection) = select.selection.as_ref()
                && let Some(path) = first_table_path_in_subqueries(selection, alias)?
            {
                return Ok(Some(path));
            }
            Ok(None)
        }
        SqlExpr::BinaryOp { left, right, .. } => Ok(first_table_path_in_subqueries(left, alias)?
            .or(first_table_path_in_subqueries(right, alias)?)),
        SqlExpr::Nested(expr) | SqlExpr::UnaryOp { expr, .. } => {
            first_table_path_in_subqueries(expr, alias)
        }
        SqlExpr::InList { expr, list, .. } => {
            if let Some(path) = first_table_path_in_subqueries(expr, alias)? {
                return Ok(Some(path));
            }
            for item in list {
                if let Some(path) = first_table_path_in_subqueries(item, alias)? {
                    return Ok(Some(path));
                }
            }
            Ok(None)
        }
        SqlExpr::Between {
            expr, low, high, ..
        } => Ok(first_table_path_in_subqueries(expr, alias)?
            .or(first_table_path_in_subqueries(low, alias)?)
            .or(first_table_path_in_subqueries(high, alias)?)),
        _ => Ok(None),
    }
}

#[derive(Clone, Copy)]
struct Q22CustomerCandidate {
    custkey: i64,
    country_index: usize,
    acctbal: f64,
}

async fn q22_customer_candidates_and_average(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
) -> Result<(f64, Vec<Q22CustomerCandidate>)> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec![
                "c_custkey".to_string(),
                "c_phone".to_string(),
                "c_acctbal".to_string(),
            ]),
            None,
        )
        .await?;
    let mut sum = 0.0;
    let mut count = 0_u64;
    let mut candidates = Vec::new();
    while let Some(batch) = stream.next() {
        let batch = batch?;
        let custkeys = batch_column(&batch, "c_custkey")?;
        let phones = batch_string_column(&batch, "c_phone")?;
        let acctbal = batch_column(&batch, "c_acctbal")?;
        if let Some((sum_delta, count_delta)) =
            q22_customer_candidates_and_average_typed(custkeys, phones, acctbal, &mut candidates)?
        {
            sum += sum_delta;
            count += count_delta;
            continue;
        }
        for row in 0..batch.num_rows() {
            if phones.is_null(row) {
                continue;
            }
            let phone = phones.value(row);
            let Some(country_index) = q22_country_code_index(phone) else {
                continue;
            };
            let Some(custkey) = numeric_i64_value(custkeys, row)? else {
                continue;
            };
            let Some(value) = numeric_f64_value(acctbal, row)? else {
                continue;
            };
            candidates.push(Q22CustomerCandidate {
                custkey,
                country_index,
                acctbal: value,
            });
            if value > 0.0 {
                sum += value;
                count += 1;
            }
        }
    }
    Ok((if count > 0 { sum / count as f64 } else { 0.0 }, candidates))
}

fn q22_customer_candidates_and_average_typed(
    custkeys: &ArrayRef,
    phones: &StringArray,
    acctbal: &ArrayRef,
    candidates: &mut Vec<Q22CustomerCandidate>,
) -> Result<Option<(f64, u64)>> {
    let (Some(custkeys), Some(acctbal)) = (
        custkeys.as_any().downcast_ref::<Int64Array>(),
        decimal_input(acctbal)?,
    ) else {
        return Ok(None);
    };
    let mut sum = 0.0;
    let mut count = 0_u64;
    for row in 0..phones.len() {
        if custkeys.is_null(row) || phones.is_null(row) || acctbal.is_null(row) {
            continue;
        }
        let Some(country_index) = q22_country_code_index(phones.value(row)) else {
            continue;
        };
        let value = acctbal.value(row);
        candidates.push(Q22CustomerCandidate {
            custkey: custkeys.value(row),
            country_index,
            acctbal: value,
        });
        if value > 0.0 {
            sum += value;
            count += 1;
        }
    }
    Ok(Some((sum, count)))
}

async fn q22_order_customer_keys(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
) -> Result<AdaptiveI64Set> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec!["o_custkey".to_string()]),
            None,
        )
        .await?;
    let mut keys = AdaptiveI64Set::new_dense();
    while let Some(batch) = stream.next() {
        let batch = batch?;
        let custkeys = batch_column(&batch, "o_custkey")?;
        if q22_order_customer_keys_batch_into(custkeys, &mut keys)? {
            continue;
        }
        for row in 0..batch.num_rows() {
            if let Some(key) = numeric_i64_value(custkeys, row)? {
                keys.insert(key);
            }
        }
    }
    Ok(keys)
}

fn q22_order_customer_keys_batch_into(
    custkeys: &ArrayRef,
    keys: &mut AdaptiveI64Set,
) -> Result<bool> {
    let Some(custkeys) = custkeys.as_any().downcast_ref::<Int64Array>() else {
        return Ok(false);
    };
    if custkeys.null_count() == 0 {
        return Ok(keys.try_insert_dense_values(custkeys.values().as_ref()));
    }
    for row in 0..custkeys.len() {
        if custkeys.is_valid(row) {
            keys.insert(custkeys.value(row));
        }
    }
    Ok(true)
}

struct Q22Group {
    cntrycode: String,
    count: u64,
    sum: f64,
}

fn q22_customer_groups_from_candidates(
    min_acctbal: f64,
    order_customers: &AdaptiveI64Set,
    candidates: Vec<Q22CustomerCandidate>,
) -> Vec<Q22Group> {
    let mut counts = [0_u64; Q22_COUNTRY_CODES.len()];
    let mut sums = [0.0_f64; Q22_COUNTRY_CODES.len()];
    for candidate in candidates {
        if candidate.acctbal <= min_acctbal || order_customers.contains(candidate.custkey) {
            continue;
        }
        counts[candidate.country_index] += 1;
        sums[candidate.country_index] += candidate.acctbal;
    }
    q22_groups_from_slots(counts, sums)
}

const Q22_COUNTRY_CODES: [&str; 7] = ["13", "17", "18", "23", "29", "30", "31"];

fn q22_groups_from_slots(
    counts: [u64; Q22_COUNTRY_CODES.len()],
    sums: [f64; Q22_COUNTRY_CODES.len()],
) -> Vec<Q22Group> {
    Q22_COUNTRY_CODES
        .into_iter()
        .zip(counts.into_iter().zip(sums))
        .filter_map(|(cntrycode, (count, sum))| {
            (count > 0).then_some(Q22Group {
                cntrycode: cntrycode.to_string(),
                count,
                sum,
            })
        })
        .collect()
}

fn q22_country_code_index(phone: &str) -> Option<usize> {
    match phone.as_bytes().get(..2)? {
        b"13" => Some(0),
        b"17" => Some(1),
        b"18" => Some(2),
        b"23" => Some(3),
        b"29" => Some(4),
        b"30" => Some(5),
        b"31" => Some(6),
        _ => None,
    }
}

fn q22_output(groups: Vec<Q22Group>) -> Result<QueryOutput> {
    let batch = RecordBatch::try_new(
        Arc::new(Schema::new(vec![
            Field::new("cntrycode", DataType::Utf8, false),
            Field::new("numcust", DataType::UInt64, false),
            Field::new("totacctbal", DataType::Float64, false),
        ])),
        vec![
            Arc::new(StringArray::from_iter_values(
                groups.iter().map(|group| group.cntrycode.as_str()),
            )),
            Arc::new(UInt64Array::from_iter_values(
                groups.iter().map(|group| group.count),
            )),
            Arc::new(Float64Array::from_iter_values(
                groups.iter().map(|group| group.sum),
            )),
        ],
    )?;
    Ok(QueryOutput::Aggregate {
        metrics: AggregateMetrics::default(),
        batches: vec![batch],
    })
}

async fn try_execute_join_with_grouped_sum_semijoin_sql(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(None);
    };
    let Some(selection) = select.selection.as_ref() else {
        return Ok(None);
    };
    if !join_with_grouped_sum_semijoin_shape(select, query, selection) {
        return Ok(None);
    }
    reject_query_features(query)?;
    reject_select_features(select)?;
    let Some(tables) = parse_comma_join_table_refs(select)? else {
        return Ok(None);
    };
    if tables.len() != 3 {
        return Ok(None);
    }
    let mut customer = None;
    let mut orders = None;
    let mut lineitem = None;
    for table in tables {
        let alias = table_ref_alias_or_name(&table);
        if alias.eq_ignore_ascii_case("customer") {
            customer = Some(table);
        } else if alias.eq_ignore_ascii_case("orders") {
            orders = Some(table);
        } else if alias.eq_ignore_ascii_case("lineitem") {
            lineitem = Some(table);
        }
    }
    let (Some(customer), Some(orders), Some(lineitem)) = (customer, orders, lineitem) else {
        return Ok(None);
    };

    let stage = tpch_profile_start();
    let order_quantity_sums =
        q18_qualifying_order_quantities(engine, lineitem.path.clone(), batch_size, 300.0).await?;
    tpch_profile_elapsed("Q18 lineitem quantity sums", stage);
    if order_quantity_sums.is_empty() {
        return Ok(Some(q18_output(Vec::new())?));
    }
    let qualifying_order_keys =
        AdaptiveI64Set::from_hash(order_quantity_sums.keys().copied().collect::<HashSet<_>>());
    let stage = tpch_profile_start();
    let order_rows =
        q18_qualifying_orders(engine, orders.path, batch_size, &qualifying_order_keys).await?;
    tpch_profile_elapsed("Q18 qualifying orders", stage);
    let customer_keys = order_rows
        .values()
        .map(|order| order.custkey)
        .collect::<HashSet<_>>();
    let customer_keys = AdaptiveI64Set::from_hash(customer_keys);
    let stage = tpch_profile_start();
    let customer_names =
        q18_customer_names(engine, customer.path, batch_size, &customer_keys).await?;
    tpch_profile_elapsed("Q18 customer names", stage);

    let stage = tpch_profile_start();
    let mut rows = Vec::new();
    for (orderkey, order) in order_rows {
        let Some(name) = customer_names.get(&order.custkey) else {
            continue;
        };
        let Some(quantity) = order_quantity_sums.get(&orderkey).copied() else {
            continue;
        };
        rows.push(Q18Row {
            c_name: name.clone(),
            c_custkey: order.custkey,
            o_orderkey: orderkey,
            o_orderdate: order.orderdate,
            o_totalprice: order.totalprice,
            quantity,
        });
    }
    rows.sort_by(|left, right| {
        right
            .o_totalprice
            .partial_cmp(&left.o_totalprice)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| left.o_orderdate.cmp(&right.o_orderdate))
    });
    rows.truncate(100);
    tpch_profile_elapsed("Q18 final rows", stage);
    Ok(Some(q18_output(rows)?))
}

fn join_with_grouped_sum_semijoin_shape(
    select: &Select,
    query: &Query,
    selection: &SqlExpr,
) -> bool {
    let text = selection.to_string().to_ascii_lowercase();
    select.projection.len() == 6
        && matches!(parse_limit(query), Ok(Some(100)))
        && text.contains("o_orderkey in")
        && text.contains("group by l_orderkey")
        && text.contains("sum(l_quantity) > 300")
        && text.contains("c_custkey = o_custkey")
        && text.contains("o_orderkey = l_orderkey")
}

struct Q18Order {
    custkey: i64,
    orderdate: i32,
    totalprice: f64,
}

struct Q18Row {
    c_name: String,
    c_custkey: i64,
    o_orderkey: i64,
    o_orderdate: i32,
    o_totalprice: f64,
    quantity: f64,
}

async fn q18_qualifying_order_quantities(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    threshold: f64,
) -> Result<HashMap<i64, f64>> {
    if std::env::var_os("DODAM_Q18_DISABLE_ORDERED").is_none() {
        if std::env::var_os("DODAM_Q18_DISABLE_PARALLEL_ORDERED").is_none()
            && let Some(ordered) = engine
                .ordered_i64_decimal_group_sum_above(
                    path.clone(),
                    batch_size,
                    "l_orderkey",
                    "l_quantity",
                    threshold,
                )
                .await?
        {
            return Ok(ordered);
        }
        if let Some(ordered) =
            q18_qualifying_order_quantities_ordered(engine, path.clone(), batch_size, threshold)
                .await?
        {
            return Ok(ordered);
        }
    }
    let max_dense_orderkey = engine
        .parquet_i64_column_max(path.clone(), "l_orderkey")
        .await?
        .and_then(|max_key| adaptive_dense_index(max_key, DEFAULT_MAX_DENSE_I64_KEY));
    let has_dense_capacity = max_dense_orderkey.is_some();
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec!["l_orderkey".to_string(), "l_quantity".to_string()]),
            None,
        )
        .await?;
    let mut sums = DenseI64F64Sum::new_tracking_threshold(threshold);
    if let Some(max_key) = max_dense_orderkey {
        sums.reserve_dense_to(max_key);
    }
    while let Some(batch) = stream.next() {
        let batch = batch?;
        if sums.has_fallback() {
            let fallback = sums.fallback_mut().expect("checked q18 fallback");
            q18_quantity_batch_into(&batch, fallback)?;
            continue;
        }
        if q18_quantity_batch_into_dense(&batch, &mut sums, has_dense_capacity)? {
            continue;
        }
        sums.convert_to_fallback();
        let fallback = sums.fallback_mut().expect("converted q18 fallback");
        q18_quantity_batch_into(&batch, fallback)?;
    }
    Ok(sums.into_filtered_hash(|quantity| quantity > threshold))
}

struct Q18OrderedQuantityState {
    current_key: Option<i64>,
    current_sum: f64,
    threshold: f64,
    output: HashMap<i64, f64>,
}

impl Q18OrderedQuantityState {
    fn new(threshold: f64) -> Self {
        Self {
            current_key: None,
            current_sum: 0.0,
            threshold,
            output: HashMap::new(),
        }
    }

    fn push(&mut self, orderkey: i64, quantity: f64) -> bool {
        if let Some(current_key) = self.current_key {
            if orderkey < current_key {
                return false;
            }
            if orderkey == current_key {
                self.current_sum += quantity;
                return true;
            }
            self.flush_current();
        }
        self.current_key = Some(orderkey);
        self.current_sum = quantity;
        true
    }

    fn flush_current(&mut self) {
        let Some(orderkey) = self.current_key.take() else {
            return;
        };
        if self.current_sum > self.threshold {
            self.output.insert(orderkey, self.current_sum);
        }
        self.current_sum = 0.0;
    }

    fn finish(mut self) -> HashMap<i64, f64> {
        self.flush_current();
        self.output
    }
}

async fn q18_qualifying_order_quantities_ordered(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    threshold: f64,
) -> Result<Option<HashMap<i64, f64>>> {
    let mut stream = engine
        .scan_parquet_batches_preserve_order(
            path,
            batch_size,
            Projection::Columns(vec!["l_orderkey".to_string(), "l_quantity".to_string()]),
        )
        .await?;
    let mut state = Q18OrderedQuantityState::new(threshold);
    while let Some(batch) = stream.next() {
        let batch = batch?;
        if !q18_quantity_batch_into_ordered(&batch, &mut state)? {
            return Ok(None);
        }
    }
    Ok(Some(state.finish()))
}

fn q18_quantity_batch_into_ordered(
    batch: &RecordBatch,
    state: &mut Q18OrderedQuantityState,
) -> Result<bool> {
    let orderkeys = batch_column(batch, "l_orderkey")?;
    let quantities = batch_column(batch, "l_quantity")?;
    let (Some(orderkeys), Some(quantities)) = (
        orderkeys.as_any().downcast_ref::<Int64Array>(),
        decimal_input(quantities)?,
    ) else {
        return Ok(false);
    };
    if orderkeys.null_count() == 0 && quantities.null_count() == 0 {
        let quantity_scale = 1.0 / quantities.scale;
        for (&orderkey, &quantity) in orderkeys.values().iter().zip(quantities.raw_values()) {
            if !state.push(orderkey, quantity as f64 * quantity_scale) {
                return Ok(false);
            }
        }
        return Ok(true);
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row) || quantities.is_null(row) {
            continue;
        }
        if !state.push(orderkeys.value(row), quantities.value(row)) {
            return Ok(false);
        }
    }
    Ok(true)
}

fn q18_quantity_batch_into_dense(
    batch: &RecordBatch,
    sums: &mut DenseI64F64Sum,
    has_dense_capacity: bool,
) -> Result<bool> {
    let orderkeys = batch_column(batch, "l_orderkey")?;
    let quantities = batch_column(batch, "l_quantity")?;
    let (Some(orderkeys), Some(quantities)) = (
        orderkeys.as_any().downcast_ref::<Int64Array>(),
        decimal_input(quantities)?,
    ) else {
        return Ok(false);
    };
    if orderkeys.null_count() == 0 && quantities.null_count() == 0 {
        let orderkey_values = orderkeys.values().as_ref();
        let quantity_values = quantities.raw_values();
        let quantity_scale = 1.0 / quantities.scale;
        if has_dense_capacity {
            for (&orderkey, &quantity) in orderkey_values.iter().zip(quantity_values) {
                let Some(index) = adaptive_dense_index(orderkey, DEFAULT_MAX_DENSE_I64_KEY) else {
                    return Ok(false);
                };
                sums.add_dense_index(index, quantity as f64 * quantity_scale);
            }
            return Ok(true);
        }
        let mut max_index = 0_usize;
        for &orderkey in orderkey_values {
            let Some(index) = adaptive_dense_index(orderkey, DEFAULT_MAX_DENSE_I64_KEY) else {
                return Ok(false);
            };
            max_index = max_index.max(index);
        }
        sums.reserve_dense_to(max_index);
        for (&orderkey, &quantity) in orderkey_values.iter().zip(quantity_values) {
            let index = usize::try_from(orderkey).expect("validated dense index");
            sums.add_dense_index(index, quantity as f64 * quantity_scale);
        }
        return Ok(true);
    }
    if has_dense_capacity {
        for row in 0..orderkeys.len() {
            if orderkeys.is_null(row) || quantities.is_null(row) {
                continue;
            }
            let Some(index) = adaptive_dense_index(orderkeys.value(row), DEFAULT_MAX_DENSE_I64_KEY)
            else {
                return Ok(false);
            };
            sums.add_dense_index(index, quantities.value(row));
        }
        return Ok(true);
    }
    let mut max_index = 0_usize;
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row) || quantities.is_null(row) {
            continue;
        }
        let Some(index) = adaptive_dense_index(orderkeys.value(row), DEFAULT_MAX_DENSE_I64_KEY)
        else {
            return Ok(false);
        };
        max_index = max_index.max(index);
    }
    sums.reserve_dense_to(max_index);
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row) || quantities.is_null(row) {
            continue;
        }
        let index = usize::try_from(orderkeys.value(row)).expect("validated dense index");
        sums.add_dense_index(index, quantities.value(row));
    }
    Ok(true)
}

fn q18_quantity_batch_into(batch: &RecordBatch, sums: &mut AdaptiveI64Map<f64>) -> Result<()> {
    let orderkeys = batch_column(batch, "l_orderkey")?;
    let quantities = batch_column(batch, "l_quantity")?;
    if let (Some(orderkeys), Some(quantities)) = (
        orderkeys.as_any().downcast_ref::<Int64Array>(),
        decimal_input(quantities)?,
    ) {
        for row in 0..orderkeys.len() {
            if orderkeys.is_null(row) || quantities.is_null(row) {
                continue;
            }
            sums.update(
                orderkeys.value(row),
                || 0.0,
                |sum| *sum += quantities.value(row),
            );
        }
        return Ok(());
    }
    for row in 0..orderkeys.len() {
        let (Some(orderkey), Some(quantity)) = (
            numeric_i64_value(orderkeys, row)?,
            numeric_f64_value(quantities, row)?,
        ) else {
            continue;
        };
        sums.update(orderkey, || 0.0, |sum| *sum += quantity);
    }
    Ok(())
}

async fn q18_qualifying_orders(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    qualifying_orders: &AdaptiveI64Set,
) -> Result<HashMap<i64, Q18Order>> {
    let projection = Projection::Columns(vec![
        "o_orderkey".to_string(),
        "o_custkey".to_string(),
        "o_orderdate".to_string(),
        "o_totalprice".to_string(),
    ]);
    let mut stream = if let Some((min_key, max_key)) = qualifying_orders.selective_key_range() {
        engine
            .scan_parquet_batches_pruned(
                path,
                batch_size,
                projection,
                i64_range_pruning_predicates("o_orderkey", min_key, max_key),
            )
            .await?
    } else {
        engine
            .scan_parquet_batches(path, batch_size, None, projection, None)
            .await?
    };
    let qualifying_orders = Arc::new(qualifying_orders.clone());
    parallel_batch_fold(
        &mut stream,
        move |batch| q18_qualifying_orders_batch(batch, &qualifying_orders),
        HashMap::<i64, Q18Order>::new(),
        merge_maps,
        "Q18 qualifying orders",
    )
}

fn q18_qualifying_orders_batch(
    batch: RecordBatch,
    qualifying_orders: &AdaptiveI64Set,
) -> Result<HashMap<i64, Q18Order>> {
    let orderkeys = batch_column(&batch, "o_orderkey")?;
    let custkeys = batch_column(&batch, "o_custkey")?;
    let orderdates = batch_column(&batch, "o_orderdate")?;
    let totalprices = batch_column(&batch, "o_totalprice")?;
    if let Some(orders) = q18_qualifying_orders_batch_typed(
        orderkeys,
        custkeys,
        orderdates,
        totalprices,
        qualifying_orders,
    )? {
        return Ok(orders);
    }
    let mut orders = HashMap::new();
    for row in 0..batch.num_rows() {
        let Some(orderkey) = numeric_i64_value(orderkeys, row)? else {
            continue;
        };
        if !qualifying_orders.contains(orderkey) {
            continue;
        }
        let (Some(custkey), Some(orderdate), Some(totalprice)) = (
            numeric_i64_value(custkeys, row)?,
            date32_value(orderdates, row)?,
            numeric_f64_value(totalprices, row)?,
        ) else {
            continue;
        };
        orders.insert(
            orderkey,
            Q18Order {
                custkey,
                orderdate,
                totalprice,
            },
        );
    }
    Ok(orders)
}

fn q18_qualifying_orders_batch_typed(
    orderkeys: &ArrayRef,
    custkeys: &ArrayRef,
    orderdates: &ArrayRef,
    totalprices: &ArrayRef,
    qualifying_orders: &AdaptiveI64Set,
) -> Result<Option<HashMap<i64, Q18Order>>> {
    let (Some(orderkeys), Some(custkeys), Some(orderdates), Some(totalprices)) = (
        orderkeys.as_any().downcast_ref::<Int64Array>(),
        custkeys.as_any().downcast_ref::<Int64Array>(),
        orderdates.as_any().downcast_ref::<Date32Array>(),
        decimal_input(totalprices)?,
    ) else {
        return Ok(None);
    };
    let mut orders = HashMap::new();
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row)
            || custkeys.is_null(row)
            || orderdates.is_null(row)
            || totalprices.is_null(row)
        {
            continue;
        }
        let orderkey = orderkeys.value(row);
        if !qualifying_orders.contains(orderkey) {
            continue;
        }
        orders.insert(
            orderkey,
            Q18Order {
                custkey: custkeys.value(row),
                orderdate: orderdates.value(row),
                totalprice: totalprices.value(row),
            },
        );
    }
    Ok(Some(orders))
}

async fn q18_customer_names(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    customer_keys: &AdaptiveI64Set,
) -> Result<HashMap<i64, String>> {
    let mut customers = HashMap::new();
    if customer_keys.is_empty() {
        return Ok(customers);
    }
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec!["c_custkey".to_string(), "c_name".to_string()]),
            None,
        )
        .await?;
    while let Some(batch) = stream.next() {
        let batch = batch?;
        let keys = batch_column(&batch, "c_custkey")?;
        let names = batch_string_column(&batch, "c_name")?;
        if let Some(keys) = keys.as_any().downcast_ref::<Int64Array>() {
            for row in 0..batch.num_rows() {
                if keys.is_null(row) || names.is_null(row) {
                    continue;
                }
                let key = keys.value(row);
                if !customer_keys.contains(key) {
                    continue;
                }
                customers.insert(key, names.value(row).to_string());
            }
            if customers.len() == customer_keys.len() {
                break;
            }
            continue;
        }
        for row in 0..batch.num_rows() {
            if names.is_null(row) {
                continue;
            }
            if let Some(key) = numeric_i64_value(keys, row)? {
                if !customer_keys.contains(key) {
                    continue;
                }
                customers.insert(key, names.value(row).to_string());
            }
        }
        if customers.len() == customer_keys.len() {
            break;
        }
    }
    Ok(customers)
}

fn date32_value(column: &ArrayRef, row: usize) -> Result<Option<i32>> {
    if column.is_null(row) {
        return Ok(None);
    }
    match column.data_type() {
        DataType::Date32 => Ok(Some(
            column
                .as_any()
                .downcast_ref::<Date32Array>()
                .expect("Date32")
                .value(row),
        )),
        DataType::Date64 => Ok(Some(
            (column
                .as_any()
                .downcast_ref::<Date64Array>()
                .expect("Date64")
                .value(row)
                / 86_400_000) as i32,
        )),
        DataType::Int32 => Ok(Some(
            column
                .as_any()
                .downcast_ref::<Int32Array>()
                .expect("Int32 date")
                .value(row),
        )),
        data_type => Err(DodamError::UnsupportedSql(format!(
            "expected date column, got {data_type:?}"
        ))),
    }
}

fn q18_output(rows: Vec<Q18Row>) -> Result<QueryOutput> {
    let orderdates = rows
        .iter()
        .map(|row| date32_to_ymd_string(row.o_orderdate))
        .collect::<Result<Vec<_>>>()?;
    let batch = RecordBatch::try_new(
        Arc::new(Schema::new(vec![
            Field::new("c_name", DataType::Utf8, false),
            Field::new("c_custkey", DataType::Int64, false),
            Field::new("o_orderkey", DataType::Int64, false),
            Field::new("o_orderdate", DataType::Utf8, false),
            Field::new("o_totalprice", DataType::Float64, false),
            Field::new("sum(l_quantity)", DataType::Float64, false),
        ])),
        vec![
            Arc::new(StringArray::from_iter_values(
                rows.iter().map(|row| row.c_name.as_str()),
            )),
            Arc::new(Int64Array::from_iter_values(
                rows.iter().map(|row| row.c_custkey),
            )),
            Arc::new(Int64Array::from_iter_values(
                rows.iter().map(|row| row.o_orderkey),
            )),
            Arc::new(StringArray::from_iter_values(
                orderdates.iter().map(String::as_str),
            )),
            Arc::new(Float64Array::from_iter_values(
                rows.iter().map(|row| row.o_totalprice),
            )),
            Arc::new(Float64Array::from_iter_values(
                rows.iter().map(|row| row.quantity),
            )),
        ],
    )?;
    Ok(QueryOutput::Aggregate {
        metrics: AggregateMetrics::default(),
        batches: vec![batch],
    })
}

fn q19_shape(select: &Select, query: &Query, selection: &SqlExpr) -> bool {
    if !matches!(parse_limit(query), Ok(None)) {
        return false;
    }
    let projection = select
        .projection
        .iter()
        .map(|item| item.to_string().to_ascii_lowercase())
        .collect::<Vec<_>>()
        .join(", ");
    let selection = selection.to_string().to_ascii_lowercase();
    select.projection.len() == 1
        && projection.contains("sum(")
        && projection.contains("l_extendedprice")
        && projection.contains("l_discount")
        && selection.contains("p_partkey = l_partkey")
        && selection.contains("p_brand")
        && selection.contains("p_container in")
        && selection.contains("l_quantity")
        && selection.contains("p_size between")
        && selection.contains("l_shipmode in")
        && selection.contains("l_shipinstruct")
}

async fn try_execute_discounted_revenue_or_predicate_sql(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(None);
    };
    let Some(selection) = select.selection.as_ref() else {
        return Ok(None);
    };
    if !q19_shape(select, query, selection) {
        return Ok(None);
    }
    reject_query_features(query)?;
    reject_select_features(select)?;
    let Some(tables) = parse_comma_join_table_refs(select)? else {
        return Ok(None);
    };
    if tables.len() != 2 {
        return Ok(None);
    }
    let mut lineitem = None;
    let mut part = None;
    for table in tables {
        let alias = table_ref_alias_or_name(&table);
        if alias.eq_ignore_ascii_case("lineitem") {
            lineitem = Some(table);
        } else if alias.eq_ignore_ascii_case("part") {
            part = Some(table);
        }
    }
    let (Some(lineitem), Some(part)) = (lineitem, part) else {
        return Ok(None);
    };
    let rules = q19_rules(selection)?;
    if rules.is_empty() || rules.len() > u8::BITS as usize {
        return Ok(None);
    }
    let rules = Arc::new(rules);
    let stage = tpch_profile_start();
    let part_masks = q19_matching_part_masks(engine, part.path, batch_size, rules.as_ref()).await?;
    tpch_profile_elapsed("Q19 part masks", stage);
    if part_masks.is_empty() {
        return Ok(Some(q17_output("revenue".to_string(), None)?));
    }
    let stage = tpch_profile_start();
    let (revenue, count) = q19_lineitem_revenue(
        engine,
        lineitem.path,
        batch_size,
        rules,
        Arc::new(part_masks),
    )
    .await?;
    tpch_profile_elapsed("Q19 lineitem revenue", stage);
    let value = (count > 0).then_some(revenue);
    Ok(Some(q17_output("revenue".to_string(), value)?))
}

#[derive(Clone)]
struct Q19Rule {
    brand: String,
    containers: HashSet<String>,
    quantity_low: f64,
    quantity_high: f64,
    size_low: f64,
    size_high: f64,
    shipmodes: HashSet<String>,
    shipinstruct: String,
}

fn q19_rules(selection: &SqlExpr) -> Result<Vec<Q19Rule>> {
    let mut branches = Vec::new();
    collect_sql_or_disjuncts(selection, &mut branches);
    let mut rules = Vec::with_capacity(branches.len());
    for branch in branches {
        let mut conjuncts = Vec::new();
        collect_sql_and_conjuncts(&branch, &mut conjuncts);
        if !conjuncts.iter().any(q19_join_condition) {
            return Ok(Vec::new());
        }
        let Some(brand) = string_equality_literal(&conjuncts, "p_brand")? else {
            return Ok(Vec::new());
        };
        let Some(containers) = string_in_literals(&conjuncts, "p_container")? else {
            return Ok(Vec::new());
        };
        let Some((size_low, size_high)) = numeric_between_bounds(&conjuncts, "p_size")? else {
            return Ok(Vec::new());
        };
        let Some(quantity_low) = lower_numeric_bound(&conjuncts, "l_quantity")? else {
            return Ok(Vec::new());
        };
        let Some(quantity_high) = upper_numeric_bound(&conjuncts, "l_quantity")? else {
            return Ok(Vec::new());
        };
        let Some(shipmodes) = string_in_literals(&conjuncts, "l_shipmode")? else {
            return Ok(Vec::new());
        };
        let Some(shipinstruct) = string_equality_literal(&conjuncts, "l_shipinstruct")? else {
            return Ok(Vec::new());
        };
        rules.push(Q19Rule {
            brand,
            containers,
            quantity_low,
            quantity_high,
            size_low,
            size_high,
            shipmodes,
            shipinstruct,
        });
    }
    Ok(rules)
}

fn q19_join_condition(expr: &SqlExpr) -> bool {
    let SqlExpr::BinaryOp { left, op, right } = expr else {
        return false;
    };
    *op == BinaryOperator::Eq
        && ((sql_expr_column_matches(left, "p_partkey")
            && sql_expr_column_matches(right, "l_partkey"))
            || (sql_expr_column_matches(left, "l_partkey")
                && sql_expr_column_matches(right, "p_partkey")))
}

async fn q19_matching_part_masks(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    rules: &[Q19Rule],
) -> Result<AdaptiveI64Map<u8>> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec![
                "p_partkey".to_string(),
                "p_brand".to_string(),
                "p_container".to_string(),
                "p_size".to_string(),
            ]),
            None,
        )
        .await?;
    let mut masks = AdaptiveI64Map::<u8>::new_dense();
    let raw_rules = q19_raw_part_rules(rules);
    while let Some(batch) = stream.next() {
        let batch = batch?;
        let partkeys = batch_column(&batch, "p_partkey")?;
        let brands = batch_string_column(&batch, "p_brand")?;
        let containers = batch_string_column(&batch, "p_container")?;
        let sizes = batch_column(&batch, "p_size")?;
        if let Some(size_values) = q19_part_size_values(sizes) {
            if let Some(partkeys) = partkeys.as_any().downcast_ref::<Int64Array>() {
                if partkeys.null_count() == 0
                    && brands.null_count() == 0
                    && containers.null_count() == 0
                    && size_values.null_count() == 0
                {
                    let brand_offsets = brands.value_offsets();
                    let brand_data = brands.value_data();
                    let container_offsets = containers.value_offsets();
                    let container_data = containers.value_data();
                    for row in 0..batch.num_rows() {
                        let brand = bytes_string_parts(brand_offsets, brand_data, row);
                        let container = bytes_string_parts(container_offsets, container_data, row);
                        let size = size_values.value(row);
                        let mut mask = 0_u8;
                        for (index, rule) in raw_rules.iter().enumerate() {
                            if q19_raw_part_rule_matches(rule, brand, container, size) {
                                mask |= 1 << index;
                            }
                        }
                        if mask != 0 {
                            masks.insert(partkeys.value(row), mask);
                        }
                    }
                    continue;
                }
            }
        }
        for row in 0..batch.num_rows() {
            if brands.is_null(row) || containers.is_null(row) {
                continue;
            }
            let (Some(partkey), Some(size)) = (
                numeric_i64_value(partkeys, row)?,
                numeric_f64_value(sizes, row)?,
            ) else {
                continue;
            };
            let mut mask = 0_u8;
            for (index, rule) in rules.iter().enumerate() {
                if brands.value(row) == rule.brand
                    && rule.containers.contains(containers.value(row))
                    && size >= rule.size_low
                    && size <= rule.size_high
                {
                    mask |= 1 << index;
                }
            }
            if mask != 0 {
                masks.insert(partkey, mask);
            }
        }
    }
    Ok(masks)
}

struct Q19RawPartRule {
    brand: Vec<u8>,
    containers: Vec<Vec<u8>>,
    size_low: i64,
    size_high: i64,
}

fn q19_raw_part_rules(rules: &[Q19Rule]) -> Vec<Q19RawPartRule> {
    rules
        .iter()
        .map(|rule| Q19RawPartRule {
            brand: rule.brand.as_bytes().to_vec(),
            containers: rule
                .containers
                .iter()
                .map(|container| container.as_bytes().to_vec())
                .collect(),
            size_low: rule.size_low.ceil() as i64,
            size_high: rule.size_high.floor() as i64,
        })
        .collect()
}

fn q19_raw_part_rule_matches(
    rule: &Q19RawPartRule,
    brand: &[u8],
    container: &[u8],
    size: i64,
) -> bool {
    rule.brand.as_slice() == brand
        && size >= rule.size_low
        && size <= rule.size_high
        && rule
            .containers
            .iter()
            .any(|candidate| candidate.as_slice() == container)
}

enum Q19PartSizeValues<'a> {
    Int32(&'a Int32Array),
    Int64(&'a Int64Array),
}

impl Q19PartSizeValues<'_> {
    fn null_count(&self) -> usize {
        match self {
            Self::Int32(values) => values.null_count(),
            Self::Int64(values) => values.null_count(),
        }
    }

    fn value(&self, row: usize) -> i64 {
        match self {
            Self::Int32(values) => i64::from(values.value(row)),
            Self::Int64(values) => values.value(row),
        }
    }
}

fn q19_part_size_values(column: &ArrayRef) -> Option<Q19PartSizeValues<'_>> {
    column
        .as_any()
        .downcast_ref::<Int32Array>()
        .map(Q19PartSizeValues::Int32)
        .or_else(|| {
            column
                .as_any()
                .downcast_ref::<Int64Array>()
                .map(Q19PartSizeValues::Int64)
        })
}

async fn q19_lineitem_revenue(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    rules: Arc<Vec<Q19Rule>>,
    part_masks: Arc<AdaptiveI64Map<u8>>,
) -> Result<(f64, u64)> {
    if std::env::var_os("DODAM_Q19_DISABLE_LATE_MATERIALIZE").is_none() {
        if let Some(result) = q19_late_materialized_lineitem_revenue(
            engine,
            path.clone(),
            batch_size,
            rules.clone(),
            part_masks.clone(),
        )
        .await?
        {
            return Ok(result);
        }
    }
    let profile = tpch_profile_enabled();
    engine
        .parquet_scan_accumulate_chunks_view(
            path,
            batch_size,
            Projection::Columns(vec![
                "l_partkey".to_string(),
                "l_quantity".to_string(),
                "l_extendedprice".to_string(),
                "l_discount".to_string(),
                "l_shipmode".to_string(),
                "l_shipinstruct".to_string(),
            ]),
            scan_aggregate_row_group_chunk(),
            4,
            scan_aggregate_fusion_enabled(),
            || (0.0, 0_u64, Q19SelectionProfile::default()),
            || (0.0, 0_u64, Q19SelectionProfile::default()),
            move |view, output| {
                let mut raw_rule_cache = None;
                let mut batch_profile = profile.then_some(Q19SelectionProfile::default());
                let (batch_sum, batch_count) = q19_lineitem_revenue_batch(
                    view,
                    &rules,
                    &part_masks,
                    &mut raw_rule_cache,
                    batch_profile.as_mut(),
                )?;
                output.0 += batch_sum;
                output.1 += batch_count;
                if let Some(batch_profile) = batch_profile {
                    output.2.add(batch_profile);
                }
                Ok(Some(()))
            },
            |total, batch| {
                total.0 += batch.0;
                total.1 += batch.1;
                total.2.add(batch.2);
            },
            "Q19 lineitem revenue",
        )
        .await
        .map(|(sum, count, profile_metrics)| {
            if profile {
                q19_log_selection_profile(profile_metrics);
            }
            (sum, count)
        })
}

async fn q19_late_materialized_lineitem_revenue(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    rules: Arc<Vec<Q19Rule>>,
    part_masks: Arc<AdaptiveI64Map<u8>>,
) -> Result<Option<(f64, u64)>> {
    let predicate_projection = Projection::Columns(vec![
        "l_partkey".to_string(),
        "l_quantity".to_string(),
        "l_discount".to_string(),
        "l_shipmode".to_string(),
        "l_shipinstruct".to_string(),
    ]);
    let payload_projection = Projection::Columns(vec!["l_extendedprice".to_string()]);
    let rules_for_state = rules.clone();
    let part_masks_for_state = part_masks.clone();
    let policy = late_materialization_policy_from_projection_env(
        &predicate_projection,
        &payload_projection,
        "DODAM_Q19_LATE_MAX_SELECTED_RATIO",
        0.60,
        None,
        None,
    );
    let Some(chunks) = engine
        .late_materialized_parquet_map_pruned_with_policy_view(
            path,
            batch_size,
            predicate_projection,
            payload_projection,
            Vec::new(),
            q19_late_materialized_row_group_chunk(),
            policy,
            move || Q19LateState {
                rules: rules_for_state.clone(),
                part_masks: part_masks_for_state.clone(),
                raw_rule_cache: None,
                selected_discounts: Vec::new(),
                discount_scale: None,
                extendedprice_scale: None,
                discount_offset: 0,
                sum: 0.0,
            },
            q19_late_build_selection_view,
            q19_late_consume_payload_view,
            |state, _metrics| {
                if state.discount_offset != state.selected_discounts.len() {
                    return Err(DodamError::UnsupportedSql(
                        "Q19 row selection payload mismatch".to_string(),
                    ));
                }
                Ok(Some((state.sum, state.selected_discounts.len() as u64)))
            },
        )
        .await?
    else {
        return Ok(None);
    };
    let mut sum = 0.0;
    let mut count = 0_u64;
    let mut metrics = LateMaterializedMetrics::default();
    for chunk in chunks {
        sum += chunk.output.0;
        count += chunk.output.1;
        metrics.add(chunk.metrics);
    }
    q19_log_late_materialized_profile(metrics, q19_late_materialized_row_group_chunk());
    Ok(Some((sum, count)))
}

fn q19_late_materialized_row_group_chunk() -> usize {
    std::env::var("DODAM_Q19_LATE_ROW_GROUP_CHUNK")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(2)
}

struct Q19LateState {
    rules: Arc<Vec<Q19Rule>>,
    part_masks: Arc<AdaptiveI64Map<u8>>,
    raw_rule_cache: Option<(u64, Vec<Q19RawLineRule>)>,
    selected_discounts: Vec<i64>,
    discount_scale: Option<i64>,
    extendedprice_scale: Option<i64>,
    discount_offset: usize,
    sum: f64,
}

fn q19_late_build_selection_batch(
    batch: RecordBatch,
    selection: &mut LateSelectionBuilder,
    state: &mut Q19LateState,
) -> Result<Option<()>> {
    let partkeys = batch_column(&batch, "l_partkey")?;
    let quantities = batch_column(&batch, "l_quantity")?;
    let discounts = batch_column(&batch, "l_discount")?;
    let shipmodes = batch_string_column(&batch, "l_shipmode")?;
    let shipinstructs = batch_string_column(&batch, "l_shipinstruct")?;
    let (Some(partkeys), Some(quantities), Some(discounts)) = (
        partkeys.as_any().downcast_ref::<Int64Array>(),
        decimal_input(quantities)?,
        decimal_input(discounts)?,
    ) else {
        return Ok(None);
    };
    if partkeys.null_count() != 0
        || quantities.null_count() != 0
        || discounts.null_count() != 0
        || shipmodes.null_count() != 0
        || shipinstructs.null_count() != 0
        || quantities.precision > 18
        || discounts.precision > 18
    {
        return Ok(None);
    }
    let discount_scale = discounts.scale as i64;
    if let Some(existing) = state.discount_scale {
        if existing != discount_scale {
            return Ok(None);
        }
    } else {
        state.discount_scale = Some(discount_scale);
    }
    let raw_rules =
        q19_raw_line_rules_cached(&state.rules, quantities.scale, &mut state.raw_rule_cache);
    let shipmode_offsets = shipmodes.value_offsets();
    let shipmode_data = shipmodes.value_data();
    let shipinstruct_offsets = shipinstructs.value_offsets();
    let shipinstruct_data = shipinstructs.value_data();
    let partkey_values = partkeys.values();
    let quantity_values = quantities.raw_values();
    let discount_values = discounts.raw_values();
    let part_masks_dense = state.part_masks.dense_slices();
    selection.push_selected_offsets(
        batch.num_rows(),
        (0..batch.num_rows()).filter_map(|row| {
            let selected = if let Some(mask) = state
                .part_masks
                .get_cached(part_masks_dense, partkey_values[row])
            {
                q19_rule_matches_lineitem_raw(
                    raw_rules,
                    mask,
                    quantity_values[row],
                    bytes_string_parts(shipmode_offsets, shipmode_data, row),
                    bytes_string_parts(shipinstruct_offsets, shipinstruct_data, row),
                )
            } else {
                false
            };
            if selected {
                state.selected_discounts.push(discount_values[row] as i64);
                Some(row)
            } else {
                None
            }
        }),
    );
    Ok(Some(()))
}

fn q19_late_build_selection_view(
    view: BatchView<'_>,
    selection: &mut LateSelectionBuilder,
    state: &mut Q19LateState,
) -> Result<Option<()>> {
    if view.num_columns() == 5
        && let (
            Some(partkeys),
            Some(quantities),
            Some(discounts),
            Some(shipmodes),
            Some(shipinstructs),
        ) = (
            view.i64_vector(0),
            view.decimal128_vector(1),
            view.decimal128_vector(2),
            view.utf8_vector(3),
            view.utf8_vector(4),
        )
    {
        return q19_late_build_selection_vector_typed(
            partkeys,
            quantities,
            discounts,
            shipmodes,
            shipinstructs,
            selection,
            state,
        );
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(None);
    };
    q19_late_build_selection_batch(batch.clone(), selection, state)
}

fn q19_late_build_selection_vector_typed(
    partkeys: I64VectorView<'_>,
    quantities: Decimal128VectorView<'_>,
    discounts: Decimal128VectorView<'_>,
    shipmodes: Utf8VectorView<'_>,
    shipinstructs: Utf8VectorView<'_>,
    selection: &mut LateSelectionBuilder,
    state: &mut Q19LateState,
) -> Result<Option<()>> {
    if quantities.precision() > 18 || discounts.precision() > 18 {
        return Ok(None);
    }
    let Some(discount_scale) = discounts.scale_i64() else {
        return Ok(None);
    };
    if let Some(existing) = state.discount_scale {
        if existing != discount_scale {
            return Ok(None);
        }
    } else {
        state.discount_scale = Some(discount_scale);
    }
    let raw_rules =
        q19_raw_line_rules_cached(&state.rules, quantities.scale(), &mut state.raw_rule_cache);
    let part_masks_dense = state.part_masks.dense_slices();
    if let (Some(quantity_values), Some(discount_values)) =
        (quantities.raw_i64_values(), discounts.raw_i64_values())
    {
        selection.push_selected_offsets(
            partkeys.len(),
            (0..partkeys.len()).filter_map(|row| {
                if partkeys.is_null(row)
                    || quantities.is_null(row)
                    || discounts.is_null(row)
                    || shipmodes.is_null(row)
                    || shipinstructs.is_null(row)
                {
                    return None;
                }
                let selected = if let Some(mask) = state
                    .part_masks
                    .get_cached(part_masks_dense, partkeys.value(row))
                {
                    q19_rule_matches_lineitem_raw(
                        raw_rules,
                        mask,
                        i128::from(quantity_values[row]),
                        shipmodes.value_bytes(row),
                        shipinstructs.value_bytes(row),
                    )
                } else {
                    false
                };
                if selected {
                    state.selected_discounts.push(discount_values[row]);
                    Some(row)
                } else {
                    None
                }
            }),
        );
        return Ok(Some(()));
    }
    let quantity_values = quantities.raw_values();
    let discount_values = discounts.raw_values();
    selection.push_selected_offsets(
        partkeys.len(),
        (0..partkeys.len()).filter_map(|row| {
            if partkeys.is_null(row)
                || quantities.is_null(row)
                || discounts.is_null(row)
                || shipmodes.is_null(row)
                || shipinstructs.is_null(row)
            {
                return None;
            }
            let selected = if let Some(mask) = state
                .part_masks
                .get_cached(part_masks_dense, partkeys.value(row))
            {
                q19_rule_matches_lineitem_raw(
                    raw_rules,
                    mask,
                    quantity_values[row],
                    shipmodes.value_bytes(row),
                    shipinstructs.value_bytes(row),
                )
            } else {
                false
            };
            if selected {
                state.selected_discounts.push(discount_values[row] as i64);
                Some(row)
            } else {
                None
            }
        }),
    );
    Ok(Some(()))
}

fn q19_late_consume_payload_batch(
    batch: RecordBatch,
    state: &mut Q19LateState,
) -> Result<Option<()>> {
    let extendedprices = batch_column(&batch, "l_extendedprice")?;
    let Some(extendedprices) = decimal_input(extendedprices)? else {
        return Ok(None);
    };
    if extendedprices.null_count() != 0 || extendedprices.precision > 18 {
        return Ok(None);
    }
    let price_scale = extendedprices.scale as i64;
    if let Some(existing) = state.extendedprice_scale {
        if existing != price_scale {
            return Ok(None);
        }
    } else {
        state.extendedprice_scale = Some(price_scale);
    }
    let discount_scale = state
        .discount_scale
        .ok_or_else(|| DodamError::UnsupportedSql("Q19 missing discount scale".to_string()))?;
    let revenue_scale = 1.0 / ((price_scale as f64) * (discount_scale as f64));
    for &extendedprice in extendedprices.raw_values() {
        let discount = *state
            .selected_discounts
            .get(state.discount_offset)
            .ok_or_else(|| {
                DodamError::UnsupportedSql("Q19 row selection payload mismatch".to_string())
            })?;
        state.sum += ((extendedprice as i64) * (discount_scale - discount)) as f64 * revenue_scale;
        state.discount_offset += 1;
    }
    Ok(Some(()))
}

fn q19_late_consume_payload_view(
    view: BatchView<'_>,
    state: &mut Q19LateState,
) -> Result<Option<()>> {
    if view.num_columns() == 1
        && let Some(extendedprices) = view.decimal128_vector(0)
    {
        return q19_late_consume_payload_vector(extendedprices, state);
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(None);
    };
    q19_late_consume_payload_batch(batch.clone(), state)
}

fn q19_late_consume_payload_vector(
    extendedprices: Decimal128VectorView<'_>,
    state: &mut Q19LateState,
) -> Result<Option<()>> {
    if extendedprices.null_count() != 0 || extendedprices.precision() > 18 {
        return Ok(None);
    }
    let Some(price_scale) = extendedprices.scale_i64() else {
        return Ok(None);
    };
    if let Some(existing) = state.extendedprice_scale {
        if existing != price_scale {
            return Ok(None);
        }
    } else {
        state.extendedprice_scale = Some(price_scale);
    }
    let discount_scale = state
        .discount_scale
        .ok_or_else(|| DodamError::UnsupportedSql("Q19 missing discount scale".to_string()))?;
    let revenue_scale = 1.0 / ((price_scale as f64) * (discount_scale as f64));
    if let Some(extendedprices) = extendedprices.raw_i64_values() {
        for &extendedprice in extendedprices {
            let discount = *state
                .selected_discounts
                .get(state.discount_offset)
                .ok_or_else(|| {
                    DodamError::UnsupportedSql("Q19 row selection payload mismatch".to_string())
                })?;
            state.sum += decimal_discounted_revenue_raw_i64(
                extendedprice,
                discount,
                discount_scale as f64,
                revenue_scale,
            );
            state.discount_offset += 1;
        }
        return Ok(Some(()));
    }
    for &extendedprice in extendedprices.raw_values() {
        let discount = *state
            .selected_discounts
            .get(state.discount_offset)
            .ok_or_else(|| {
                DodamError::UnsupportedSql("Q19 row selection payload mismatch".to_string())
            })?;
        state.sum += ((extendedprice as i64) * (discount_scale - discount)) as f64 * revenue_scale;
        state.discount_offset += 1;
    }
    Ok(Some(()))
}

fn q19_log_late_materialized_profile(metrics: LateMaterializedMetrics, row_group_chunk: usize) {
    if !tpch_profile_enabled() {
        return;
    }
    let ratio = if metrics.total_rows == 0 {
        0.0
    } else {
        metrics.selected_rows as f64 / metrics.total_rows as f64
    };
    eprintln!(
        "[dodam:tpch-profile] Q19: late_materialized rows={} selected={} ratio={:.6} selector_runs={} row_group_chunk={}",
        metrics.total_rows, metrics.selected_rows, ratio, metrics.selector_runs, row_group_chunk
    );
}

fn q19_lineitem_revenue_batch(
    view: BatchView<'_>,
    rules: &[Q19Rule],
    part_masks: &AdaptiveI64Map<u8>,
    raw_rule_cache: &mut Option<(u64, Vec<Q19RawLineRule>)>,
    mut profile: Option<&mut Q19SelectionProfile>,
) -> Result<(f64, u64)> {
    if view.num_columns() == 6
        && let (
            Some(partkeys),
            Some(quantities),
            Some(extendedprices),
            Some(discounts),
            Some(shipmodes),
            Some(shipinstructs),
        ) = (
            view.i64_vector(0),
            view.decimal128_vector(1),
            view.decimal128_vector(2),
            view.decimal128_vector(3),
            view.utf8_vector(4),
            view.utf8_vector(5),
        )
    {
        return q19_lineitem_revenue_vector_typed(
            partkeys,
            quantities,
            extendedprices,
            discounts,
            shipmodes,
            shipinstructs,
            rules,
            part_masks,
            raw_rule_cache,
            profile,
        );
    }
    let Some(batch) = view.try_record_batch() else {
        return Err(DodamError::UnsupportedSql(
            "Q19 lineitem revenue raw vector columns have unsupported types".to_string(),
        ));
    };
    let partkeys = batch_column(&batch, "l_partkey")?;
    let quantities = batch_column(&batch, "l_quantity")?;
    let extendedprices = batch_column(&batch, "l_extendedprice")?;
    let discounts = batch_column(&batch, "l_discount")?;
    let shipmodes = batch_string_column(&batch, "l_shipmode")?;
    let shipinstructs = batch_string_column(&batch, "l_shipinstruct")?;
    let mut sum = 0.0;
    let mut count = 0_u64;
    if let (Some(partkeys), Some(quantities), Some(extendedprices), Some(discounts)) = (
        partkeys.as_any().downcast_ref::<Int64Array>(),
        decimal_input(quantities)?,
        decimal_input(extendedprices)?,
        decimal_input(discounts)?,
    ) {
        let raw_rules = q19_raw_line_rules_cached(rules, quantities.scale, raw_rule_cache);
        if partkeys.null_count() == 0
            && quantities.null_count() == 0
            && extendedprices.null_count() == 0
            && discounts.null_count() == 0
            && shipmodes.null_count() == 0
            && shipinstructs.null_count() == 0
        {
            let discount_one_raw = scaled_f64_to_i128(1.0, discounts.scale);
            let revenue_scale = 1.0 / (extendedprices.scale * discounts.scale);
            let shipmode_offsets = shipmodes.value_offsets();
            let shipmode_data = shipmodes.value_data();
            let shipinstruct_offsets = shipinstructs.value_offsets();
            let shipinstruct_data = shipinstructs.value_data();
            let partkey_values = partkeys.values();
            let quantity_values = quantities.raw_values();
            let extendedprice_values = extendedprices.raw_values();
            let discount_values = discounts.raw_values();
            for row in 0..batch.num_rows() {
                let selected = if let Some(mask) = part_masks.get(partkey_values[row]) {
                    q19_rule_matches_lineitem_raw(
                        &raw_rules,
                        mask,
                        quantity_values[row],
                        bytes_string_parts(shipmode_offsets, shipmode_data, row),
                        bytes_string_parts(shipinstruct_offsets, shipinstruct_data, row),
                    )
                } else {
                    false
                };
                if let Some(profile) = profile.as_deref_mut() {
                    profile.record(selected);
                }
                if !selected {
                    continue;
                }
                sum += (extendedprice_values[row] * (discount_one_raw - discount_values[row]))
                    as f64
                    * revenue_scale;
                count += 1;
            }
            return Ok((sum, count));
        }
        for row in 0..batch.num_rows() {
            if partkeys.is_null(row)
                || quantities.is_null(row)
                || extendedprices.is_null(row)
                || discounts.is_null(row)
                || shipmodes.is_null(row)
                || shipinstructs.is_null(row)
            {
                if let Some(profile) = profile.as_deref_mut() {
                    profile.record(false);
                }
                continue;
            }
            let quantity = quantities.value(row);
            let selected = if let Some(mask) = part_masks.get(partkeys.value(row)) {
                q19_rule_matches_lineitem(
                    rules,
                    mask,
                    quantity,
                    shipmodes.value(row),
                    shipinstructs.value(row),
                )
            } else {
                false
            };
            if let Some(profile) = profile.as_deref_mut() {
                profile.record(selected);
            }
            if !selected {
                continue;
            }
            sum += extendedprices.value(row) * (1.0 - discounts.value(row));
            count += 1;
        }
        return Ok((sum, count));
    }
    for row in 0..batch.num_rows() {
        if shipmodes.is_null(row) || shipinstructs.is_null(row) {
            if let Some(profile) = profile.as_deref_mut() {
                profile.record(false);
            }
            continue;
        }
        let (Some(partkey), Some(quantity), Some(extendedprice), Some(discount)) = (
            numeric_i64_value(partkeys, row)?,
            numeric_f64_value(quantities, row)?,
            numeric_f64_value(extendedprices, row)?,
            numeric_f64_value(discounts, row)?,
        ) else {
            if let Some(profile) = profile.as_deref_mut() {
                profile.record(false);
            }
            continue;
        };
        let selected = if let Some(mask) = part_masks.get(partkey) {
            q19_rule_matches_lineitem(
                rules,
                mask,
                quantity,
                shipmodes.value(row),
                shipinstructs.value(row),
            )
        } else {
            false
        };
        if let Some(profile) = profile.as_deref_mut() {
            profile.record(selected);
        }
        if selected {
            sum += extendedprice * (1.0 - discount);
            count += 1;
        }
    }
    Ok((sum, count))
}

#[allow(clippy::too_many_arguments)]
fn q19_lineitem_revenue_vector_typed(
    partkeys: I64VectorView<'_>,
    quantities: Decimal128VectorView<'_>,
    extendedprices: Decimal128VectorView<'_>,
    discounts: Decimal128VectorView<'_>,
    shipmodes: Utf8VectorView<'_>,
    shipinstructs: Utf8VectorView<'_>,
    rules: &[Q19Rule],
    part_masks: &AdaptiveI64Map<u8>,
    raw_rule_cache: &mut Option<(u64, Vec<Q19RawLineRule>)>,
    mut profile: Option<&mut Q19SelectionProfile>,
) -> Result<(f64, u64)> {
    let mut sum = 0.0;
    let mut count = 0_u64;
    let raw_rules = q19_raw_line_rules_cached(rules, quantities.scale(), raw_rule_cache);
    let discount_one_raw = scaled_f64_to_i128(1.0, discounts.scale());
    let revenue_scale = 1.0 / (extendedprices.scale() * discounts.scale());
    if let (Some(quantity_values), Some(extendedprice_values), Some(discount_values)) = (
        quantities.raw_i64_values(),
        extendedprices.raw_i64_values(),
        discounts.raw_i64_values(),
    ) {
        let discount_one_raw = discount_one_raw as i64;
        for row in 0..partkeys.len() {
            if partkeys.is_null(row)
                || quantities.is_null(row)
                || extendedprices.is_null(row)
                || discounts.is_null(row)
                || shipmodes.is_null(row)
                || shipinstructs.is_null(row)
            {
                if let Some(profile) = profile.as_deref_mut() {
                    profile.record(false);
                }
                continue;
            }
            let selected = if let Some(mask) = part_masks.get(partkeys.value(row)) {
                q19_rule_matches_lineitem_raw(
                    raw_rules,
                    mask,
                    i128::from(quantity_values[row]),
                    shipmodes.value_bytes(row),
                    shipinstructs.value_bytes(row),
                )
            } else {
                false
            };
            if let Some(profile) = profile.as_deref_mut() {
                profile.record(selected);
            }
            if !selected {
                continue;
            }
            sum += decimal_discounted_revenue_raw_i64(
                extendedprice_values[row],
                discount_values[row],
                discount_one_raw as f64,
                revenue_scale,
            );
            count += 1;
        }
        return Ok((sum, count));
    }
    let quantity_values = quantities.raw_values();
    let extendedprice_values = extendedprices.raw_values();
    let discount_values = discounts.raw_values();
    for row in 0..partkeys.len() {
        if partkeys.is_null(row)
            || quantities.is_null(row)
            || extendedprices.is_null(row)
            || discounts.is_null(row)
            || shipmodes.is_null(row)
            || shipinstructs.is_null(row)
        {
            if let Some(profile) = profile.as_deref_mut() {
                profile.record(false);
            }
            continue;
        }
        let selected = if let Some(mask) = part_masks.get(partkeys.value(row)) {
            q19_rule_matches_lineitem_raw(
                raw_rules,
                mask,
                quantity_values[row],
                shipmodes.value_bytes(row),
                shipinstructs.value_bytes(row),
            )
        } else {
            false
        };
        if let Some(profile) = profile.as_deref_mut() {
            profile.record(selected);
        }
        if !selected {
            continue;
        }
        sum += (extendedprice_values[row] * (discount_one_raw - discount_values[row])) as f64
            * revenue_scale;
        count += 1;
    }
    Ok((sum, count))
}

#[derive(Debug, Clone, Copy, Default)]
struct Q19SelectionProfile {
    total_rows: u64,
    selected_rows: u64,
    selector_runs: u64,
    last_selected: Option<bool>,
}

impl Q19SelectionProfile {
    fn record(&mut self, selected: bool) {
        self.total_rows += 1;
        if selected {
            self.selected_rows += 1;
        }
        if self.last_selected != Some(selected) {
            self.selector_runs += 1;
            self.last_selected = Some(selected);
        }
    }

    fn add(&mut self, other: Self) {
        if other.total_rows == 0 {
            return;
        }
        self.total_rows += other.total_rows;
        self.selected_rows += other.selected_rows;
        self.selector_runs += other.selector_runs;
        self.last_selected = other.last_selected.or(self.last_selected);
    }
}

fn q19_log_selection_profile(profile: Q19SelectionProfile) {
    let ratio = if profile.total_rows == 0 {
        0.0
    } else {
        profile.selected_rows as f64 / profile.total_rows as f64
    };
    eprintln!(
        "[dodam:tpch-profile] Q19: predicate_selected rows={} selected={} ratio={:.6} selector_runs={}",
        profile.total_rows, profile.selected_rows, ratio, profile.selector_runs
    );
}

struct Q19RawLineRule {
    quantity_low: i128,
    quantity_high: i128,
    shipmodes: Vec<Vec<u8>>,
    shipinstruct: Vec<u8>,
}

fn q19_raw_line_rules(rules: &[Q19Rule], quantity_scale: f64) -> Vec<Q19RawLineRule> {
    rules
        .iter()
        .map(|rule| Q19RawLineRule {
            quantity_low: scaled_f64_to_i128(rule.quantity_low, quantity_scale),
            quantity_high: scaled_f64_to_i128(rule.quantity_high, quantity_scale),
            shipmodes: rule
                .shipmodes
                .iter()
                .map(|shipmode| shipmode.as_bytes().to_vec())
                .collect(),
            shipinstruct: rule.shipinstruct.as_bytes().to_vec(),
        })
        .collect()
}

fn q19_raw_line_rules_cached<'a>(
    rules: &[Q19Rule],
    quantity_scale: f64,
    cache: &'a mut Option<(u64, Vec<Q19RawLineRule>)>,
) -> &'a [Q19RawLineRule] {
    let scale_key = quantity_scale.to_bits();
    if !matches!(cache, Some((cached_key, _)) if *cached_key == scale_key) {
        *cache = Some((scale_key, q19_raw_line_rules(rules, quantity_scale)));
    }
    cache
        .as_ref()
        .expect("q19 raw rule cache populated")
        .1
        .as_slice()
}

fn bytes_string_parts<'a>(offsets: &[i32], data: &'a [u8], row: usize) -> &'a [u8] {
    let start = offsets[row] as usize;
    let end = offsets[row + 1] as usize;
    &data[start..end]
}

fn q19_rule_matches_lineitem_raw(
    rules: &[Q19RawLineRule],
    mask: u8,
    quantity: i128,
    shipmode: &[u8],
    shipinstruct: &[u8],
) -> bool {
    let relevant_mask = (u16::from(mask) & ((1_u16 << rules.len().min(8)) - 1)) as u8;
    if relevant_mask != 0 && (relevant_mask & (relevant_mask - 1)) == 0 {
        return rules
            .get(relevant_mask.trailing_zeros() as usize)
            .is_some_and(|rule| {
                q19_raw_rule_matches_lineitem(rule, quantity, shipmode, shipinstruct)
            });
    }
    for (index, rule) in rules.iter().enumerate() {
        if mask & (1 << index) == 0 {
            continue;
        }
        if q19_raw_rule_matches_lineitem(rule, quantity, shipmode, shipinstruct) {
            return true;
        }
    }
    false
}

fn q19_raw_rule_matches_lineitem(
    rule: &Q19RawLineRule,
    quantity: i128,
    shipmode: &[u8],
    shipinstruct: &[u8],
) -> bool {
    quantity >= rule.quantity_low
        && quantity <= rule.quantity_high
        && rule.shipinstruct == shipinstruct
        && rule
            .shipmodes
            .iter()
            .any(|candidate| candidate.as_slice() == shipmode)
}

fn q19_rule_matches_lineitem(
    rules: &[Q19Rule],
    mask: u8,
    quantity: f64,
    shipmode: &str,
    shipinstruct: &str,
) -> bool {
    for (index, rule) in rules.iter().enumerate() {
        if mask & (1 << index) == 0 {
            continue;
        }
        if quantity >= rule.quantity_low
            && quantity <= rule.quantity_high
            && rule.shipmodes.contains(shipmode)
            && shipinstruct == rule.shipinstruct
        {
            return true;
        }
    }
    false
}

async fn try_execute_supplier_wait_count_antijoin_sql(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(None);
    };
    let Some(selection) = select.selection.as_ref() else {
        return Ok(None);
    };
    if !supplier_wait_count_antijoin_shape(select, query, selection) {
        return Ok(None);
    }
    reject_query_features(query)?;
    reject_select_features(select)?;
    let Some(tables) = parse_comma_join_table_refs(select)? else {
        return Ok(None);
    };
    if tables.len() != 4 {
        return Ok(None);
    }
    let mut supplier = None;
    let mut lineitem = None;
    let mut orders = None;
    let mut nation = None;
    for table in tables {
        let alias = table_ref_alias_or_name(&table);
        if alias.eq_ignore_ascii_case("supplier") {
            supplier = Some(table);
        } else if alias.eq_ignore_ascii_case("l1") {
            lineitem = Some(table);
        } else if alias.eq_ignore_ascii_case("orders") {
            orders = Some(table);
        } else if alias.eq_ignore_ascii_case("nation") {
            nation = Some(table);
        }
    }
    let (Some(supplier), Some(lineitem), Some(orders), Some(nation)) =
        (supplier, lineitem, orders, nation)
    else {
        return Ok(None);
    };
    let stage = tpch_profile_start();
    let nation_keys = q21_nation_keys(engine, nation.path, batch_size, "SAUDI ARABIA").await?;
    tpch_profile_elapsed("Q21 nation keys", stage);
    let stage = tpch_profile_start();
    let suppliers = q21_supplier_names(engine, supplier.path, batch_size, &nation_keys).await?;
    tpch_profile_elapsed("Q21 supplier names", stage);
    if suppliers.is_empty() {
        return Ok(Some(q21_output(Vec::new())?));
    }
    let stage = tpch_profile_start();
    let final_orders = q21_final_order_keys(engine, orders.path, batch_size).await?;
    tpch_profile_elapsed("Q21 final order keys", stage);
    if final_orders.is_empty() {
        return Ok(Some(q21_output(Vec::new())?));
    }
    let stage = tpch_profile_start();
    let counts = if q21_ordered_lineitem_enabled()
        && let Some(counts) = q21_lineitem_supplier_counts_ordered(
            engine,
            lineitem.path.clone(),
            batch_size,
            &final_orders,
            &suppliers,
        )
        .await?
    {
        tpch_profile_elapsed("Q21 ordered lineitem counts", stage);
        counts
    } else {
        let order_states =
            q21_lineitem_order_states(engine, lineitem.path, batch_size, final_orders).await?;
        tpch_profile_elapsed("Q21 lineitem order states", stage);
        let mut counts = HashMap::<i64, u64>::with_capacity(suppliers.len());
        for state in order_states.into_values() {
            q21_count_qualifying_order(&mut counts, &suppliers, &state);
        }
        counts
    };
    let stage = tpch_profile_start();
    let mut rows = counts
        .into_iter()
        .filter_map(|(suppkey, count)| {
            suppliers.get(&suppkey).map(|name| Q21Row {
                s_name: name.clone(),
                count,
            })
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        right
            .count
            .cmp(&left.count)
            .then_with(|| left.s_name.cmp(&right.s_name))
    });
    rows.truncate(100);
    tpch_profile_elapsed("Q21 final rows", stage);
    Ok(Some(q21_output(rows)?))
}

fn q21_ordered_lineitem_enabled() -> bool {
    std::env::var_os("DODAM_Q21_DISABLE_ORDERED_LINEITEM").is_none()
}

fn supplier_wait_count_antijoin_shape(select: &Select, query: &Query, selection: &SqlExpr) -> bool {
    let text = selection.to_string().to_ascii_lowercase();
    select.projection.len() == 2
        && matches!(parse_limit(query), Ok(Some(100)))
        && text.contains("o_orderstatus = 'f'")
        && text.contains("l1.l_receiptdate > l1.l_commitdate")
        && text.contains("exists")
        && text.contains("not exists")
        && text.contains("n_name = 'saudi arabia'")
}

async fn q21_nation_keys(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    nation_name: &str,
) -> Result<HashSet<i64>> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec!["n_nationkey".to_string(), "n_name".to_string()]),
            None,
        )
        .await?;
    let mut keys = HashSet::new();
    while let Some(batch) = stream.next() {
        let batch = batch?;
        let nationkeys = batch_column(&batch, "n_nationkey")?;
        let names = batch_string_column(&batch, "n_name")?;
        for row in 0..batch.num_rows() {
            if names.is_valid(row)
                && names.value(row) == nation_name
                && let Some(key) = numeric_i64_value(nationkeys, row)?
            {
                keys.insert(key);
            }
        }
    }
    Ok(keys)
}

async fn q21_supplier_names(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    nation_keys: &HashSet<i64>,
) -> Result<HashMap<i64, String>> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec![
                "s_suppkey".to_string(),
                "s_nationkey".to_string(),
                "s_name".to_string(),
            ]),
            None,
        )
        .await?;
    let mut suppliers = HashMap::new();
    while let Some(batch) = stream.next() {
        let batch = batch?;
        let suppkeys = batch_column(&batch, "s_suppkey")?;
        let nationkeys = batch_column(&batch, "s_nationkey")?;
        let names = batch_string_column(&batch, "s_name")?;
        for row in 0..batch.num_rows() {
            let (Some(suppkey), Some(nationkey)) = (
                numeric_i64_value(suppkeys, row)?,
                numeric_i64_value(nationkeys, row)?,
            ) else {
                continue;
            };
            if nation_keys.contains(&nationkey) && names.is_valid(row) {
                suppliers.insert(suppkey, names.value(row).to_string());
            }
        }
    }
    Ok(suppliers)
}

async fn q21_final_order_keys(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
) -> Result<Q21FinalOrders> {
    if q21_atomic_final_orders_enabled()
        && let Some(keys) = q21_final_order_keys_atomic(engine, path.clone(), batch_size).await?
    {
        return Ok(keys);
    }
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec!["o_orderkey".to_string(), "o_orderstatus".to_string()]),
            None,
        )
        .await?;
    let mut keys = Q21FinalOrders::new_dense();
    while let Some(batch) = stream.next() {
        let batch = batch?;
        q21_final_orders_batch_into(&batch, &mut keys)?;
    }
    Ok(keys)
}

type Q21FinalOrders = AdaptiveI64Set;

fn q21_atomic_final_orders_enabled() -> bool {
    !std::env::var("DODAM_Q21_DISABLE_ATOMIC_FINAL_ORDERS")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
}

async fn q21_final_order_keys_atomic(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
) -> Result<Option<Q21FinalOrders>> {
    let Some(max_key) = engine
        .parquet_i64_column_max(path.clone(), "o_orderkey")
        .await?
        .and_then(|key| usize::try_from(key).ok())
    else {
        return Ok(None);
    };
    let markers = Arc::new(DenseAtomicU8::zeroed(max_key + 1));
    let Some(_) = engine
        .parquet_row_group_map_dictionary_columns_pruned_view(
            path.clone(),
            batch_size,
            Projection::Columns(vec!["o_orderkey".to_string(), "o_orderstatus".to_string()]),
            vec!["o_orderstatus".to_string()],
            Vec::new(),
            q21_atomic_final_order_row_group_chunk(),
            || (),
            {
                let markers = markers.clone();
                move |view, _state| {
                    q21_final_orders_atomic_view_into(view, &markers)?;
                    Ok(Some(()))
                }
            },
            |_| Ok(Some(())),
        )
        .await?
    else {
        return Ok(None);
    };
    let markers = Arc::try_unwrap(markers).map_err(|_| {
        DodamError::UnsupportedSql("Q21 atomic final-order marker still shared".to_string())
    })?;
    Ok(Some(markers.into_adaptive_i64_set()))
}

fn q21_atomic_final_order_row_group_chunk() -> usize {
    std::env::var("DODAM_Q21_ATOMIC_FINAL_ORDER_ROW_GROUP_CHUNK")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(8)
}

fn q21_final_orders_atomic_view_into(view: BatchView<'_>, markers: &DenseAtomicU8) -> Result<()> {
    if view.num_columns() == 2
        && let Some(orderkeys) = view.i64_vector(0)
    {
        if let Some(statuses) = view.dictionary_i32_view(1) {
            return q21_final_orders_atomic_dictionary_view_into(orderkeys, statuses, markers);
        }
        if let Some(statuses) = view.utf8(1) {
            return q21_final_orders_atomic_utf8_view_into(orderkeys, statuses, markers);
        }
    }
    let Some(batch) = view.try_record_batch() else {
        return Err(DodamError::UnsupportedSql(
            "Q21 final-order raw vector columns have unsupported types".to_string(),
        ));
    };
    q21_final_orders_atomic_batch_into(batch, markers)
}

fn q21_final_orders_atomic_dictionary_view_into(
    orderkeys: I64VectorView<'_>,
    statuses: DictionaryI32View<'_>,
    markers: &DenseAtomicU8,
) -> Result<()> {
    store_i64_keys_matching_dictionary_target(orderkeys, statuses, b"F", markers);
    Ok(())
}

fn q21_final_orders_atomic_utf8_view_into(
    orderkeys: I64VectorView<'_>,
    statuses: &StringArray,
    markers: &DenseAtomicU8,
) -> Result<()> {
    store_i64_keys_matching_utf8_target(orderkeys, statuses, b"F", markers);
    Ok(())
}

fn q21_final_orders_atomic_batch_into(batch: &RecordBatch, markers: &DenseAtomicU8) -> Result<()> {
    let orderkeys = batch_column(batch, "o_orderkey")?;
    let statuses = batch_string_column(batch, "o_orderstatus")?;
    if let Some(orderkeys) = orderkeys.as_any().downcast_ref::<Int64Array>() {
        if orderkeys.null_count() == 0 && statuses.null_count() == 0 {
            let status_offsets = statuses.value_offsets();
            let status_data = statuses.value_data();
            for row in 0..orderkeys.len() {
                if bytes_string_parts(status_offsets, status_data, row) == b"F"
                    && let Ok(index) = usize::try_from(orderkeys.value(row))
                {
                    markers.store_present(index);
                }
            }
            return Ok(());
        }
        for row in 0..orderkeys.len() {
            if orderkeys.is_null(row) || statuses.is_null(row) || statuses.value(row) != "F" {
                continue;
            }
            if let Ok(index) = usize::try_from(orderkeys.value(row)) {
                markers.store_present(index);
            }
        }
        return Ok(());
    }
    for row in 0..orderkeys.len() {
        if statuses.is_null(row) || statuses.value(row) != "F" {
            continue;
        }
        if let Some(key) = numeric_i64_value(orderkeys, row)?
            && let Ok(index) = usize::try_from(key)
        {
            markers.store_present(index);
        }
    }
    Ok(())
}

fn q21_final_orders_batch_into(batch: &RecordBatch, keys: &mut Q21FinalOrders) -> Result<()> {
    let orderkeys = batch_column(batch, "o_orderkey")?;
    let statuses = batch_string_column(batch, "o_orderstatus")?;
    if let Some(orderkeys) = orderkeys.as_any().downcast_ref::<Int64Array>() {
        if orderkeys.null_count() == 0 && statuses.null_count() == 0 {
            let status_offsets = statuses.value_offsets();
            let status_data = statuses.value_data();
            for row in 0..orderkeys.len() {
                if bytes_string_parts(status_offsets, status_data, row) == b"F" {
                    keys.insert(orderkeys.value(row));
                }
            }
            return Ok(());
        }
        for row in 0..orderkeys.len() {
            if orderkeys.is_null(row) || statuses.is_null(row) || statuses.value(row) != "F" {
                continue;
            }
            keys.insert(orderkeys.value(row));
        }
        return Ok(());
    }
    for row in 0..orderkeys.len() {
        if statuses.is_null(row) || statuses.value(row) != "F" {
            continue;
        }
        if let Some(key) = numeric_i64_value(orderkeys, row)? {
            keys.insert(key);
        }
    }
    Ok(())
}

#[derive(Clone, Copy, Default)]
struct Q21OrderState {
    first_supplier: i64,
    late_supplier: i64,
    late_row_count: u32,
    flags: u8,
}

impl Q21OrderState {
    const HAS_SUPPLIER: u8 = 1 << 0;
    const HAS_MULTIPLE_SUPPLIERS: u8 = 1 << 1;
    const HAS_LATE_SUPPLIER: u8 = 1 << 2;
    const HAS_MULTIPLE_LATE_SUPPLIERS: u8 = 1 << 3;

    fn has_supplier(&self) -> bool {
        self.flags & Self::HAS_SUPPLIER != 0
    }

    fn has_multiple_suppliers(&self) -> bool {
        self.flags & Self::HAS_MULTIPLE_SUPPLIERS != 0
    }

    fn has_late_supplier(&self) -> bool {
        self.flags & Self::HAS_LATE_SUPPLIER != 0
    }

    fn has_multiple_late_suppliers(&self) -> bool {
        self.flags & Self::HAS_MULTIPLE_LATE_SUPPLIERS != 0
    }

    fn add_supplier(&mut self, suppkey: i64) {
        if !self.has_supplier() {
            self.first_supplier = suppkey;
            self.flags |= Self::HAS_SUPPLIER;
        } else if suppkey != self.first_supplier {
            self.flags |= Self::HAS_MULTIPLE_SUPPLIERS;
        }
    }

    fn add_late_supplier(&mut self, suppkey: i64) {
        if !self.has_late_supplier() {
            self.late_supplier = suppkey;
            self.flags |= Self::HAS_LATE_SUPPLIER;
            self.late_row_count = 1;
        } else if suppkey == self.late_supplier {
            self.late_row_count += 1;
        } else {
            self.flags |= Self::HAS_MULTIPLE_LATE_SUPPLIERS;
        }
    }

    fn has_single_late_supplier(&self) -> bool {
        self.has_late_supplier() && !self.has_multiple_late_suppliers()
    }

    fn merge(&mut self, other: Q21OrderState) {
        if other.has_supplier() {
            self.add_supplier(other.first_supplier);
            if other.has_multiple_suppliers() {
                self.flags |= Self::HAS_MULTIPLE_SUPPLIERS;
            }
        }
        if !other.has_late_supplier() {
            return;
        }
        if !self.has_late_supplier() {
            self.late_supplier = other.late_supplier;
            self.flags |= Self::HAS_LATE_SUPPLIER;
            self.late_row_count = other.late_row_count;
            if other.has_multiple_late_suppliers() {
                self.flags |= Self::HAS_MULTIPLE_LATE_SUPPLIERS;
            }
            return;
        }
        if self.late_supplier == other.late_supplier {
            self.late_row_count += other.late_row_count;
        } else {
            self.flags |= Self::HAS_MULTIPLE_LATE_SUPPLIERS;
        }
        if other.has_multiple_late_suppliers() {
            self.flags |= Self::HAS_MULTIPLE_LATE_SUPPLIERS;
        }
    }
}

type Q21OrderStateMap = FastHashMap<i64, Q21OrderState>;

fn q21_order_state_map() -> Q21OrderStateMap {
    fast_hash_map()
}

fn q21_order_state_map_with_capacity(capacity: usize) -> Q21OrderStateMap {
    fast_hash_map_with_capacity(capacity)
}

async fn q21_lineitem_order_states(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    final_orders: Q21FinalOrders,
) -> Result<Q21OrderStateMap> {
    if q21_dense_order_state_enabled()
        && let Some(dense_index) = q21_dense_final_order_index(&final_orders)
        && let Some(states) =
            q21_lineitem_order_states_dense(engine, path.clone(), batch_size, dense_index).await?
    {
        return Ok(states);
    }
    let projection = Projection::Columns(vec![
        "l_orderkey".to_string(),
        "l_suppkey".to_string(),
        "l_receiptdate".to_string(),
        "l_commitdate".to_string(),
    ]);
    let output_capacity = final_orders.len();
    let final_orders = Arc::new(final_orders);
    if q21_row_group_map_enabled()
        && let Some(partials) = engine
            .parquet_row_group_map_view(
                path.clone(),
                batch_size,
                projection.clone(),
                q21_row_group_map_chunk(),
                q21_order_state_map,
                {
                    let final_orders = final_orders.clone();
                    move |view, states| {
                        q21_lineitem_order_states_projected_view_into(view, &final_orders, states)?;
                        Ok(Some(()))
                    }
                },
                |states| Ok(Some(states)),
            )
            .await?
    {
        let mut output = q21_order_state_map_with_capacity(output_capacity);
        for partial in partials {
            q21_merge_order_states(&mut output, partial);
        }
        return Ok(output);
    }
    let mut stream = engine
        .scan_parquet_batches(path, batch_size, None, projection, None)
        .await?;
    q21_parallel_batch_order_states(
        &mut stream,
        q21_lineitem_order_state_chunk_size(),
        output_capacity,
        move |batches| {
            let mut states = q21_order_state_map();
            for batch in batches {
                q21_lineitem_order_states_projected_batch_into(batch, &final_orders, &mut states)?;
            }
            Ok(states)
        },
    )
}

fn q21_row_group_map_enabled() -> bool {
    std::env::var_os("DODAM_Q21_DISABLE_ROW_GROUP_MAP").is_none()
}

fn q21_row_group_map_chunk() -> usize {
    std::env::var("DODAM_Q21_ROW_GROUP_MAP_CHUNK")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(2)
}

fn q21_dense_order_state_enabled() -> bool {
    std::env::var("DODAM_Q21_ENABLE_DENSE_ORDER_STATE")
        .map(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
        .unwrap_or(false)
}

fn q21_dense_order_state_max_orders() -> usize {
    std::env::var("DODAM_Q21_DENSE_STATE_MAX_ORDERS")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(2_000_000)
}

struct Q21DenseFinalOrderIndex {
    index_by_orderkey: Vec<i32>,
    orderkeys: Vec<i64>,
}

fn q21_dense_final_order_index(
    final_orders: &Q21FinalOrders,
) -> Option<Arc<Q21DenseFinalOrderIndex>> {
    let contains = final_orders.dense_contains_slice()?;
    let selected = final_orders.len();
    if selected > q21_dense_order_state_max_orders() {
        return None;
    }
    let mut index_by_orderkey = vec![-1_i32; contains.len()];
    let mut orderkeys = Vec::with_capacity(selected);
    for (orderkey, selected) in contains.iter().copied().enumerate() {
        if !selected {
            continue;
        }
        let index = i32::try_from(orderkeys.len()).ok()?;
        index_by_orderkey[orderkey] = index;
        orderkeys.push(orderkey as i64);
    }
    Some(Arc::new(Q21DenseFinalOrderIndex {
        index_by_orderkey,
        orderkeys,
    }))
}

async fn q21_lineitem_order_states_dense(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    dense_index: Arc<Q21DenseFinalOrderIndex>,
) -> Result<Option<Q21OrderStateMap>> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec![
                "l_orderkey".to_string(),
                "l_suppkey".to_string(),
                "l_receiptdate".to_string(),
                "l_commitdate".to_string(),
            ]),
            None,
        )
        .await?;
    q21_parallel_dense_order_states(
        &mut stream,
        q21_lineitem_order_state_chunk_size(),
        dense_index,
    )
}

fn q21_parallel_dense_order_states(
    stream: &mut SendableBatchStream,
    chunk_size: usize,
    dense_index: Arc<Q21DenseFinalOrderIndex>,
) -> Result<Option<Q21OrderStateMap>> {
    let profile = tpch_profile_enabled();
    let started = profile.then(Instant::now);
    let (sender, receiver) = mpsc::channel();
    let chunk_size = chunk_size.max(1);
    let mut pending_chunks = 0_usize;
    let mut chunk = Vec::with_capacity(chunk_size);
    let stream_started = profile.then(Instant::now);
    while let Some(batch) = stream.next() {
        chunk.push(batch?);
        if chunk.len() < chunk_size {
            continue;
        }
        let sender = sender.clone();
        let dense_index = dense_index.clone();
        let task_chunk = std::mem::replace(&mut chunk, Vec::with_capacity(chunk_size));
        pending_chunks += 1;
        rayon::spawn(move || {
            let _ = sender.send(q21_dense_order_states_chunk(task_chunk, dense_index));
        });
    }
    if !chunk.is_empty() {
        let sender = sender.clone();
        let dense_index = dense_index.clone();
        pending_chunks += 1;
        rayon::spawn(move || {
            let _ = sender.send(q21_dense_order_states_chunk(chunk, dense_index));
        });
    }
    let stream_ms = stream_started
        .map(|started| started.elapsed().as_secs_f64() * 1000.0)
        .unwrap_or_default();
    drop(sender);
    let merge_started = profile.then(Instant::now);
    let mut output = Q21DenseOrderStates::new(dense_index.orderkeys.len());
    for _ in 0..pending_chunks {
        let partial = receiver
            .recv()
            .map_err(|_| DodamError::UnsupportedSql("Q21 dense worker stopped".to_string()))??;
        output.merge(partial);
    }
    let states = output.into_map(&dense_index.orderkeys);
    if let Some(started) = started {
        let merge_ms = merge_started
            .map(|started| started.elapsed().as_secs_f64() * 1000.0)
            .unwrap_or_default();
        eprintln!(
            "[dodam:tpch-profile] Q21 dense lineitem order states: total={:.3} ms stream_read={:.3} ms worker_wait_merge={:.3} ms chunks={pending_chunks}",
            started.elapsed().as_secs_f64() * 1000.0,
            stream_ms,
            merge_ms
        );
    }
    Ok(Some(states))
}

fn q21_dense_order_states_chunk(
    batches: Vec<RecordBatch>,
    dense_index: Arc<Q21DenseFinalOrderIndex>,
) -> Result<Q21DenseOrderStates> {
    let mut states = Q21DenseOrderStates::new(dense_index.orderkeys.len());
    for batch in batches {
        if !q21_dense_order_states_batch_into(&batch, &dense_index, &mut states)? {
            return Err(DodamError::UnsupportedSql(
                "Q21 dense order-state path requires typed lineitem columns".to_string(),
            ));
        }
    }
    Ok(states)
}

struct Q21DenseOrderStates {
    positions: Vec<i32>,
    states: Vec<Q21OrderState>,
    touched: Vec<usize>,
}

impl Q21DenseOrderStates {
    fn new(len: usize) -> Self {
        Self {
            positions: vec![-1; len],
            states: Vec::new(),
            touched: Vec::new(),
        }
    }

    fn state_mut(&mut self, index: usize) -> &mut Q21OrderState {
        let position = self.positions[index];
        let position = if position < 0 {
            let position = self.states.len();
            self.positions[index] = i32::try_from(position).expect("Q21 state index overflow");
            self.states.push(Q21OrderState::default());
            self.touched.push(index);
            position
        } else {
            position as usize
        };
        &mut self.states[position]
    }

    fn merge(&mut self, other: Self) {
        for index in other.touched {
            let position = other.positions[index];
            debug_assert!(position >= 0);
            self.state_mut(index).merge(other.states[position as usize]);
        }
    }

    fn into_map(self, orderkeys: &[i64]) -> Q21OrderStateMap {
        let mut output = q21_order_state_map_with_capacity(self.touched.len());
        for index in self.touched {
            let position = self.positions[index];
            debug_assert!(position >= 0);
            output.insert(orderkeys[index], self.states[position as usize]);
        }
        output
    }
}

fn q21_dense_order_states_batch_into(
    batch: &RecordBatch,
    dense_index: &Q21DenseFinalOrderIndex,
    states: &mut Q21DenseOrderStates,
) -> Result<bool> {
    let orderkeys = batch_column(batch, "l_orderkey")?;
    let suppkeys = batch_column(batch, "l_suppkey")?;
    let receipt = batch_column(batch, "l_receiptdate")?;
    let commit = batch_column(batch, "l_commitdate")?;
    let (Some(orderkeys), Some(suppkeys), Some(receipt), Some(commit)) = (
        orderkeys.as_any().downcast_ref::<Int64Array>(),
        suppkeys.as_any().downcast_ref::<Int64Array>(),
        receipt.as_any().downcast_ref::<Date32Array>(),
        commit.as_any().downcast_ref::<Date32Array>(),
    ) else {
        return Ok(false);
    };
    if orderkeys.null_count() == 0
        && suppkeys.null_count() == 0
        && receipt.null_count() == 0
        && commit.null_count() == 0
    {
        let orderkeys = orderkeys.values().as_ref();
        let suppkeys = suppkeys.values().as_ref();
        let receipts = receipt.values().as_ref();
        let commits = commit.values().as_ref();
        for row in 0..orderkeys.len() {
            let Some(index) = q21_dense_order_index(dense_index, orderkeys[row]) else {
                continue;
            };
            let state = states.state_mut(index);
            let suppkey = suppkeys[row];
            state.add_supplier(suppkey);
            if receipts[row] > commits[row] {
                state.add_late_supplier(suppkey);
            }
        }
        return Ok(true);
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row) || suppkeys.is_null(row) {
            continue;
        }
        let Some(index) = q21_dense_order_index(dense_index, orderkeys.value(row)) else {
            continue;
        };
        let state = states.state_mut(index);
        let suppkey = suppkeys.value(row);
        state.add_supplier(suppkey);
        if receipt.is_null(row) || commit.is_null(row) {
            continue;
        }
        if receipt.value(row) > commit.value(row) {
            state.add_late_supplier(suppkey);
        }
    }
    Ok(true)
}

fn q21_dense_order_index(dense_index: &Q21DenseFinalOrderIndex, orderkey: i64) -> Option<usize> {
    let index = usize::try_from(orderkey).ok()?;
    let compact = *dense_index.index_by_orderkey.get(index)?;
    usize::try_from(compact).ok()
}

fn q21_parallel_batch_order_states<Map>(
    stream: &mut SendableBatchStream,
    chunk_size: usize,
    output_capacity: usize,
    map: Map,
) -> Result<Q21OrderStateMap>
where
    Map: Fn(Vec<RecordBatch>) -> Result<Q21OrderStateMap> + Send + Sync + Clone + 'static,
{
    let profile = tpch_profile_enabled();
    let started = profile.then(Instant::now);
    let (sender, receiver) = mpsc::channel();
    let chunk_size = chunk_size.max(1);
    let mut pending_chunks = 0_usize;
    let mut chunk = Vec::with_capacity(chunk_size);
    let stream_started = profile.then(Instant::now);
    while let Some(batch) = stream.next() {
        chunk.push(batch?);
        if chunk.len() < chunk_size {
            continue;
        }
        let sender = sender.clone();
        let map = map.clone();
        let task_chunk = std::mem::replace(&mut chunk, Vec::with_capacity(chunk_size));
        pending_chunks += 1;
        rayon::spawn(move || {
            let _ = sender.send(map(task_chunk));
        });
    }
    if !chunk.is_empty() {
        let sender = sender.clone();
        let map = map.clone();
        pending_chunks += 1;
        rayon::spawn(move || {
            let _ = sender.send(map(chunk));
        });
    }
    let stream_ms = stream_started
        .map(|started| started.elapsed().as_secs_f64() * 1000.0)
        .unwrap_or_default();
    drop(sender);
    let merge_started = profile.then(Instant::now);
    let mut partials = Vec::with_capacity(pending_chunks);
    for _ in 0..pending_chunks {
        partials.push(
            receiver
                .recv()
                .map_err(|_| DodamError::UnsupportedSql("Q21 worker stopped".to_string()))??,
        );
    }
    let output = if q21_parallel_merge_enabled() {
        partials
            .into_par_iter()
            .reduce(q21_order_state_map, q21_merge_order_states_owned)
    } else {
        let mut output = q21_order_state_map_with_capacity(output_capacity);
        for partial in partials {
            q21_merge_order_states(&mut output, partial);
        }
        output
    };
    if let Some(started) = started {
        let merge_ms = merge_started
            .map(|started| started.elapsed().as_secs_f64() * 1000.0)
            .unwrap_or_default();
        eprintln!(
            "[dodam:tpch-profile] Q21 lineitem order states: total={:.3} ms stream_read={:.3} ms worker_wait_merge={:.3} ms chunks={pending_chunks}",
            started.elapsed().as_secs_f64() * 1000.0,
            stream_ms,
            merge_ms
        );
    }
    Ok(output)
}

fn q21_parallel_merge_enabled() -> bool {
    std::env::var("DODAM_Q21_ENABLE_PARALLEL_MERGE")
        .map(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
        .unwrap_or(false)
}

fn q21_lineitem_order_state_chunk_size() -> usize {
    std::env::var("DODAM_Q21_CHUNK_SIZE")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(48)
}

fn q21_lineitem_order_states_batch_into(
    batch: RecordBatch,
    final_orders: &Q21FinalOrders,
    states: &mut Q21OrderStateMap,
) -> Result<()> {
    let orderkeys = batch_column(&batch, "l_orderkey")?;
    let suppkeys = batch_column(&batch, "l_suppkey")?;
    let receipt = batch_column(&batch, "l_receiptdate")?;
    let commit = batch_column(&batch, "l_commitdate")?;
    if q21_lineitem_order_states_typed_into(
        orderkeys,
        suppkeys,
        receipt,
        commit,
        final_orders,
        states,
    ) {
        return Ok(());
    }
    let dense_final_orders = final_orders.dense_contains_slice();
    for row in 0..batch.num_rows() {
        let (Some(orderkey), Some(suppkey)) = (
            numeric_i64_value(orderkeys, row)?,
            numeric_i64_value(suppkeys, row)?,
        ) else {
            continue;
        };
        if !q21_final_order_contains(final_orders, dense_final_orders, orderkey) {
            continue;
        }
        let state = states.entry(orderkey).or_default();
        state.add_supplier(suppkey);
        let (Some(receipt), Some(commit)) =
            (date32_value(receipt, row)?, date32_value(commit, row)?)
        else {
            continue;
        };
        if receipt > commit {
            state.add_late_supplier(suppkey);
        }
    }
    Ok(())
}

fn q21_lineitem_order_states_projected_batch_into(
    batch: RecordBatch,
    final_orders: &Q21FinalOrders,
    states: &mut Q21OrderStateMap,
) -> Result<()> {
    if batch.num_columns() == 4
        && q21_lineitem_order_states_typed_into(
            batch.column(0),
            batch.column(1),
            batch.column(2),
            batch.column(3),
            final_orders,
            states,
        )
    {
        return Ok(());
    }
    q21_lineitem_order_states_batch_into(batch, final_orders, states)
}

fn q21_lineitem_order_states_projected_view_into(
    view: BatchView<'_>,
    final_orders: &Q21FinalOrders,
    states: &mut Q21OrderStateMap,
) -> Result<()> {
    if view.num_columns() == 4
        && let (Some(orderkeys), Some(suppkeys), Some(receipt), Some(commit)) = (
            view.i64_vector(0),
            view.i64_vector(1),
            view.date32_vector(2),
            view.date32_vector(3),
        )
    {
        q21_lineitem_order_states_vector_typed_into(
            orderkeys,
            suppkeys,
            receipt,
            commit,
            final_orders,
            states,
        );
        return Ok(());
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(());
    };
    q21_lineitem_order_states_batch_into(batch.clone(), final_orders, states)
}

fn q21_lineitem_order_states_typed_into(
    orderkeys: &ArrayRef,
    suppkeys: &ArrayRef,
    receipt: &ArrayRef,
    commit: &ArrayRef,
    final_orders: &Q21FinalOrders,
    states: &mut Q21OrderStateMap,
) -> bool {
    let (Some(orderkeys), Some(suppkeys), Some(receipt), Some(commit)) = (
        orderkeys.as_any().downcast_ref::<Int64Array>(),
        suppkeys.as_any().downcast_ref::<Int64Array>(),
        receipt.as_any().downcast_ref::<Date32Array>(),
        commit.as_any().downcast_ref::<Date32Array>(),
    ) else {
        return false;
    };
    let dense_final_orders = final_orders.dense_contains_slice();
    if orderkeys.null_count() == 0
        && suppkeys.null_count() == 0
        && receipt.null_count() == 0
        && commit.null_count() == 0
    {
        let orderkeys = orderkeys.values().as_ref();
        let suppkeys = suppkeys.values().as_ref();
        let receipts = receipt.values().as_ref();
        let commits = commit.values().as_ref();
        let mut current_orderkey = None::<i64>;
        let mut current_order_selected = false;
        let mut current_state = Q21OrderState::default();
        for row in 0..orderkeys.len() {
            let orderkey = orderkeys[row];
            if current_orderkey.is_some_and(|current| current != orderkey) {
                if current_order_selected {
                    q21_flush_run_state(states, current_orderkey, &mut current_state);
                }
                current_order_selected =
                    q21_final_order_contains(final_orders, dense_final_orders, orderkey);
                current_orderkey = Some(orderkey);
            } else if current_orderkey.is_none() {
                current_order_selected =
                    q21_final_order_contains(final_orders, dense_final_orders, orderkey);
                current_orderkey = Some(orderkey);
            }
            if !current_order_selected {
                continue;
            }
            let suppkey = suppkeys[row];
            current_state.add_supplier(suppkey);
            if receipts[row] > commits[row] {
                current_state.add_late_supplier(suppkey);
            }
        }
        if current_order_selected {
            q21_flush_run_state(states, current_orderkey, &mut current_state);
        }
        return true;
    }
    let mut current_orderkey = None::<i64>;
    let mut current_order_selected = false;
    let mut current_state = Q21OrderState::default();
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row) || suppkeys.is_null(row) {
            continue;
        }
        let orderkey = orderkeys.value(row);
        if current_orderkey.is_some_and(|current| current != orderkey) {
            if current_order_selected {
                q21_flush_run_state(states, current_orderkey, &mut current_state);
            }
            current_order_selected =
                q21_final_order_contains(final_orders, dense_final_orders, orderkey);
            current_orderkey = Some(orderkey);
        } else if current_orderkey.is_none() {
            current_order_selected =
                q21_final_order_contains(final_orders, dense_final_orders, orderkey);
            current_orderkey = Some(orderkey);
        }
        if !current_order_selected {
            continue;
        }
        let suppkey = suppkeys.value(row);
        current_state.add_supplier(suppkey);
        if receipt.is_null(row) || commit.is_null(row) {
            continue;
        }
        if receipt.value(row) > commit.value(row) {
            current_state.add_late_supplier(suppkey);
        }
    }
    if current_order_selected {
        q21_flush_run_state(states, current_orderkey, &mut current_state);
    }
    true
}

fn q21_lineitem_order_states_vector_typed_into(
    orderkeys: I64VectorView<'_>,
    suppkeys: I64VectorView<'_>,
    receipt: Date32VectorView<'_>,
    commit: Date32VectorView<'_>,
    final_orders: &Q21FinalOrders,
    states: &mut Q21OrderStateMap,
) {
    let dense_final_orders = final_orders.dense_contains_slice();
    if let (Some(orderkey_values), Some(suppkey_values), Some(receipts), Some(commits)) = (
        orderkeys.values_if_null_free(),
        suppkeys.values_if_null_free(),
        receipt.values_if_null_free(),
        commit.values_if_null_free(),
    ) {
        let mut current_orderkey = None::<i64>;
        let mut current_order_selected = false;
        let mut current_state = Q21OrderState::default();
        for row in 0..orderkey_values.len() {
            let orderkey = orderkey_values[row];
            if current_orderkey.is_some_and(|current| current != orderkey) {
                if current_order_selected {
                    q21_flush_run_state(states, current_orderkey, &mut current_state);
                }
                current_order_selected =
                    q21_final_order_contains(final_orders, dense_final_orders, orderkey);
                current_orderkey = Some(orderkey);
            } else if current_orderkey.is_none() {
                current_order_selected =
                    q21_final_order_contains(final_orders, dense_final_orders, orderkey);
                current_orderkey = Some(orderkey);
            }
            if !current_order_selected {
                continue;
            }
            let suppkey = suppkey_values[row];
            current_state.add_supplier(suppkey);
            if receipts[row] > commits[row] {
                current_state.add_late_supplier(suppkey);
            }
        }
        if current_order_selected {
            q21_flush_run_state(states, current_orderkey, &mut current_state);
        }
        return;
    }
    let mut current_orderkey = None::<i64>;
    let mut current_order_selected = false;
    let mut current_state = Q21OrderState::default();
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row) || suppkeys.is_null(row) {
            continue;
        }
        let orderkey = orderkeys.value(row);
        if current_orderkey.is_some_and(|current| current != orderkey) {
            if current_order_selected {
                q21_flush_run_state(states, current_orderkey, &mut current_state);
            }
            current_order_selected =
                q21_final_order_contains(final_orders, dense_final_orders, orderkey);
            current_orderkey = Some(orderkey);
        } else if current_orderkey.is_none() {
            current_order_selected =
                q21_final_order_contains(final_orders, dense_final_orders, orderkey);
            current_orderkey = Some(orderkey);
        }
        if !current_order_selected {
            continue;
        }
        let suppkey = suppkeys.value(row);
        current_state.add_supplier(suppkey);
        if receipt.is_null(row) || commit.is_null(row) {
            continue;
        }
        if receipt.value(row) > commit.value(row) {
            current_state.add_late_supplier(suppkey);
        }
    }
    if current_order_selected {
        q21_flush_run_state(states, current_orderkey, &mut current_state);
    }
}

fn q21_final_order_contains(
    final_orders: &Q21FinalOrders,
    dense_final_orders: Option<&[bool]>,
    orderkey: i64,
) -> bool {
    if let Some(dense_final_orders) = dense_final_orders {
        return usize::try_from(orderkey)
            .ok()
            .and_then(|index| dense_final_orders.get(index))
            .copied()
            .unwrap_or(false);
    }
    final_orders.contains(orderkey)
}

async fn q21_lineitem_supplier_counts_ordered(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    final_orders: &Q21FinalOrders,
    suppliers: &HashMap<i64, String>,
) -> Result<Option<HashMap<i64, u64>>> {
    let projection = Projection::Columns(vec![
        "l_orderkey".to_string(),
        "l_suppkey".to_string(),
        "l_receiptdate".to_string(),
        "l_commitdate".to_string(),
    ]);
    let final_orders = Arc::new(final_orders.clone());
    let suppliers = Arc::new(suppliers.clone());
    let Some(chunks) = engine
        .parquet_row_group_map_view(
            path,
            batch_size,
            projection,
            q21_row_group_map_chunk(),
            Q21OrderedLineitemChunkState::default,
            {
                let final_orders = final_orders.clone();
                let suppliers = suppliers.clone();
                move |view, state| {
                    q21_ordered_lineitem_chunk_view(view, &final_orders, suppliers.as_ref(), state)
                }
            },
            |state| Ok(Some(state)),
        )
        .await?
    else {
        return Ok(None);
    };
    Ok(Some(q21_merge_ordered_lineitem_chunks(
        chunks,
        suppliers.as_ref(),
    )))
}

#[derive(Default)]
struct Q21OrderedLineitemChunkState {
    counts: HashMap<i64, u64>,
    current_orderkey: Option<i64>,
    current_selected: bool,
    current_state: Q21OrderState,
    first: Option<OrderedRowGroupBoundary<i64, Q21SelectedOrderState>>,
    last: Option<OrderedRowGroupBoundary<i64, Q21SelectedOrderState>>,
    order_count: usize,
}

#[derive(Clone, Copy, Default)]
struct Q21SelectedOrderState {
    selected: bool,
    state: Q21OrderState,
}

fn q21_ordered_lineitem_chunk_view(
    view: BatchView<'_>,
    final_orders: &Q21FinalOrders,
    suppliers: &HashMap<i64, String>,
    state: &mut Q21OrderedLineitemChunkState,
) -> Result<Option<()>> {
    if view.num_columns() == 4
        && let (Some(orderkeys), Some(suppkeys), Some(receipt), Some(commit)) = (
            view.i64_vector(0),
            view.i64_vector(1),
            view.date32_vector(2),
            view.date32_vector(3),
        )
    {
        return q21_ordered_lineitem_chunk_vector_typed(
            orderkeys,
            suppkeys,
            receipt,
            commit,
            final_orders,
            suppliers,
            state,
        );
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(None);
    };
    q21_ordered_lineitem_chunk_batch(batch, final_orders, suppliers, state)
}

fn q21_ordered_lineitem_chunk_batch(
    batch: &RecordBatch,
    final_orders: &Q21FinalOrders,
    suppliers: &HashMap<i64, String>,
    state: &mut Q21OrderedLineitemChunkState,
) -> Result<Option<()>> {
    if batch.num_columns() == 4
        && let (Some(orderkeys), Some(suppkeys), Some(receipt), Some(commit)) = (
            batch.column(0).as_any().downcast_ref::<Int64Array>(),
            batch.column(1).as_any().downcast_ref::<Int64Array>(),
            batch.column(2).as_any().downcast_ref::<Date32Array>(),
            batch.column(3).as_any().downcast_ref::<Date32Array>(),
        )
    {
        return q21_ordered_lineitem_chunk_typed_batch(
            orderkeys,
            suppkeys,
            receipt,
            commit,
            final_orders,
            suppliers,
            state,
        );
    }
    Ok(None)
}

fn q21_ordered_lineitem_chunk_typed_batch(
    orderkeys: &Int64Array,
    suppkeys: &Int64Array,
    receipt: &Date32Array,
    commit: &Date32Array,
    final_orders: &Q21FinalOrders,
    suppliers: &HashMap<i64, String>,
    chunk: &mut Q21OrderedLineitemChunkState,
) -> Result<Option<()>> {
    let dense_final_orders = final_orders.dense_contains_slice();
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row) || suppkeys.is_null(row) {
            continue;
        }
        let orderkey = orderkeys.value(row);
        if let Some(current) = chunk.current_orderkey {
            if orderkey < current {
                return Ok(None);
            }
            if orderkey != current {
                q21_ordered_chunk_finish_current(chunk, suppliers);
                chunk.current_orderkey = Some(orderkey);
                chunk.current_selected =
                    q21_final_order_contains(final_orders, dense_final_orders, orderkey);
                chunk.current_state = Q21OrderState::default();
                chunk.order_count += 1;
            }
        } else {
            chunk.current_orderkey = Some(orderkey);
            chunk.current_selected =
                q21_final_order_contains(final_orders, dense_final_orders, orderkey);
            chunk.order_count = 1;
        }
        if !chunk.current_selected {
            continue;
        }
        let suppkey = suppkeys.value(row);
        chunk.current_state.add_supplier(suppkey);
        if receipt.is_valid(row) && commit.is_valid(row) && receipt.value(row) > commit.value(row) {
            chunk.current_state.add_late_supplier(suppkey);
        }
    }
    Ok(Some(()))
}

fn q21_ordered_lineitem_chunk_vector_typed(
    orderkeys: I64VectorView<'_>,
    suppkeys: I64VectorView<'_>,
    receipt: Date32VectorView<'_>,
    commit: Date32VectorView<'_>,
    final_orders: &Q21FinalOrders,
    suppliers: &HashMap<i64, String>,
    chunk: &mut Q21OrderedLineitemChunkState,
) -> Result<Option<()>> {
    let dense_final_orders = final_orders.dense_contains_slice();
    if let (Some(orderkey_values), Some(suppkey_values), Some(receipts), Some(commits)) = (
        orderkeys.values_if_null_free(),
        suppkeys.values_if_null_free(),
        receipt.values_if_null_free(),
        commit.values_if_null_free(),
    ) {
        for row in 0..orderkey_values.len() {
            let orderkey = orderkey_values[row];
            if let Some(current) = chunk.current_orderkey {
                if orderkey < current {
                    return Ok(None);
                }
                if orderkey != current {
                    q21_ordered_chunk_finish_current(chunk, suppliers);
                    chunk.current_orderkey = Some(orderkey);
                    chunk.current_selected =
                        q21_final_order_contains(final_orders, dense_final_orders, orderkey);
                    chunk.current_state = Q21OrderState::default();
                    chunk.order_count += 1;
                }
            } else {
                chunk.current_orderkey = Some(orderkey);
                chunk.current_selected =
                    q21_final_order_contains(final_orders, dense_final_orders, orderkey);
                chunk.order_count = 1;
            }
            if !chunk.current_selected {
                continue;
            }
            let suppkey = suppkey_values[row];
            chunk.current_state.add_supplier(suppkey);
            if receipts[row] > commits[row] {
                chunk.current_state.add_late_supplier(suppkey);
            }
        }
        return Ok(Some(()));
    }
    for row in 0..orderkeys.len() {
        if orderkeys.is_null(row) || suppkeys.is_null(row) {
            continue;
        }
        let orderkey = orderkeys.value(row);
        if let Some(current) = chunk.current_orderkey {
            if orderkey < current {
                return Ok(None);
            }
            if orderkey != current {
                q21_ordered_chunk_finish_current(chunk, suppliers);
                chunk.current_orderkey = Some(orderkey);
                chunk.current_selected =
                    q21_final_order_contains(final_orders, dense_final_orders, orderkey);
                chunk.current_state = Q21OrderState::default();
                chunk.order_count += 1;
            }
        } else {
            chunk.current_orderkey = Some(orderkey);
            chunk.current_selected =
                q21_final_order_contains(final_orders, dense_final_orders, orderkey);
            chunk.order_count = 1;
        }
        if !chunk.current_selected {
            continue;
        }
        let suppkey = suppkeys.value(row);
        chunk.current_state.add_supplier(suppkey);
        if !receipt.is_null(row) && !commit.is_null(row) && receipt.value(row) > commit.value(row) {
            chunk.current_state.add_late_supplier(suppkey);
        }
    }
    Ok(Some(()))
}

fn q21_ordered_chunk_finish_current(
    chunk: &mut Q21OrderedLineitemChunkState,
    suppliers: &HashMap<i64, String>,
) {
    let Some(orderkey) = chunk.current_orderkey else {
        return;
    };
    let boundary = OrderedRowGroupBoundary {
        key: orderkey,
        state: Q21SelectedOrderState {
            selected: chunk.current_selected,
            state: chunk.current_state,
        },
    };
    if chunk.order_count == 1 {
        chunk.first = Some(boundary);
    } else if boundary.state.selected {
        q21_count_qualifying_order(&mut chunk.counts, suppliers, &boundary.state.state);
    }
}

fn q21_merge_ordered_lineitem_chunks(
    mut chunks: Vec<Q21OrderedLineitemChunkState>,
    suppliers: &HashMap<i64, String>,
) -> HashMap<i64, u64> {
    let mut ordered_chunks = Vec::with_capacity(chunks.len());
    for mut chunk in chunks.drain(..) {
        if let Some(orderkey) = chunk.current_orderkey {
            let boundary = OrderedRowGroupBoundary {
                key: orderkey,
                state: Q21SelectedOrderState {
                    selected: chunk.current_selected,
                    state: chunk.current_state,
                },
            };
            if chunk.order_count <= 1 {
                chunk.first = Some(boundary);
            } else {
                chunk.last = Some(boundary);
            }
        }
        ordered_chunks.push(OrderedRowGroupChunk {
            output: chunk.counts,
            first: chunk.first,
            last: chunk.last,
        });
    }
    let mut counts = HashMap::<i64, u64>::with_capacity(suppliers.len());
    merge_ordered_row_group_chunks(
        ordered_chunks,
        &mut counts,
        |counts, chunk_counts| {
            for (suppkey, count) in chunk_counts {
                *counts.entry(suppkey).or_insert(0) += count;
            }
        },
        |left, right| {
            left.selected |= right.selected;
            left.state.merge(right.state);
        },
        |counts, boundary| {
            if boundary.state.selected {
                q21_count_qualifying_order(counts, suppliers, &boundary.state.state);
            }
        },
    );
    counts
}

fn q21_count_qualifying_order(
    counts: &mut HashMap<i64, u64>,
    suppliers: &HashMap<i64, String>,
    state: &Q21OrderState,
) {
    if !state.has_multiple_suppliers() || !state.has_single_late_supplier() {
        return;
    }
    let suppkey = state.late_supplier;
    if !suppliers.contains_key(&suppkey) {
        return;
    }
    *counts.entry(suppkey).or_insert(0) += u64::from(state.late_row_count);
}

fn q21_flush_run_state(
    states: &mut Q21OrderStateMap,
    orderkey: Option<i64>,
    state: &mut Q21OrderState,
) {
    let Some(orderkey) = orderkey else {
        return;
    };
    states
        .entry(orderkey)
        .or_default()
        .merge(std::mem::take(state));
}

fn q21_merge_order_states(states: &mut Q21OrderStateMap, batch_states: Q21OrderStateMap) {
    for (orderkey, batch_state) in batch_states {
        states.entry(orderkey).or_default().merge(batch_state);
    }
}

fn q21_merge_order_states_owned(
    mut left: Q21OrderStateMap,
    mut right: Q21OrderStateMap,
) -> Q21OrderStateMap {
    if left.len() < right.len() {
        std::mem::swap(&mut left, &mut right);
    }
    q21_merge_order_states(&mut left, right);
    left
}

struct Q21Row {
    s_name: String,
    count: u64,
}

fn q21_output(rows: Vec<Q21Row>) -> Result<QueryOutput> {
    let batch = RecordBatch::try_new(
        Arc::new(Schema::new(vec![
            Field::new("s_name", DataType::Utf8, false),
            Field::new("numwait", DataType::UInt64, false),
        ])),
        vec![
            Arc::new(StringArray::from_iter_values(
                rows.iter().map(|row| row.s_name.as_str()),
            )),
            Arc::new(UInt64Array::from_iter_values(
                rows.iter().map(|row| row.count),
            )),
        ],
    )?;
    Ok(QueryOutput::Aggregate {
        metrics: AggregateMetrics::default(),
        batches: vec![batch],
    })
}

async fn try_execute_prefix_part_supplier_threshold_sql(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(None);
    };
    let Some(selection) = select.selection.as_ref() else {
        return Ok(None);
    };
    if !prefix_part_supplier_threshold_shape(select, selection) {
        return Ok(None);
    }
    reject_query_features(query)?;
    reject_select_features(select)?;
    let Some(tables) = parse_comma_join_table_refs(select)? else {
        return Ok(None);
    };
    if tables.len() != 2 {
        return Ok(None);
    }
    let mut supplier = None;
    let mut nation = None;
    for table in tables {
        let alias = table_ref_alias_or_name(&table);
        if alias.eq_ignore_ascii_case("supplier") {
            supplier = Some(table);
        } else if alias.eq_ignore_ascii_case("nation") {
            nation = Some(table);
        }
    }
    let (Some(supplier), Some(nation)) = (supplier, nation) else {
        return Ok(None);
    };
    let Some(partsupp_path) = first_table_path_in_subqueries(selection, "partsupp")? else {
        return Ok(None);
    };
    let Some(part_path) = first_table_path_in_subqueries(selection, "part")? else {
        return Ok(None);
    };
    let Some(lineitem_path) = first_table_path_in_subqueries(selection, "lineitem")? else {
        return Ok(None);
    };

    let stage = tpch_profile_start();
    let forest_parts = q20_forest_part_keys(engine, part_path, batch_size).await?;
    tpch_profile_elapsed("Q20 forest part keys", stage);
    if forest_parts.is_empty() {
        return Ok(Some(q20_output(Vec::new())?));
    }
    let forest_parts = AdaptiveI64Set::from_hash(forest_parts);
    let stage = tpch_profile_start();
    let lineitem_sums =
        q20_lineitem_quantity_sums(engine, lineitem_path, batch_size, &forest_parts).await?;
    tpch_profile_elapsed("Q20 lineitem quantity sums", stage);
    let stage = tpch_profile_start();
    let eligible_suppliers = q20_eligible_supplier_keys(
        engine,
        partsupp_path,
        batch_size,
        &forest_parts,
        &lineitem_sums,
    )
    .await?;
    tpch_profile_elapsed("Q20 eligible suppliers", stage);
    if eligible_suppliers.is_empty() {
        return Ok(Some(q20_output(Vec::new())?));
    }
    let stage = tpch_profile_start();
    let nation_keys = q21_nation_keys(engine, nation.path, batch_size, "CANADA").await?;
    tpch_profile_elapsed("Q20 nation keys", stage);
    let stage = tpch_profile_start();
    let mut rows = q20_supplier_rows(
        engine,
        supplier.path,
        batch_size,
        &nation_keys,
        &eligible_suppliers,
    )
    .await?;
    tpch_profile_elapsed("Q20 supplier rows", stage);
    let stage = tpch_profile_start();
    rows.sort_by(|left, right| left.s_name.cmp(&right.s_name));
    tpch_profile_elapsed("Q20 final sort", stage);
    Ok(Some(q20_output(rows)?))
}

fn prefix_part_supplier_threshold_shape(select: &Select, selection: &SqlExpr) -> bool {
    let text = selection.to_string().to_ascii_lowercase();
    select.projection.len() == 2
        && text.contains("s_suppkey in")
        && text.contains("p_name like 'forest%'")
        && text.contains("ps_availqty >")
        && text.contains("0.5 * sum(l_quantity)")
        && text.contains("n_name = 'canada'")
}

async fn q20_forest_part_keys(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
) -> Result<HashSet<i64>> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec!["p_partkey".to_string(), "p_name".to_string()]),
            None,
        )
        .await?;
    let mut keys = HashSet::new();
    while let Some(batch) = stream.next() {
        let batch = batch?;
        let partkeys = batch_column(&batch, "p_partkey")?;
        let names = batch_string_column(&batch, "p_name")?;
        for row in 0..batch.num_rows() {
            if names.is_valid(row)
                && names.value(row).starts_with("forest")
                && let Some(key) = numeric_i64_value(partkeys, row)?
            {
                keys.insert(key);
            }
        }
    }
    Ok(keys)
}

async fn q20_lineitem_quantity_sums(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    forest_parts: &AdaptiveI64Set,
) -> Result<HashMap<(i64, i64), f64>> {
    let forest_parts = Arc::new(forest_parts.clone());
    engine
        .parquet_scan_accumulate_chunks_view(
            path,
            batch_size,
            Projection::Columns(vec![
                "l_partkey".to_string(),
                "l_suppkey".to_string(),
                "l_quantity".to_string(),
                "l_shipdate".to_string(),
            ]),
            scan_aggregate_row_group_chunk(),
            4,
            scan_aggregate_fusion_enabled(),
            HashMap::<(i64, i64), f64>::new,
            HashMap::<(i64, i64), f64>::new,
            move |view, sums| {
                q20_lineitem_quantity_sums_view_into(view, &forest_parts, sums)?;
                Ok(Some(()))
            },
            merge_f64_groups,
            "Q20 lineitem quantity aggregate",
        )
        .await
}

fn q20_lineitem_quantity_sums_view_into(
    view: BatchView<'_>,
    forest_parts: &AdaptiveI64Set,
    sums: &mut HashMap<(i64, i64), f64>,
) -> Result<()> {
    if view.num_columns() == 4
        && let (Some(partkeys), Some(suppkeys), Some(quantities), Some(shipdates)) = (
            view.i64_vector(0),
            view.i64_vector(1),
            view.decimal128_vector(2),
            view.date32_vector(3),
        )
        && let Some(batch_sums) = q20_lineitem_quantity_sums_vector_typed(
            partkeys,
            suppkeys,
            quantities,
            shipdates,
            forest_parts,
        )
    {
        merge_f64_groups(sums, batch_sums);
        return Ok(());
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(());
    };
    merge_f64_groups(
        sums,
        q20_lineitem_quantity_sums_batch(batch.clone(), forest_parts)?,
    );
    Ok(())
}

fn q20_lineitem_quantity_sums_batch(
    batch: RecordBatch,
    forest_parts: &AdaptiveI64Set,
) -> Result<HashMap<(i64, i64), f64>> {
    let partkeys = batch_column(&batch, "l_partkey")?;
    let suppkeys = batch_column(&batch, "l_suppkey")?;
    let quantities = batch_column(&batch, "l_quantity")?;
    let shipdates = batch_column(&batch, "l_shipdate")?;
    if let Some(sums) =
        q20_lineitem_quantity_sums_typed(partkeys, suppkeys, quantities, shipdates, forest_parts)?
    {
        return Ok(sums);
    }
    let mut sums = HashMap::<(i64, i64), f64>::new();
    for row in 0..batch.num_rows() {
        let Some(shipdate) = date32_value(shipdates, row)? else {
            continue;
        };
        if !(8_766..9_131).contains(&shipdate) {
            continue;
        }
        let (Some(partkey), Some(suppkey), Some(quantity)) = (
            numeric_i64_value(partkeys, row)?,
            numeric_i64_value(suppkeys, row)?,
            numeric_f64_value(quantities, row)?,
        ) else {
            continue;
        };
        if forest_parts.contains(partkey) {
            *sums.entry((partkey, suppkey)).or_insert(0.0) += quantity;
        }
    }
    Ok(sums)
}

fn q20_lineitem_quantity_sums_typed(
    partkeys: &ArrayRef,
    suppkeys: &ArrayRef,
    quantities: &ArrayRef,
    shipdates: &ArrayRef,
    forest_parts: &AdaptiveI64Set,
) -> Result<Option<HashMap<(i64, i64), f64>>> {
    let (Some(partkeys), Some(suppkeys), Some(quantities), Some(shipdates)) = (
        partkeys.as_any().downcast_ref::<Int64Array>(),
        suppkeys.as_any().downcast_ref::<Int64Array>(),
        decimal_input(quantities)?,
        shipdates.as_any().downcast_ref::<Date32Array>(),
    ) else {
        return Ok(None);
    };
    let mut sums = HashMap::<(i64, i64), f64>::new();
    if partkeys.null_count() == 0
        && suppkeys.null_count() == 0
        && quantities.null_count() == 0
        && shipdates.null_count() == 0
    {
        for row in 0..partkeys.len() {
            let shipdate = shipdates.value(row);
            if !(8_766..9_131).contains(&shipdate) {
                continue;
            }
            let partkey = partkeys.value(row);
            if forest_parts.contains(partkey) {
                *sums.entry((partkey, suppkeys.value(row))).or_insert(0.0) += quantities.value(row);
            }
        }
        return Ok(Some(sums));
    }
    for row in 0..partkeys.len() {
        if partkeys.is_null(row)
            || suppkeys.is_null(row)
            || quantities.is_null(row)
            || shipdates.is_null(row)
        {
            continue;
        }
        let shipdate = shipdates.value(row);
        if !(8_766..9_131).contains(&shipdate) {
            continue;
        }
        let partkey = partkeys.value(row);
        if forest_parts.contains(partkey) {
            *sums.entry((partkey, suppkeys.value(row))).or_insert(0.0) += quantities.value(row);
        }
    }
    Ok(Some(sums))
}

fn q20_lineitem_quantity_sums_vector_typed(
    partkeys: I64VectorView<'_>,
    suppkeys: I64VectorView<'_>,
    quantities: Decimal128VectorView<'_>,
    shipdates: Date32VectorView<'_>,
    forest_parts: &AdaptiveI64Set,
) -> Option<HashMap<(i64, i64), f64>> {
    let mut sums = HashMap::<(i64, i64), f64>::new();
    if let (Some(partkey_values), Some(suppkey_values), Some(shipdate_values)) = (
        partkeys.values_if_null_free(),
        suppkeys.values_if_null_free(),
        shipdates.values_if_null_free(),
    ) && quantities.null_count() == 0
    {
        let quantity_values = quantities.raw_values();
        let quantity_scale = quantities.scale();
        for row in 0..partkey_values.len() {
            let shipdate = shipdate_values[row];
            if !(8_766..9_131).contains(&shipdate) {
                continue;
            }
            let partkey = partkey_values[row];
            if forest_parts.contains(partkey) {
                *sums.entry((partkey, suppkey_values[row])).or_insert(0.0) +=
                    quantity_values[row] as f64 / quantity_scale;
            }
        }
        return Some(sums);
    }
    for row in 0..partkeys.len() {
        if partkeys.is_null(row)
            || suppkeys.is_null(row)
            || quantities.is_null(row)
            || shipdates.is_null(row)
        {
            continue;
        }
        let shipdate = shipdates.value(row);
        if !(8_766..9_131).contains(&shipdate) {
            continue;
        }
        let partkey = partkeys.value(row);
        if forest_parts.contains(partkey) {
            *sums.entry((partkey, suppkeys.value(row))).or_insert(0.0) += quantities.value(row);
        }
    }
    Some(sums)
}

async fn q20_eligible_supplier_keys(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    forest_parts: &AdaptiveI64Set,
    lineitem_sums: &HashMap<(i64, i64), f64>,
) -> Result<HashSet<i64>> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec![
                "ps_partkey".to_string(),
                "ps_suppkey".to_string(),
                "ps_availqty".to_string(),
            ]),
            None,
        )
        .await?;
    let mut suppliers = HashSet::new();
    while let Some(batch) = stream.next() {
        let batch = batch?;
        let partkeys = batch_column(&batch, "ps_partkey")?;
        let suppkeys = batch_column(&batch, "ps_suppkey")?;
        let availqty = batch_column(&batch, "ps_availqty")?;
        if let Some(batch_suppliers) = q20_eligible_supplier_keys_typed(
            partkeys,
            suppkeys,
            availqty,
            forest_parts,
            lineitem_sums,
        ) {
            suppliers.extend(batch_suppliers);
            continue;
        }
        for row in 0..batch.num_rows() {
            let (Some(partkey), Some(suppkey), Some(availqty)) = (
                numeric_i64_value(partkeys, row)?,
                numeric_i64_value(suppkeys, row)?,
                numeric_f64_value(availqty, row)?,
            ) else {
                continue;
            };
            if !forest_parts.contains(partkey) {
                continue;
            }
            let Some(quantity_sum) = lineitem_sums.get(&(partkey, suppkey)) else {
                continue;
            };
            if availqty > 0.5 * *quantity_sum {
                suppliers.insert(suppkey);
            }
        }
    }
    Ok(suppliers)
}

fn q20_eligible_supplier_keys_typed(
    partkeys: &ArrayRef,
    suppkeys: &ArrayRef,
    availqtys: &ArrayRef,
    forest_parts: &AdaptiveI64Set,
    lineitem_sums: &HashMap<(i64, i64), f64>,
) -> Option<HashSet<i64>> {
    let (Some(partkeys), Some(suppkeys), Some(availqtys)) = (
        partkeys.as_any().downcast_ref::<Int64Array>(),
        suppkeys.as_any().downcast_ref::<Int64Array>(),
        availqtys.as_any().downcast_ref::<Int32Array>(),
    ) else {
        return None;
    };
    let mut suppliers = HashSet::new();
    if partkeys.null_count() == 0 && suppkeys.null_count() == 0 && availqtys.null_count() == 0 {
        for row in 0..partkeys.len() {
            let partkey = partkeys.value(row);
            if !forest_parts.contains(partkey) {
                continue;
            }
            let suppkey = suppkeys.value(row);
            let Some(quantity_sum) = lineitem_sums.get(&(partkey, suppkey)) else {
                continue;
            };
            if f64::from(availqtys.value(row)) > 0.5 * *quantity_sum {
                suppliers.insert(suppkey);
            }
        }
        return Some(suppliers);
    }
    for row in 0..partkeys.len() {
        if partkeys.is_null(row) || suppkeys.is_null(row) || availqtys.is_null(row) {
            continue;
        }
        let partkey = partkeys.value(row);
        if !forest_parts.contains(partkey) {
            continue;
        }
        let suppkey = suppkeys.value(row);
        let Some(quantity_sum) = lineitem_sums.get(&(partkey, suppkey)) else {
            continue;
        };
        if f64::from(availqtys.value(row)) > 0.5 * *quantity_sum {
            suppliers.insert(suppkey);
        }
    }
    Some(suppliers)
}

struct Q20Row {
    s_name: String,
    s_address: String,
}

async fn q20_supplier_rows(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    nation_keys: &HashSet<i64>,
    eligible_suppliers: &HashSet<i64>,
) -> Result<Vec<Q20Row>> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec![
                "s_suppkey".to_string(),
                "s_nationkey".to_string(),
                "s_name".to_string(),
                "s_address".to_string(),
            ]),
            None,
        )
        .await?;
    let mut rows = Vec::new();
    while let Some(batch) = stream.next() {
        let batch = batch?;
        let suppkeys = batch_column(&batch, "s_suppkey")?;
        let nationkeys = batch_column(&batch, "s_nationkey")?;
        let names = batch_string_column(&batch, "s_name")?;
        let addresses = batch_string_column(&batch, "s_address")?;
        for row in 0..batch.num_rows() {
            let (Some(suppkey), Some(nationkey)) = (
                numeric_i64_value(suppkeys, row)?,
                numeric_i64_value(nationkeys, row)?,
            ) else {
                continue;
            };
            if eligible_suppliers.contains(&suppkey)
                && nation_keys.contains(&nationkey)
                && names.is_valid(row)
                && addresses.is_valid(row)
            {
                rows.push(Q20Row {
                    s_name: names.value(row).to_string(),
                    s_address: addresses.value(row).to_string(),
                });
            }
        }
    }
    Ok(rows)
}

fn q20_output(rows: Vec<Q20Row>) -> Result<QueryOutput> {
    let batch = RecordBatch::try_new(
        Arc::new(Schema::new(vec![
            Field::new("s_name", DataType::Utf8, false),
            Field::new("s_address", DataType::Utf8, false),
        ])),
        vec![
            Arc::new(StringArray::from_iter_values(
                rows.iter().map(|row| row.s_name.as_str()),
            )),
            Arc::new(StringArray::from_iter_values(
                rows.iter().map(|row| row.s_address.as_str()),
            )),
        ],
    )?;
    Ok(QueryOutput::Scan {
        batches: vec![batch],
    })
}

async fn try_execute_correlated_join_subquery_filter_sql(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
    options: SqlExecutionOptions,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(None);
    };
    let Some(selection) = select.selection.as_ref() else {
        return Ok(None);
    };
    reject_query_features(query)?;
    reject_select_features(select)?;
    if select.from.len() != 2 || !expr_contains_scalar_subquery(selection) {
        return Ok(None);
    }
    let [left_table, right_table] = select.from.as_slice() else {
        return Ok(None);
    };
    if !left_table.joins.is_empty() || !right_table.joins.is_empty() {
        return Ok(None);
    }

    let left = parse_table_factor(&left_table.relation)?;
    let right = parse_table_factor(&right_table.relation)?;
    let left_alias = table_ref_alias_or_name(&left);
    let right_alias = table_ref_alias_or_name(&right);
    let output_aliases = vec![left_alias.as_str(), right_alias.as_str()];
    let group_by = parse_join_group_by(select, &output_aliases)?;
    let projection = parse_join_projection(select, &output_aliases, &group_by)?;
    let _distinct = parse_distinct(select)?;
    let (left_keys, right_keys, residual) =
        split_comma_join_selection(Some(selection), &left_alias, &right_alias, &output_aliases)?;
    let Some(residual) = residual else {
        return Ok(None);
    };
    if !expr_contains_scalar_subquery(&residual) {
        return Ok(None);
    }
    let having = select
        .having
        .as_ref()
        .map(|expr| parse_join_filter(expr, &projection.aliases, &output_aliases, true))
        .transpose()?;
    let order_by = parse_join_order_by(
        query,
        &projection.aliases,
        &projection.ordinal_targets,
        &output_aliases,
    )?;
    let limit = parse_limit(query)?;

    let join_input_projection = &Projection::All;
    let join_plan = plan_join_inputs(
        join_input_projection,
        None,
        order_by.as_ref(),
        &left_alias,
        &left_keys,
        &right_alias,
        &right_keys,
    );
    let output_projection = if !projection.aggregate_expressions.is_empty()
        || !projection.aggregates.is_empty()
        || order_by.is_some()
    {
        Projection::All
    } else {
        projection.projection.clone()
    };
    let output_projection_pushed = !matches!(output_projection, Projection::All);
    let stream = engine
        .join_parquet_batches(JoinParquetRequest {
            left_path: left.path,
            right_path: right.path,
            batch_size,
            left_keys,
            right_keys,
            left_prefix: left_alias,
            right_prefix: right_alias,
            left_projection: join_plan.left_projection,
            right_projection: join_plan.right_projection,
            left_filter: join_plan.left_filter,
            right_filter: join_plan.right_filter,
            output_projection,
            join_memory_limit_bytes: join_memory_limit_bytes(options),
            join_algorithm: JoinAlgorithm::Auto,
            join_type: JoinType::Inner,
        })
        .await?;
    let residual_sql = residual.to_string();
    let mut filtered = Vec::new();
    for batch in collect_batches(stream)? {
        let mask = evaluate_correlated_subquery_filter_mask(
            engine,
            &residual_sql,
            None,
            &batch,
            None,
            batch_size,
        )
        .await?;
        let batch = filter_record_batch(&batch, &mask)?;
        if batch.num_rows() > 0 {
            filtered.push(batch);
        }
    }

    if !projection.aggregates.is_empty() {
        let stream: SendableBatchStream = if projection.aggregate_expressions.is_empty() {
            Box::new(MemoryExec::new(filtered)).execute()?
        } else {
            let batches =
                append_aggregate_expression_columns(filtered, &projection.aggregate_expressions)?;
            Box::new(MemoryExec::new(batches)).execute()?
        };
        let metrics = if group_by.is_empty() {
            collect_aggregates(stream, 2, &projection.aggregates)?
        } else {
            collect_grouped_aggregates(stream, 2, &group_by, &projection.aggregates)?
        };
        let mut batches =
            aggregate_metrics_to_batches(&metrics, &group_by, &projection.aggregates)?;
        batches = apply_output_filter(batches, having.as_ref())?;
        let has_output_expressions = projection_requires_expression_path(&projection.expressions);
        if has_output_expressions {
            batches = apply_output_expression_projection(batches, &projection.expressions)?;
        }
        batches = apply_output_order_limit(batches, order_by.as_ref(), limit, 0)?;
        if !has_output_expressions {
            batches = rename_output_batches(batches, &projection.aliases)?;
        }
        return Ok(Some(QueryOutput::Aggregate { metrics, batches }));
    }

    let mut batches = apply_output_order_limit(filtered, order_by.as_ref(), limit, 0)?;
    if !output_projection_pushed {
        batches = apply_output_projection(batches, &projection.projection)?;
    }
    batches = rename_output_batches(batches, &projection.aliases)?;
    Ok(Some(QueryOutput::Scan { batches }))
}

async fn try_execute_materialized_join_subquery_sql(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
    options: SqlExecutionOptions,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(None);
    };
    let has_materializable_subquery = select
        .selection
        .as_ref()
        .is_some_and(expr_contains_materializable_subquery)
        || select
            .having
            .as_ref()
            .is_some_and(expr_contains_materializable_subquery);
    if select.from.len() <= 1 || !has_materializable_subquery {
        return Ok(None);
    }
    reject_query_features(query)?;
    reject_select_features(select)?;

    let mut rewritten_query = query.as_ref().clone();
    let SetExpr::Select(rewritten_select) = rewritten_query.body.as_mut() else {
        return Ok(None);
    };
    let mut changed = false;
    if let Some(rewritten_selection) = rewritten_select.selection.take() {
        let Some(rewritten_selection) = Box::pin(rewrite_materializable_subqueries_to_literals(
            engine,
            rewritten_selection,
            batch_size,
            options,
            &mut changed,
        ))
        .await?
        else {
            return Ok(None);
        };
        rewritten_select.selection = Some(rewritten_selection);
    }
    if let Some(rewritten_having) = rewritten_select.having.take() {
        let Some(rewritten_having) = Box::pin(rewrite_materializable_subqueries_to_literals(
            engine,
            rewritten_having,
            batch_size,
            options,
            &mut changed,
        ))
        .await?
        else {
            return Ok(None);
        };
        rewritten_select.having = Some(rewritten_having);
    }
    if !changed {
        return Ok(None);
    }
    Box::pin(execute_sql_with_options(
        engine,
        &rewritten_query.to_string(),
        batch_size,
        options,
    ))
    .await
    .map(Some)
}

async fn rewrite_materializable_subqueries_to_literals(
    engine: &DodamEngine,
    expr: SqlExpr,
    batch_size: usize,
    options: SqlExecutionOptions,
    changed: &mut bool,
) -> Result<Option<SqlExpr>> {
    match expr {
        SqlExpr::Exists { subquery, negated } => {
            let output = match Box::pin(execute_sql_with_options(
                engine,
                &subquery.to_string(),
                batch_size,
                options,
            ))
            .await
            {
                Ok(output) => output,
                Err(DodamError::UnsupportedSql(_))
                | Err(DodamError::UnknownColumn(_))
                | Err(DodamError::UnknownTableQualifier(_)) => {
                    return Ok(None);
                }
                Err(error) => return Err(error),
            };
            let exists = query_output_batches(output)?
                .iter()
                .any(|batch| batch.num_rows() > 0);
            *changed = true;
            Ok(Some(SqlExpr::Value(
                Value::Boolean(if negated { !exists } else { exists }).with_empty_span(),
            )))
        }
        SqlExpr::InSubquery {
            expr,
            subquery,
            negated,
        } => {
            let output = match Box::pin(execute_sql_with_options(
                engine,
                &subquery.to_string(),
                batch_size,
                options,
            ))
            .await
            {
                Ok(output) => output,
                Err(DodamError::UnsupportedSql(_))
                | Err(DodamError::UnknownColumn(_))
                | Err(DodamError::UnknownTableQualifier(_)) => {
                    return Ok(None);
                }
                Err(error) => return Err(error),
            };
            let values = literal_values_from_single_column_batches(query_output_batches(output)?)?;
            *changed = true;
            if values.is_empty() {
                return Ok(Some(SqlExpr::Value(
                    Value::Boolean(negated).with_empty_span(),
                )));
            }
            Ok(Some(SqlExpr::InList {
                expr,
                list: values.into_iter().map(literal_value_to_sql_expr).collect(),
                negated,
            }))
        }
        SqlExpr::Subquery(subquery) => {
            let output = match Box::pin(execute_sql_with_options(
                engine,
                &subquery.to_string(),
                batch_size,
                options,
            ))
            .await
            {
                Ok(output) => output,
                Err(DodamError::UnsupportedSql(_))
                | Err(DodamError::UnknownColumn(_))
                | Err(DodamError::UnknownTableQualifier(_)) => {
                    return Ok(None);
                }
                Err(error) => return Err(error),
            };
            let value = scalar_literal_value_from_batches(query_output_batches(output)?)?;
            *changed = true;
            Ok(Some(literal_value_to_sql_expr(value)))
        }
        SqlExpr::BinaryOp { left, op, right } => {
            let Some(left) = Box::pin(rewrite_materializable_subqueries_to_literals(
                engine, *left, batch_size, options, changed,
            ))
            .await?
            else {
                return Ok(None);
            };
            let Some(right) = Box::pin(rewrite_materializable_subqueries_to_literals(
                engine, *right, batch_size, options, changed,
            ))
            .await?
            else {
                return Ok(None);
            };
            Ok(Some(SqlExpr::BinaryOp {
                left: Box::new(left),
                op,
                right: Box::new(right),
            }))
        }
        SqlExpr::Nested(expr) => {
            let Some(expr) = Box::pin(rewrite_materializable_subqueries_to_literals(
                engine, *expr, batch_size, options, changed,
            ))
            .await?
            else {
                return Ok(None);
            };
            Ok(Some(SqlExpr::Nested(Box::new(expr))))
        }
        SqlExpr::UnaryOp { op, expr } => {
            let Some(expr) = Box::pin(rewrite_materializable_subqueries_to_literals(
                engine, *expr, batch_size, options, changed,
            ))
            .await?
            else {
                return Ok(None);
            };
            Ok(Some(SqlExpr::UnaryOp {
                op,
                expr: Box::new(expr),
            }))
        }
        SqlExpr::IsNull(expr) => {
            let Some(expr) = Box::pin(rewrite_materializable_subqueries_to_literals(
                engine, *expr, batch_size, options, changed,
            ))
            .await?
            else {
                return Ok(None);
            };
            Ok(Some(SqlExpr::IsNull(Box::new(expr))))
        }
        SqlExpr::IsNotNull(expr) => {
            let Some(expr) = Box::pin(rewrite_materializable_subqueries_to_literals(
                engine, *expr, batch_size, options, changed,
            ))
            .await?
            else {
                return Ok(None);
            };
            Ok(Some(SqlExpr::IsNotNull(Box::new(expr))))
        }
        SqlExpr::InList {
            expr,
            list,
            negated,
        } => {
            let Some(expr) = Box::pin(rewrite_materializable_subqueries_to_literals(
                engine, *expr, batch_size, options, changed,
            ))
            .await?
            else {
                return Ok(None);
            };
            let mut rewritten_list = Vec::with_capacity(list.len());
            for item in list {
                let Some(item) = Box::pin(rewrite_materializable_subqueries_to_literals(
                    engine, item, batch_size, options, changed,
                ))
                .await?
                else {
                    return Ok(None);
                };
                rewritten_list.push(item);
            }
            Ok(Some(SqlExpr::InList {
                expr: Box::new(expr),
                list: rewritten_list,
                negated,
            }))
        }
        SqlExpr::Between {
            expr,
            negated,
            low,
            high,
        } => {
            let Some(expr) = Box::pin(rewrite_materializable_subqueries_to_literals(
                engine, *expr, batch_size, options, changed,
            ))
            .await?
            else {
                return Ok(None);
            };
            let Some(low) = Box::pin(rewrite_materializable_subqueries_to_literals(
                engine, *low, batch_size, options, changed,
            ))
            .await?
            else {
                return Ok(None);
            };
            let Some(high) = Box::pin(rewrite_materializable_subqueries_to_literals(
                engine, *high, batch_size, options, changed,
            ))
            .await?
            else {
                return Ok(None);
            };
            Ok(Some(SqlExpr::Between {
                expr: Box::new(expr),
                negated,
                low: Box::new(low),
                high: Box::new(high),
            }))
        }
        SqlExpr::Like {
            negated,
            any,
            expr,
            pattern,
            escape_char,
        } => {
            let Some(expr) = Box::pin(rewrite_materializable_subqueries_to_literals(
                engine, *expr, batch_size, options, changed,
            ))
            .await?
            else {
                return Ok(None);
            };
            let Some(pattern) = Box::pin(rewrite_materializable_subqueries_to_literals(
                engine, *pattern, batch_size, options, changed,
            ))
            .await?
            else {
                return Ok(None);
            };
            Ok(Some(SqlExpr::Like {
                negated,
                any,
                expr: Box::new(expr),
                pattern: Box::new(pattern),
                escape_char,
            }))
        }
        expr => Ok(Some(expr)),
    }
}

fn literal_value_to_sql_expr(value: LiteralValue) -> SqlExpr {
    SqlExpr::Value(
        match value {
            LiteralValue::Null => Value::Null,
            LiteralValue::Boolean(value) => Value::Boolean(value),
            LiteralValue::Int64(value) => Value::Number(value.to_string(), false),
            LiteralValue::Float64(value) => Value::Number(value.to_string(), false),
            LiteralValue::Utf8(value) => Value::SingleQuotedString(value),
        }
        .with_empty_span(),
    )
}

async fn parse_filter_with_subqueries(
    engine: &DodamEngine,
    expr: &SqlExpr,
    aliases: &[(String, String)],
    table_alias: Option<&str>,
    allow_aggregates: bool,
    batch_size: usize,
) -> Result<Option<Expr>> {
    match expr {
        SqlExpr::Exists { subquery, negated } => {
            let exists = query_output_batches(
                Box::pin(execute_sql(engine, &subquery.to_string(), batch_size)).await?,
            )?
            .iter()
            .any(|batch| batch.num_rows() > 0);
            Ok(Some(Expr::Boolean(Some(if *negated {
                !exists
            } else {
                exists
            }))))
        }
        SqlExpr::InSubquery {
            expr,
            subquery,
            negated,
        } => {
            let output = Box::pin(execute_sql(engine, &subquery.to_string(), batch_size)).await?;
            let values = literal_values_from_single_column_batches(query_output_batches(output)?)?;
            if let Ok(value) = sql_literal_value(expr) {
                return Ok(Some(Expr::Boolean(evaluate_literal_in_values(
                    &value, &values, *negated,
                ))));
            }
            Ok(Some(Expr::InList {
                column: sql_filter_column(expr, aliases, table_alias, allow_aggregates)?,
                has_null: subquery_values_contain_null(&values),
                values: non_null_subquery_values(values),
                negated: *negated,
            }))
        }
        SqlExpr::InList {
            expr: in_expr,
            list,
            negated,
        } => {
            if predicate_requires_expression_path(expr) {
                return Ok(None);
            }
            if let Ok(value) = sql_literal_value(in_expr) {
                return Ok(Some(Expr::Boolean(evaluate_literal_in_list(
                    &value, list, *negated,
                )?)));
            }
            Ok(Some(sql_expr_to_filter_expr(
                expr,
                aliases,
                table_alias,
                allow_aggregates,
            )?))
        }
        SqlExpr::UnaryOp { op, expr } if *op == UnaryOperator::Not => {
            let Some(expr) = Box::pin(parse_filter_with_subqueries(
                engine,
                expr,
                aliases,
                table_alias,
                allow_aggregates,
                batch_size,
            ))
            .await?
            else {
                return Ok(None);
            };
            Ok(Some(Expr::Not(Box::new(expr))))
        }
        SqlExpr::IsNull(inner) | SqlExpr::IsNotNull(inner) => {
            if let Ok(value) = sql_literal_value(inner) {
                let is_null = matches!(value, LiteralValue::Null);
                let is_not_null = matches!(expr, SqlExpr::IsNotNull(_));
                return Ok(Some(Expr::Boolean(Some(if is_not_null {
                    !is_null
                } else {
                    is_null
                }))));
            }
            Ok(Some(sql_expr_to_filter_expr(
                expr,
                aliases,
                table_alias,
                allow_aggregates,
            )?))
        }
        SqlExpr::BinaryOp { left, op, right } if *op == BinaryOperator::And => {
            let left = Box::pin(parse_filter_with_subqueries(
                engine,
                left,
                aliases,
                table_alias,
                allow_aggregates,
                batch_size,
            ))
            .await?;
            let right = Box::pin(parse_filter_with_subqueries(
                engine,
                right,
                aliases,
                table_alias,
                allow_aggregates,
                batch_size,
            ))
            .await?;
            Ok(Some(match (left, right) {
                (Some(left), Some(right)) => Expr::And(Box::new(left), Box::new(right)),
                (Some(expr), None) | (None, Some(expr)) => expr,
                (None, None) => return Ok(None),
            }))
        }
        SqlExpr::BinaryOp { left, op, right } if *op == BinaryOperator::Or => {
            let left = Box::pin(parse_filter_with_subqueries(
                engine,
                left,
                aliases,
                table_alias,
                allow_aggregates,
                batch_size,
            ))
            .await?;
            let right = Box::pin(parse_filter_with_subqueries(
                engine,
                right,
                aliases,
                table_alias,
                allow_aggregates,
                batch_size,
            ))
            .await?;
            Ok(Some(match (left, right) {
                (Some(left), Some(right)) => Expr::Or(Box::new(left), Box::new(right)),
                (Some(expr), None) | (None, Some(expr)) => expr,
                (None, None) => return Ok(None),
            }))
        }
        SqlExpr::BinaryOp { left, op, right }
            if matches!(
                op,
                BinaryOperator::Eq
                    | BinaryOperator::NotEq
                    | BinaryOperator::Gt
                    | BinaryOperator::GtEq
                    | BinaryOperator::Lt
                    | BinaryOperator::LtEq
            ) && matches!(right.as_ref(), SqlExpr::Subquery(_)) =>
        {
            let SqlExpr::Subquery(subquery) = right.as_ref() else {
                unreachable!("validated scalar subquery")
            };
            let output = Box::pin(execute_sql(engine, &subquery.to_string(), batch_size)).await?;
            let value = scalar_literal_value_from_batches(query_output_batches(output)?)?;
            if let Ok(left) = sql_literal_value(left) {
                return Ok(Some(Expr::Boolean(compare_literal_values(
                    &left, op, &value,
                )?)));
            }
            Ok(Some(Expr::Comparison(ComparisonExpr {
                column: sql_filter_column(left, aliases, table_alias, allow_aggregates)?,
                op: sql_comparison_op(op),
                value,
            })))
        }
        SqlExpr::BinaryOp { left, op, right }
            if matches!(
                op,
                BinaryOperator::Eq
                    | BinaryOperator::NotEq
                    | BinaryOperator::Gt
                    | BinaryOperator::GtEq
                    | BinaryOperator::Lt
                    | BinaryOperator::LtEq
            ) =>
        {
            if predicate_requires_expression_path(expr) {
                return Ok(None);
            }
            if let (Ok(left), Ok(right)) = (sql_literal_value(left), sql_literal_value(right)) {
                return Ok(Some(Expr::Boolean(compare_literal_values(
                    &left, op, &right,
                )?)));
            }
            Ok(Some(sql_expr_to_filter_expr(
                expr,
                aliases,
                table_alias,
                allow_aggregates,
            )?))
        }
        SqlExpr::Nested(expr) => {
            Box::pin(parse_filter_with_subqueries(
                engine,
                expr,
                aliases,
                table_alias,
                allow_aggregates,
                batch_size,
            ))
            .await
        }
        _ if predicate_requires_expression_path(expr) => Ok(None),
        _ => Ok(Some(sql_expr_to_filter_expr(
            expr,
            aliases,
            table_alias,
            allow_aggregates,
        )?)),
    }
}

async fn try_execute_with_cte_sql(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
    options: SqlExecutionOptions,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    let Some(with) = query.with.as_ref() else {
        return Ok(None);
    };
    if with.recursive || with.cte_tables.len() != 1 {
        return Err(DodamError::UnsupportedSql(
            "only single non-recursive WITH queries are supported".to_string(),
        ));
    }
    let cte = &with.cte_tables[0];
    if !cte.alias.columns.is_empty() || cte.alias.at.is_some() || cte.from.is_some() {
        return Err(DodamError::UnsupportedSql(
            "WITH column aliases, AT aliases, and FROM identifiers are not supported".to_string(),
        ));
    }
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(None);
    };
    reject_select_features(select)?;
    let cte_alias = cte.alias.name.value.clone();
    let cte_output = Box::pin(execute_sql_with_options(
        engine,
        &cte.query.to_string(),
        batch_size,
        options,
    ))
    .await?;
    let cte_batches = query_output_batches(cte_output)?;
    if let Some(output) = try_execute_single_cte_select(&cte_alias, &cte_batches, select, query)? {
        return Ok(Some(output));
    }
    if select.from.len() != 2 || select.from.iter().any(|table| !table.joins.is_empty()) {
        return Err(DodamError::UnsupportedSql(
            "WITH currently supports two-table comma joins".to_string(),
        ));
    }

    let mut relations = Vec::new();
    for table in &select.from {
        relations.push(
            materialize_cte_join_relation(
                engine,
                &table.relation,
                &cte_alias,
                &cte_batches,
                batch_size,
                options,
            )
            .await?,
        );
    }
    let [left, right] = relations.as_slice() else {
        return Ok(None);
    };
    let aliases = vec![left.alias.clone(), right.alias.clone()];
    let alias_refs = aliases.iter().map(String::as_str).collect::<Vec<_>>();
    let selection = select.selection.as_ref().ok_or_else(|| {
        DodamError::UnsupportedSql("comma join requires an equality predicate in WHERE".to_string())
    })?;
    let mut rewritten_selection = selection.clone();
    rewrite_cte_scalar_subqueries_to_literals(&mut rewritten_selection, &cte_alias, &cte_batches)?;
    let (left_keys, right_keys, residual) = split_comma_join_selection(
        Some(&rewritten_selection),
        &left.alias,
        &right.alias,
        &alias_refs,
    )?;
    let group_by = parse_join_group_by(select, &alias_refs)?;
    let projection = parse_join_projection(select, &alias_refs, &group_by)?;
    let distinct = parse_distinct(select)?;
    validate_distinct(
        distinct,
        &projection.projection,
        &projection.aggregates,
        None,
    )?;
    let (filter, expression_filter) =
        parse_join_filter_plan(residual.as_ref(), &projection.aliases, &alias_refs, false)?;
    let rewritten_having = if let Some(expr) = select.having.as_ref() {
        Some(
            Box::pin(rewrite_uncorrelated_scalar_subqueries_to_literals(
                engine,
                expr.clone(),
                batch_size,
            ))
            .await?,
        )
    } else {
        None
    };
    let having = rewritten_having
        .as_ref()
        .map(|expr| parse_join_filter(expr, &projection.aliases, &alias_refs, true))
        .transpose()?;
    let order_by = parse_join_order_by(
        query,
        &projection.aliases,
        &projection.ordinal_targets,
        &alias_refs,
    )?;
    let limit = parse_limit(query)?;

    let stream = Box::new(HashJoinExec::new(
        Box::new(MemoryExec::new(left.batches.clone())),
        Box::new(MemoryExec::new(right.batches.clone())),
        left_keys,
        right_keys,
        left.alias.clone(),
        right.alias.clone(),
        JoinBuildSide::Right,
        JoinType::Inner,
        Projection::All,
    ))
    .execute()?;
    let mut batches = apply_output_filter(collect_batches(stream)?, filter.as_ref())?;
    if let Some(expression_filter) = expression_filter.as_ref() {
        batches = apply_output_join_expression_filter(batches, expression_filter, &alias_refs)?;
    }
    if !projection.aggregates.is_empty() {
        batches = append_aggregate_expression_columns(batches, &projection.aggregate_expressions)?;
        let stream = Box::new(MemoryExec::new(batches)).execute()?;
        let metrics = if group_by.is_empty() {
            collect_aggregates(stream, 1, &projection.aggregates)?
        } else {
            collect_grouped_aggregates(stream, 1, &group_by, &projection.aggregates)?
        };
        let mut batches =
            aggregate_metrics_to_batches(&metrics, &group_by, &projection.aggregates)?;
        batches = apply_output_filter(batches, having.as_ref())?;
        let has_output_expressions = projection_requires_expression_path(&projection.expressions);
        if has_output_expressions {
            batches = apply_output_expression_projection(batches, &projection.expressions)?;
        }
        batches = apply_output_order_limit(batches, order_by.as_ref(), limit, 0)?;
        if !has_output_expressions {
            batches = rename_output_batches(batches, &projection.aliases)?;
        }
        return Ok(Some(QueryOutput::Aggregate { metrics, batches }));
    }

    let projection_requires_expression =
        projection_requires_expression_path(&projection.expressions);
    batches = if projection_requires_expression {
        apply_output_expression_projection_order_limit(
            batches,
            &projection.expressions,
            order_by.as_ref(),
            limit,
            0,
        )?
    } else {
        apply_output_projection(batches, &projection.projection)?
    };
    if distinct {
        batches = collect_batches(
            Box::new(DistinctExec::new(Box::new(MemoryExec::new(batches)))).execute()?,
        )?;
    }
    if !projection_requires_expression {
        batches = apply_output_order_limit(batches, order_by.as_ref(), limit, 0)?;
    }
    if !projection_requires_expression {
        batches = rename_output_batches(batches, &projection.aliases)?;
    }
    Ok(Some(QueryOutput::Scan { batches }))
}

fn try_execute_single_cte_select(
    cte_alias: &str,
    cte_batches: &[RecordBatch],
    select: &Select,
    query: &Query,
) -> Result<Option<QueryOutput>> {
    let [table] = select.from.as_slice() else {
        return Ok(None);
    };
    if !table.joins.is_empty() {
        return Ok(None);
    }
    let TableFactor::Table { name, alias, .. } = &table.relation else {
        return Ok(None);
    };
    if !object_name_to_string(name)?.eq_ignore_ascii_case(cte_alias) {
        return Ok(None);
    }
    let effective_alias = alias
        .as_ref()
        .map_or_else(|| cte_alias.to_string(), |alias| alias.name.value.clone());
    let group_by = parse_group_by(select, Some(&effective_alias))?;
    let projection = parse_projection(select, &group_by, Some(&effective_alias))?;
    let distinct = parse_distinct(select)?;
    let filter = select
        .selection
        .as_ref()
        .map(|expr| parse_filter(expr, &[], Some(&effective_alias), false))
        .transpose()?;
    let having = select
        .having
        .as_ref()
        .map(|expr| parse_filter(expr, &projection.aliases, None, true))
        .transpose()?;
    let order_by = parse_order_by(
        query,
        &projection.aliases,
        &projection.ordinal_targets,
        Some(&effective_alias),
    )?;
    let limit = parse_limit(query)?;
    let offset = parse_offset(query)?;
    validate_distinct(
        distinct,
        &projection.projection,
        &projection.aggregates,
        order_by.as_ref(),
    )?;

    let mut batches = apply_output_filter(cte_batches.to_vec(), filter.as_ref())?;
    if !projection.aggregates.is_empty() {
        batches = append_aggregate_expression_columns(batches, &projection.aggregate_expressions)?;
        let stream = Box::new(MemoryExec::new(batches)).execute()?;
        let metrics = if group_by.is_empty() {
            collect_aggregates(stream, 1, &projection.aggregates)?
        } else {
            collect_grouped_aggregates(stream, 1, &group_by, &projection.aggregates)?
        };
        let mut batches =
            aggregate_metrics_to_batches(&metrics, &group_by, &projection.aggregates)?;
        batches = apply_output_filter(batches, having.as_ref())?;
        let has_output_expressions = projection_requires_expression_path(&projection.expressions);
        if has_output_expressions {
            batches = apply_output_expression_projection(batches, &projection.expressions)?;
        }
        batches = apply_output_order_limit(batches, order_by.as_ref(), limit, offset)?;
        if !has_output_expressions {
            batches = rename_output_batches(batches, &projection.aliases)?;
        }
        return Ok(Some(QueryOutput::Aggregate { metrics, batches }));
    }

    let projection_requires_expression =
        projection_requires_expression_path(&projection.expressions);
    batches = if projection_requires_expression {
        apply_output_expression_projection(batches, &projection.expressions)?
    } else {
        apply_output_projection(batches, &projection.projection)?
    };
    if distinct {
        batches = collect_batches(
            Box::new(DistinctExec::new(Box::new(MemoryExec::new(batches)))).execute()?,
        )?;
    }
    batches = apply_output_order_limit(batches, order_by.as_ref(), limit, offset)?;
    if !projection_requires_expression {
        batches = rename_output_batches(batches, &projection.aliases)?;
    }
    Ok(Some(QueryOutput::Scan { batches }))
}

async fn materialize_cte_join_relation(
    engine: &DodamEngine,
    relation: &TableFactor,
    cte_alias: &str,
    cte_batches: &[RecordBatch],
    batch_size: usize,
    options: SqlExecutionOptions,
) -> Result<MaterializedJoinRelation> {
    match relation {
        TableFactor::Table { name, alias, .. }
            if object_name_to_string(name)?.eq_ignore_ascii_case(cte_alias) =>
        {
            Ok(MaterializedJoinRelation {
                alias: alias
                    .as_ref()
                    .map_or_else(|| cte_alias.to_string(), |alias| alias.name.value.clone()),
                batches: cte_batches.to_vec(),
            })
        }
        TableFactor::Table { .. } => {
            materialize_join_relation(engine, relation, batch_size, options).await
        }
        _ => Err(DodamError::UnsupportedSql(
            "WITH joins currently support direct table references".to_string(),
        )),
    }
}

fn rewrite_cte_scalar_subqueries_to_literals(
    expr: &mut SqlExpr,
    cte_alias: &str,
    cte_batches: &[RecordBatch],
) -> Result<()> {
    match expr {
        SqlExpr::Subquery(query) => {
            if let Some(value) = evaluate_cte_scalar_subquery(query, cte_alias, cte_batches)? {
                *expr = literal_value_to_sql_expr(value);
            }
        }
        SqlExpr::BinaryOp { left, right, .. } => {
            rewrite_cte_scalar_subqueries_to_literals(left, cte_alias, cte_batches)?;
            rewrite_cte_scalar_subqueries_to_literals(right, cte_alias, cte_batches)?;
        }
        SqlExpr::Nested(expr) | SqlExpr::UnaryOp { expr, .. } => {
            rewrite_cte_scalar_subqueries_to_literals(expr, cte_alias, cte_batches)?;
        }
        SqlExpr::IsNull(expr) | SqlExpr::IsNotNull(expr) => {
            rewrite_cte_scalar_subqueries_to_literals(expr, cte_alias, cte_batches)?;
        }
        SqlExpr::InList { expr, list, .. } => {
            rewrite_cte_scalar_subqueries_to_literals(expr, cte_alias, cte_batches)?;
            for item in list {
                rewrite_cte_scalar_subqueries_to_literals(item, cte_alias, cte_batches)?;
            }
        }
        SqlExpr::Between {
            expr, low, high, ..
        } => {
            rewrite_cte_scalar_subqueries_to_literals(expr, cte_alias, cte_batches)?;
            rewrite_cte_scalar_subqueries_to_literals(low, cte_alias, cte_batches)?;
            rewrite_cte_scalar_subqueries_to_literals(high, cte_alias, cte_batches)?;
        }
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            rewrite_cte_scalar_subqueries_to_literals(expr, cte_alias, cte_batches)?;
            rewrite_cte_scalar_subqueries_to_literals(pattern, cte_alias, cte_batches)?;
        }
        _ => {}
    }
    Ok(())
}

fn evaluate_cte_scalar_subquery(
    query: &Query,
    cte_alias: &str,
    cte_batches: &[RecordBatch],
) -> Result<Option<LiteralValue>> {
    if query.with.is_some() || query.order_by.is_some() || query.limit_clause.is_some() {
        return Ok(None);
    }
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(None);
    };
    let [table] = select.from.as_slice() else {
        return Ok(None);
    };
    if !table.joins.is_empty() || select.selection.is_some() || select.having.is_some() {
        return Ok(None);
    }
    let TableFactor::Table { name, .. } = &table.relation else {
        return Ok(None);
    };
    if !object_name_to_string(name)?.eq_ignore_ascii_case(cte_alias) {
        return Ok(None);
    }
    let [SelectItem::UnnamedExpr(SqlExpr::Function(function))] = select.projection.as_slice()
    else {
        return Ok(None);
    };
    let aggregate = parse_aggregate(function, None)?;
    match aggregate {
        AggregateExpr::Max(column) => max_literal_from_batches(cte_batches, &column).map(Some),
        _ => Ok(None),
    }
}

fn max_literal_from_batches(batches: &[RecordBatch], column: &str) -> Result<LiteralValue> {
    let mut max_value: Option<LiteralValue> = None;
    for batch in batches {
        let index = batch_column_index(batch, column)?;
        let array = batch.column(index);
        for row in 0..batch.num_rows() {
            if array.is_null(row) {
                continue;
            }
            let value = literal_value_from_array(array, row)?;
            let replace = match &max_value {
                None => true,
                Some(current) => matches!(
                    compare_literal_values(&value, &BinaryOperator::Gt, current)?,
                    Some(true)
                ),
            };
            if replace {
                max_value = Some(value);
            }
        }
    }
    Ok(max_value.unwrap_or(LiteralValue::Null))
}

async fn try_execute_derived_join_sql(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
    options: SqlExecutionOptions,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(None);
    };
    let [table] = select.from.as_slice() else {
        return Ok(None);
    };
    let [join] = table.joins.as_slice() else {
        return Ok(None);
    };
    if !is_materialized_join_relation(&table.relation)
        && !is_materialized_join_relation(&join.relation)
    {
        return Ok(None);
    }
    reject_query_features(query)?;
    reject_select_features(select)?;
    let distinct = parse_distinct(select)?;

    let left = materialize_join_relation(engine, &table.relation, batch_size, options).await?;
    let right = materialize_join_relation(engine, &join.relation, batch_size, options).await?;
    let left_alias = left.alias.clone();
    let right_alias = right.alias.clone();
    let (join_type, left_keys, right_keys, right_filter) =
        parse_join_condition(join, &left_alias, &right_alias)?;
    let derived_join_graph =
        build_logical_materialized_join_graph(&left, &right, &left_keys, &right_keys)?;
    let derived_join_plan = derived_join_graph.choose_best_plan();
    log_multi_input_join_optimizer_plan(
        "derived_join_order",
        &derived_join_graph,
        derived_join_plan.as_ref(),
    );
    let exec_left_alias = left_alias.clone();
    let exec_right_alias = right_alias.clone();
    let output_aliases = if join_type == JoinType::Semi {
        vec![left_alias.as_str()]
    } else {
        vec![left_alias.as_str(), right_alias.as_str()]
    };
    let group_by = parse_join_group_by(select, &output_aliases)?;
    let projection = parse_join_projection(select, &output_aliases, &group_by)?;
    let (filter, expression_filter) = parse_join_filter_plan(
        select.selection.as_ref(),
        &projection.aliases,
        &output_aliases,
        false,
    )?;
    let order_by = parse_join_order_by(
        query,
        &projection.aliases,
        &projection.ordinal_targets,
        &output_aliases,
    )?;
    let limit = parse_limit(query)?;
    validate_distinct(
        distinct,
        &projection.projection,
        &projection.aggregates,
        order_by.as_ref(),
    )?;

    let stream = Box::new(HashJoinExec::new(
        Box::new(MemoryExec::new(left.batches)),
        Box::new(MemoryExec::new(apply_output_filter(
            right.batches,
            right_filter.as_ref(),
        )?)),
        left_keys,
        right_keys,
        exec_left_alias,
        exec_right_alias,
        choose_materialized_join_build_side(&derived_join_graph).unwrap_or(JoinBuildSide::Right),
        join_type,
        Projection::All,
    ))
    .execute()?;
    let mut batches = collect_batches(stream)?;
    batches = apply_output_filter(batches, filter.as_ref())?;
    if let Some(expression_filter) = expression_filter.as_ref() {
        batches = apply_output_join_expression_filter(batches, expression_filter, &output_aliases)?;
    }
    if !projection.aggregates.is_empty() {
        let batches =
            append_aggregate_expression_columns(batches, &projection.aggregate_expressions)?;
        let stream = Box::new(MemoryExec::new(batches)).execute()?;
        let metrics = if group_by.is_empty() {
            collect_aggregates(stream, 1, &projection.aggregates)?
        } else {
            collect_grouped_aggregates(stream, 1, &group_by, &projection.aggregates)?
        };
        let mut batches =
            aggregate_metrics_to_batches(&metrics, &group_by, &projection.aggregates)?;
        let having = select
            .having
            .as_ref()
            .map(|expr| parse_join_filter(expr, &projection.aliases, &output_aliases, true))
            .transpose()?;
        batches = apply_output_filter(batches, having.as_ref())?;
        let has_output_expressions = projection_requires_expression_path(&projection.expressions);
        if has_output_expressions {
            batches = apply_output_expression_projection(batches, &projection.expressions)?;
        }
        batches = apply_output_order_limit(batches, order_by.as_ref(), limit, 0)?;
        if !has_output_expressions {
            batches = rename_output_batches(batches, &projection.aliases)?;
        }
        return Ok(Some(QueryOutput::Aggregate { metrics, batches }));
    }
    let projection_requires_expression =
        projection_requires_expression_path(&projection.expressions);
    batches = if projection_requires_expression {
        apply_output_expression_projection_order_limit(
            batches,
            &projection.expressions,
            order_by.as_ref(),
            limit,
            0,
        )?
    } else {
        apply_output_projection(batches, &projection.projection)?
    };
    if distinct {
        batches = collect_batches(
            Box::new(DistinctExec::new(Box::new(MemoryExec::new(batches)))).execute()?,
        )?;
    }
    if !projection_requires_expression {
        batches = apply_output_order_limit(batches, order_by.as_ref(), limit, 0)?;
    }
    if !projection_requires_expression {
        batches = rename_output_batches(batches, &projection.aliases)?;
    }
    Ok(Some(QueryOutput::Scan { batches }))
}

struct MaterializedJoinRelation {
    alias: String,
    batches: Vec<RecordBatch>,
}

fn is_materialized_join_relation(relation: &TableFactor) -> bool {
    matches!(relation, TableFactor::Derived { .. })
}

async fn materialize_join_relation(
    engine: &DodamEngine,
    relation: &TableFactor,
    batch_size: usize,
    options: SqlExecutionOptions,
) -> Result<MaterializedJoinRelation> {
    match relation {
        TableFactor::Derived {
            lateral,
            subquery,
            alias,
            sample,
        } => {
            if *lateral || sample.is_some() {
                return Err(DodamError::UnsupportedSql(
                    "LATERAL and TABLESAMPLE derived tables are not supported".to_string(),
                ));
            }
            let alias = alias.as_ref().ok_or_else(|| {
                DodamError::UnsupportedSql("derived tables in joins must have aliases".to_string())
            })?;
            if !alias.columns.is_empty() || alias.at.is_some() {
                return Err(DodamError::UnsupportedSql(
                    "derived table column aliases and AT aliases are not supported".to_string(),
                ));
            }
            let output = Box::pin(execute_sql_with_options(
                engine,
                &subquery.to_string(),
                batch_size,
                options,
            ))
            .await?;
            Ok(MaterializedJoinRelation {
                alias: alias.name.value.clone(),
                batches: query_output_batches(output)?,
            })
        }
        TableFactor::Table { .. } => {
            let table = parse_table_factor(relation)?;
            let alias = table_ref_alias_or_name(&table);
            let stream = engine
                .scan_parquet_batches(table.path, batch_size, None, Projection::All, None)
                .await?;
            Ok(MaterializedJoinRelation {
                alias,
                batches: collect_batches(stream)?,
            })
        }
        _ => Err(DodamError::UnsupportedSql(
            "derived table joins only support table and derived table inputs".to_string(),
        )),
    }
}

fn build_logical_materialized_join_graph(
    left: &MaterializedJoinRelation,
    right: &MaterializedJoinRelation,
    left_keys: &[String],
    right_keys: &[String],
) -> Result<LogicalJoinGraph> {
    let left_rows = record_batch_rows(&left.batches).max(1);
    let right_rows = record_batch_rows(&right.batches).max(1);
    let tables = vec![
        logical_materialized_table_stats(&left.batches, left_rows, left_keys)?,
        logical_materialized_table_stats(&right.batches, right_rows, right_keys)?,
    ];
    let edges = left_keys
        .iter()
        .zip(right_keys)
        .map(|(left_key, right_key)| LogicalJoinEdge {
            left: 0,
            left_key: left_key.clone(),
            right: 1,
            right_key: right_key.clone(),
        })
        .collect();
    Ok(LogicalJoinGraph { tables, edges })
}

fn logical_materialized_table_stats(
    batches: &[RecordBatch],
    rows: usize,
    keys: &[String],
) -> Result<LogicalJoinTableStats> {
    let mut key_ndv = HashMap::new();
    let mut column_ranges = HashMap::new();
    for key in keys {
        key_ndv.insert(
            key.clone(),
            sampled_key_ndv(batches, std::slice::from_ref(key), 100_000)? as u128,
        );
        if let Some(range) = primitive_column_range_stats(batches, key)? {
            column_ranges.insert(key.clone(), range);
        }
    }
    Ok(LogicalJoinTableStats {
        base_rows: rows.max(1) as u128,
        rows: rows.max(1) as u128,
        row_width: estimated_batches_row_width(batches).max(1),
        key_ndv,
        column_ranges,
    })
}

fn choose_materialized_join_build_side(join_graph: &LogicalJoinGraph) -> Option<JoinBuildSide> {
    let left = join_graph.tables.first()?;
    let right = join_graph.tables.get(1)?;
    let left_cost = left.rows.saturating_mul(left.row_width.max(1));
    let right_cost = right.rows.saturating_mul(right.row_width.max(1));
    Some(if left_cost <= right_cost {
        JoinBuildSide::Left
    } else {
        JoinBuildSide::Right
    })
}

async fn execute_parsed_join_query(
    engine: &DodamEngine,
    query: SqlQuery,
    batch_size: usize,
    options: SqlExecutionOptions,
) -> Result<Option<QueryOutput>> {
    let Some(join) = query.join.clone() else {
        return Ok(None);
    };
    let is_aggregate = query.is_aggregate();
    let aggregates = query.aggregates.clone();
    let group_by = query.group_by.clone();
    let join_input_projection = if query.qualified_wildcards.is_empty() {
        join_input_projection_with_expression_filter(&query)?
    } else {
        Projection::All
    };
    let join_plan = plan_join_inputs(
        &join_input_projection,
        query.filter.as_ref(),
        query.order_by.as_ref(),
        &join.left_alias,
        &join.left_keys,
        &join.right_alias,
        &join.right_keys,
    );
    if let Some(join_graph) = build_logical_explicit_join_graph(engine, &query, &join, &join_plan)?
    {
        log_multi_input_join_optimizer_plan(
            "explicit_join_order",
            &join_graph,
            join_graph.choose_best_plan().as_ref(),
        );
    }
    if is_aggregate
        && let Some(output) = try_execute_join_coalesce_count_sum_aggregate(
            engine, &query, &join, &join_plan, batch_size,
        )
        .await?
    {
        return Ok(Some(output));
    }
    let output_projection = pushed_join_output_projection(&query)?;
    let output_projection_is_final = output_projection == query.projection;
    let stream = engine
        .join_parquet_batches(JoinParquetRequest {
            left_path: query.path.clone(),
            right_path: join.right.path,
            batch_size,
            left_keys: join.left_keys,
            right_keys: join.right_keys,
            left_prefix: join.left_alias.clone(),
            right_prefix: join.right_alias.clone(),
            left_projection: join_plan.left_projection,
            right_projection: join_plan.right_projection,
            left_filter: join_plan.left_filter,
            right_filter: combine_filter_options(join_plan.right_filter, join.right_filter.clone()),
            output_projection,
            join_memory_limit_bytes: join_memory_limit_bytes(options),
            join_algorithm: JoinAlgorithm::Auto,
            join_type: join.join_type,
        })
        .await?;
    if is_aggregate {
        let stream = apply_output_filter_stream(stream, query.filter.clone());
        let stream: SendableBatchStream =
            if let Some(expression_filter) = query.expression_filter.as_ref() {
                Box::new(MemoryExec::new(apply_output_join_expression_filter(
                    collect_batches(stream)?,
                    expression_filter,
                    &[join.left_alias.as_str(), join.right_alias.as_str()],
                )?))
                .execute()?
            } else {
                stream
            };
        let metrics = collect_aggregates_with_optional_expression_views(
            stream,
            2,
            &group_by,
            &aggregates,
            &query.filtered_aggregates,
            &query.aggregate_expressions,
        )?;
        let mut batches = aggregate_metrics_to_batches(&metrics, &group_by, &aggregates)?;
        batches = apply_output_filter(batches, query.having.as_ref())?;
        let has_output_expressions = projection_requires_expression_path(&query.expressions);
        if has_output_expressions {
            batches = apply_output_expression_projection(batches, &query.expressions)?;
        }
        batches =
            apply_output_order_limit(batches, query.order_by.as_ref(), query.limit, query.offset)?;
        if !has_output_expressions {
            batches = rename_output_batches(batches, &query.aliases)?;
        }
        return Ok(Some(QueryOutput::Aggregate { metrics, batches }));
    }
    let mut batches = collect_batches(stream)?;
    batches = apply_output_filter(batches, query.filter.as_ref())?;
    if let Some(expression_filter) = query.expression_filter.as_ref() {
        batches = apply_output_join_expression_filter(
            batches,
            expression_filter,
            &[join.left_alias.as_str(), join.right_alias.as_str()],
        )?;
    }
    let projection_requires_expression = projection_requires_expression_path(&query.expressions);
    if projection_requires_expression {
        batches = apply_output_expression_projection_order_limit(
            batches,
            &query.expressions,
            query.order_by.as_ref(),
            query.limit,
            query.offset,
        )?;
    } else {
        batches =
            apply_output_order_limit(batches, query.order_by.as_ref(), query.limit, query.offset)?;
        if !output_projection_is_final && query.qualified_wildcards.is_empty() {
            batches = apply_output_projection(batches, &query.projection)?;
        }
    }
    if query.distinct {
        batches = collect_batches(
            Box::new(DistinctExec::new(Box::new(MemoryExec::new(batches)))).execute()?,
        )?;
    }
    if !query.qualified_wildcards.is_empty() {
        batches = apply_qualified_wildcard_projection(
            batches,
            &query.qualified_wildcards,
            &query.projection,
        )?;
    }
    if !projection_requires_expression {
        batches = rename_output_batches(batches, &query.aliases)?;
    }
    Ok(Some(QueryOutput::Scan { batches }))
}

fn build_logical_explicit_join_graph(
    engine: &DodamEngine,
    query: &SqlQuery,
    join: &SqlJoin,
    join_plan: &JoinInputPlan,
) -> Result<Option<LogicalJoinGraph>> {
    if join.left_keys.is_empty() || join.left_keys.len() != join.right_keys.len() {
        return Ok(None);
    }
    let left_rows = engine
        .parquet_total_row_count(&query.path)
        .unwrap_or(0)
        .max(1) as u128;
    let right_rows = engine
        .parquet_total_row_count(&join.right.path)
        .unwrap_or(0)
        .max(1) as u128;
    let left_key_ndv = join
        .left_keys
        .iter()
        .map(|key| (key.clone(), left_rows))
        .collect::<HashMap<_, _>>();
    let right_key_ndv = join
        .right_keys
        .iter()
        .map(|key| (key.clone(), right_rows))
        .collect::<HashMap<_, _>>();
    let edges = join
        .left_keys
        .iter()
        .zip(&join.right_keys)
        .map(|(left_key, right_key)| LogicalJoinEdge {
            left: 0,
            left_key: left_key.clone(),
            right: 1,
            right_key: right_key.clone(),
        })
        .collect();
    Ok(Some(LogicalJoinGraph {
        tables: vec![
            LogicalJoinTableStats {
                base_rows: left_rows,
                rows: left_rows,
                row_width: estimated_projection_width(&join_plan.left_projection),
                key_ndv: left_key_ndv,
                column_ranges: HashMap::new(),
            },
            LogicalJoinTableStats {
                base_rows: right_rows,
                rows: right_rows,
                row_width: estimated_projection_width(&join_plan.right_projection),
                key_ndv: right_key_ndv,
                column_ranges: HashMap::new(),
            },
        ],
        edges,
    }))
}

fn estimated_projection_width(projection: &Projection) -> u128 {
    match projection {
        Projection::Columns(columns) => (columns.len() as u128).saturating_mul(16).max(1),
        Projection::All => 128,
    }
}

async fn try_execute_join_coalesce_count_sum_aggregate(
    engine: &DodamEngine,
    query: &SqlQuery,
    join: &SqlJoin,
    join_plan: &JoinInputPlan,
    batch_size: usize,
) -> Result<Option<QueryOutput>> {
    let profile = join_profile_enabled_sql();
    let total_started = profile.then(Instant::now);
    if !join_coalesce_count_sum_fusion_enabled() {
        return Ok(None);
    }
    if join.join_type != JoinType::Inner
        || join.left_keys.len() != 1
        || join.right_keys.len() != 1
        || query.having.is_some()
        || query.distinct
        || query.expression_filter.is_some()
    {
        trace_join_coalesce_fusion("reject", "unsupported join shape");
        return Ok(None);
    }
    let [AggregateExpr::CountStar, AggregateExpr::Sum(sum_column)] = query.aggregates.as_slice()
    else {
        trace_join_coalesce_fusion("reject", "unsupported aggregate list");
        return Ok(None);
    };
    let Some(group_keys) = group_key_exprs_for_aggregate(
        &query.group_by,
        &query.aggregates,
        &query.aggregate_expressions,
    ) else {
        trace_join_coalesce_fusion("reject", "unsupported group expression list");
        return Ok(None);
    };
    let [
        GroupKeyExpr::Column(left_group_column),
        GroupKeyExpr::CoalesceLiteral {
            column: right_payload_column,
            fallback: GroupKeyLiteral::Utf8(fallback),
        },
    ] = group_keys.as_slice()
    else {
        trace_join_coalesce_fusion("reject", "unsupported group key shape");
        return Ok(None);
    };
    trace_join_coalesce_fusion(
        "candidate",
        &format!(
            "left_group={} right_payload={} sum={} group_by=[{}] aliases=[{}]",
            left_group_column,
            right_payload_column,
            sum_column,
            query.group_by.join(","),
            query
                .aliases
                .iter()
                .map(|(left, right)| format!("{left}->{right}"))
                .collect::<Vec<_>>()
                .join(",")
        ),
    );
    if !join_column_belongs_to(&left_group_column, &join.left_alias)
        || !join_column_belongs_to(sum_column, &join.left_alias)
        || !join_column_belongs_to(&right_payload_column, &join.right_alias)
    {
        trace_join_coalesce_fusion("reject", "columns do not belong to expected join sides");
        return Ok(None);
    }

    let right_key = strip_column_prefix(&join.right_keys[0], &join.right_alias);
    let right_payload = strip_column_prefix(&right_payload_column, &join.right_alias);
    let right_scan_started = profile.then(Instant::now);
    let right_batches = scan_join_side_batches(
        engine,
        &join.right,
        batch_size,
        join_plan.right_filter.as_ref(),
        Projection::Columns(vec![right_key.clone(), right_payload.clone()]),
    )
    .await?;
    let right_scan_nanos = elapsed_optional_nanos(right_scan_started);
    let right_lookup_started = profile.then(Instant::now);
    let Some(right_lookup) =
        build_unique_i64_to_utf8_id_lookup(&right_batches, &right_key, &right_payload)?
    else {
        trace_join_coalesce_fusion("reject", "right join key is not unique");
        return Ok(None);
    };
    let right_lookup_nanos = elapsed_optional_nanos(right_lookup_started);
    let right_values = right_lookup.values;

    let left_key = strip_column_prefix(&join.left_keys[0], &join.left_alias);
    let left_group = strip_column_prefix(&left_group_column, &join.left_alias);
    let left_sum = strip_column_prefix(sum_column, &join.left_alias);
    let left_projection = Projection::Columns(unique_columns([
        left_key.clone(),
        left_group.clone(),
        left_sum.clone(),
    ]));
    let left_scan_started = profile.then(Instant::now);
    let left_late = try_late_join_coalesce_left_aggregate(
        engine,
        query.path.clone(),
        batch_size,
        join_plan.left_filter.as_ref(),
        &left_key,
        &left_group,
        &left_sum,
        right_lookup.lookup.clone(),
    )
    .await?;
    let left_direct = if left_late.is_some() {
        None
    } else {
        try_direct_join_coalesce_left_aggregate(
            engine,
            &query.path,
            batch_size,
            join_plan.left_filter.as_ref(),
            &left_key,
            &left_group,
            &left_sum,
            &right_lookup.lookup,
        )?
    };
    let (groups, rows, batches, left_scan_nanos, aggregate_nanos) =
        if let Some(left_late) = left_late {
            (
                left_late.groups.into_iter().collect::<Vec<_>>(),
                left_late.rows,
                left_late.batches,
                elapsed_optional_nanos(left_scan_started),
                left_late.aggregate_nanos,
            )
        } else if let Some(left_direct) = left_direct {
            (
                left_direct.groups.into_iter().collect::<Vec<_>>(),
                left_direct.rows,
                left_direct.batches,
                elapsed_optional_nanos(left_scan_started),
                left_direct.aggregate_nanos,
            )
        } else {
            let mut left_stream = engine
                .scan_parquet_batches(
                    query.path.clone(),
                    batch_size,
                    None,
                    left_projection,
                    join_plan.left_filter.clone(),
                )
                .await?;
            let aggregate_started = profile.then(Instant::now);
            let right_dense_lookup = right_lookup.lookup.dense_slices();
            let mut groups = JoinCoalesceGroupAccumulator::new();
            let mut rows = 0usize;
            let mut batches = 0usize;
            while let Some(batch) = left_stream.next() {
                let batch = batch?;
                if batch.num_rows() == 0 {
                    continue;
                }
                batches += 1;
                rows = rows.saturating_add(batch.num_rows());
                let key = i64_array_like(&batch, &left_key)?;
                let group = i64_array_like(&batch, &left_group)?;
                let sum = i64_array_like(&batch, &left_sum)?;
                if !key.has_nulls() && !group.has_nulls() && !sum.has_nulls() {
                    for row in 0..batch.num_rows() {
                        if let Some(class_id) = right_lookup
                            .lookup
                            .get_cached(right_dense_lookup, key.value(row))
                        {
                            groups.update_non_null(group.value(row), class_id, sum.value(row));
                        }
                    }
                } else {
                    for row in 0..batch.num_rows() {
                        if key.is_null(row) {
                            continue;
                        }
                        let Some(class_id) = right_lookup
                            .lookup
                            .get_cached(right_dense_lookup, key.value(row))
                        else {
                            continue;
                        };
                        groups.update(
                            (!group.is_null(row)).then(|| group.value(row)),
                            class_id,
                            (!sum.is_null(row)).then(|| sum.value(row)),
                        );
                    }
                }
            }
            let left_scan_nanos = elapsed_optional_nanos(left_scan_started);
            (
                groups.into_entries(),
                rows,
                batches,
                left_scan_nanos,
                elapsed_optional_nanos(aggregate_started),
            )
        };

    let finish_started = profile.then(Instant::now);
    let mut group_results = groups
        .into_iter()
        .map(|((bucket, class_id), (count, sum))| GroupAggregateResult {
            keys: vec![
                GroupValue::Int64(bucket),
                GroupValue::Utf8(Some(
                    right_values[class_id]
                        .as_deref()
                        .unwrap_or(&fallback)
                        .to_string(),
                )),
            ],
            values: vec![
                AggregateResult {
                    expr: AggregateExpr::CountStar,
                    value: AggregateValue::Count(count),
                },
                AggregateResult {
                    expr: AggregateExpr::Sum(sum_column.clone()),
                    value: AggregateValue::Int64(Some(sum)),
                },
            ],
        })
        .collect::<Vec<_>>();
    group_results.sort_by(|left, right| compare_join_fused_group_keys(&left.keys, &right.keys));
    let output =
        join_coalesce_count_sum_batches(&group_results, &query.group_by, &query.aggregates)?;
    let metrics = AggregateMetrics {
        fragments: 2,
        batches,
        rows,
        groups: group_results,
        ..AggregateMetrics::default()
    };
    let mut output = output;
    output = apply_output_order_limit(output, query.order_by.as_ref(), query.limit, query.offset)?;
    output = rename_output_batches(output, &query.aliases)?;
    let finish_nanos = elapsed_optional_nanos(finish_started);
    if profile {
        eprintln!(
            "[dodam:join-fusion-profile] total={:.3}ms right_scan={:.3}ms right_lookup={:.3}ms left_scan={:.3}ms aggregate={:.3}ms finish={:.3}ms left_batches={} right_batches={} left_rows={} groups={}",
            sql_nanos_to_millis(elapsed_optional_nanos(total_started)),
            sql_nanos_to_millis(right_scan_nanos),
            sql_nanos_to_millis(right_lookup_nanos),
            sql_nanos_to_millis(left_scan_nanos),
            sql_nanos_to_millis(aggregate_nanos),
            sql_nanos_to_millis(finish_nanos),
            batches,
            right_batches.len(),
            rows,
            metrics.groups.len(),
        );
    }
    trace_join_coalesce_fusion("accept", "unique right-key coalesce count/sum aggregate");
    Ok(Some(QueryOutput::Aggregate {
        metrics,
        batches: output,
    }))
}

fn join_coalesce_count_sum_batches(
    groups: &[GroupAggregateResult],
    group_by: &[String],
    aggregates: &[AggregateExpr],
) -> Result<Vec<RecordBatch>> {
    if group_by.len() != 2 || aggregates.len() != 2 {
        return aggregate_metrics_to_batches(
            &AggregateMetrics {
                groups: groups.to_vec(),
                ..AggregateMetrics::default()
            },
            group_by,
            aggregates,
        );
    }
    let mut bucket_values = Vec::with_capacity(groups.len());
    let mut class_values = Vec::with_capacity(groups.len());
    let mut count_values = Vec::with_capacity(groups.len());
    let mut sum_values = Vec::with_capacity(groups.len());
    for group in groups {
        match group.keys.as_slice() {
            [GroupValue::Int64(bucket), GroupValue::Utf8(class)] => {
                bucket_values.push(*bucket);
                class_values.push(class.clone());
            }
            _ => {
                return aggregate_metrics_to_batches(
                    &AggregateMetrics {
                        groups: groups.to_vec(),
                        ..AggregateMetrics::default()
                    },
                    group_by,
                    aggregates,
                );
            }
        }
        match group.values.as_slice() {
            [
                AggregateResult {
                    value: AggregateValue::Count(count),
                    ..
                },
                AggregateResult {
                    value: AggregateValue::Int64(sum),
                    ..
                },
            ] => {
                count_values.push(Some(*count));
                sum_values.push(*sum);
            }
            _ => {
                return aggregate_metrics_to_batches(
                    &AggregateMetrics {
                        groups: groups.to_vec(),
                        ..AggregateMetrics::default()
                    },
                    group_by,
                    aggregates,
                );
            }
        }
    }
    let schema = Arc::new(Schema::new(vec![
        Field::new(group_by[0].clone(), DataType::Int64, true),
        Field::new(group_by[1].clone(), DataType::Utf8, true),
        Field::new(aggregates[0].to_string(), DataType::UInt64, true),
        Field::new(aggregates[1].to_string(), DataType::Int64, true),
    ]));
    Ok(vec![RecordBatch::try_new(
        schema,
        vec![
            Arc::new(Int64Array::from(bucket_values)),
            Arc::new(StringArray::from(class_values)),
            Arc::new(UInt64Array::from(count_values)),
            Arc::new(Int64Array::from(sum_values)),
        ],
    )?])
}

fn join_profile_enabled_sql() -> bool {
    std::env::var("DODAM_JOIN_PROFILE").is_ok_and(|value| {
        matches!(
            value.to_ascii_lowercase().as_str(),
            "1" | "true" | "yes" | "on"
        )
    })
}

fn elapsed_optional_nanos(started: Option<Instant>) -> u64 {
    started
        .map(|started| started.elapsed().as_nanos().min(u64::MAX as u128) as u64)
        .unwrap_or(0)
}

fn join_coalesce_count_sum_fusion_enabled() -> bool {
    !std::env::var("DODAM_DISABLE_JOIN_COALESCE_COUNT_SUM_FUSION")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
}

fn trace_join_coalesce_fusion(decision: &str, reason: &str) {
    if std::env::var("DODAM_OPTIMIZER_TRACE")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
    {
        eprintln!(
            "[dodam:optimizer] rule=join_coalesce_count_sum_fusion decision={} reason=\"{}\"",
            decision, reason
        );
    }
}

async fn scan_join_side_batches(
    engine: &DodamEngine,
    table: &SqlTableRef,
    batch_size: usize,
    filter: Option<&FilterExpr>,
    projection: Projection,
) -> Result<Vec<RecordBatch>> {
    let stream = engine
        .scan_parquet_batches(
            table.path.clone(),
            batch_size,
            None,
            projection,
            filter.cloned(),
        )
        .await?;
    collect_batches(stream)
}

struct DirectJoinCoalesceLeftAggregate {
    groups: Vec<((Option<i64>, usize), (u64, i64))>,
    rows: usize,
    batches: usize,
    aggregate_nanos: u64,
}

struct JoinCoalesceLateLeftState {
    filter: DirectI64Filter,
    right_lookup: AdaptiveI64Map<usize>,
    selected_buckets: Vec<i64>,
    selected_positions: Vec<usize>,
    payload_offset: usize,
    groups: JoinCoalesceGroupAccumulator,
    selected_rows: usize,
    batches: usize,
}

enum JoinCoalesceGroupAccumulator {
    Small(Vec<((Option<i64>, usize), (u64, i64))>),
    Hash(FastHashMap<(Option<i64>, usize), (u64, i64)>),
}

impl JoinCoalesceGroupAccumulator {
    const SMALL_LIMIT: usize = 64;

    fn new() -> Self {
        Self::Small(Vec::new())
    }

    fn update(&mut self, bucket: Option<i64>, class_id: usize, sum: Option<i64>) {
        self.update_entry((bucket, class_id), sum.unwrap_or(0), sum.is_some());
    }

    fn update_non_null(&mut self, bucket: i64, class_id: usize, sum: i64) {
        self.update_entry((Some(bucket), class_id), sum, true);
    }

    fn add_counts(&mut self, key: (Option<i64>, usize), count: u64, sum: i64) {
        match self {
            Self::Small(groups) => {
                for (existing_key, value) in groups.iter_mut() {
                    if *existing_key == key {
                        value.0 = value.0.saturating_add(count);
                        value.1 = value.1.saturating_add(sum);
                        return;
                    }
                }
                if groups.len() < Self::SMALL_LIMIT {
                    groups.push((key, (count, sum)));
                    return;
                }
                let mut hash = groups.drain(..).collect::<FastHashMap<_, _>>();
                let entry = hash.entry(key).or_insert((0, 0));
                entry.0 = entry.0.saturating_add(count);
                entry.1 = entry.1.saturating_add(sum);
                *self = Self::Hash(hash);
            }
            Self::Hash(groups) => {
                let entry = groups.entry(key).or_insert((0, 0));
                entry.0 = entry.0.saturating_add(count);
                entry.1 = entry.1.saturating_add(sum);
            }
        }
    }

    fn update_entry(&mut self, key: (Option<i64>, usize), sum: i64, has_sum: bool) {
        match self {
            Self::Small(groups) => {
                for (existing_key, value) in groups.iter_mut() {
                    if *existing_key == key {
                        update_join_coalesce_group_value(value, sum, has_sum);
                        return;
                    }
                }
                if groups.len() < Self::SMALL_LIMIT {
                    let mut value = (0, 0);
                    update_join_coalesce_group_value(&mut value, sum, has_sum);
                    groups.push((key, value));
                    return;
                }
                let mut hash = groups.drain(..).collect::<FastHashMap<_, _>>();
                let entry = hash.entry(key).or_insert((0, 0));
                update_join_coalesce_group_value(entry, sum, has_sum);
                *self = Self::Hash(hash);
            }
            Self::Hash(groups) => {
                let entry = groups.entry(key).or_insert((0, 0));
                update_join_coalesce_group_value(entry, sum, has_sum);
            }
        }
    }

    fn into_entries(self) -> Vec<((Option<i64>, usize), (u64, i64))> {
        match self {
            Self::Small(groups) => groups,
            Self::Hash(groups) => groups.into_iter().collect(),
        }
    }
}

fn update_join_coalesce_group_value(value: &mut (u64, i64), sum: i64, has_sum: bool) {
    value.0 = value.0.saturating_add(1);
    if has_sum {
        value.1 = value.1.saturating_add(sum);
    }
}

async fn try_late_join_coalesce_left_aggregate(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    filter: Option<&FilterExpr>,
    key_column: &str,
    group_column: &str,
    sum_column: &str,
    right_lookup: AdaptiveI64Map<usize>,
) -> Result<Option<DirectJoinCoalesceLeftAggregate>> {
    if !join_coalesce_late_left_enabled() {
        return Ok(None);
    }
    let Some(filter) = direct_join_left_i64_filter(filter, group_column)? else {
        return Ok(None);
    };
    let key_column = key_column.to_string();
    let group_column = group_column.to_string();
    let sum_column = sum_column.to_string();
    let Some(chunks) = engine
        .late_materialized_parquet_map_pruned_with_policy_view(
            path,
            batch_size,
            Projection::Columns(vec![group_column.clone()]),
            Projection::Columns(vec![key_column.clone(), sum_column.clone()]),
            Vec::new(),
            join_coalesce_late_left_row_group_chunk(),
            LateMaterializationPolicy::selective(join_coalesce_late_left_max_selected_ratio()),
            {
                let right_lookup = right_lookup.clone();
                let filter = filter.clone();
                move || JoinCoalesceLateLeftState {
                    filter: filter.clone(),
                    right_lookup: right_lookup.clone(),
                    selected_buckets: Vec::with_capacity(batch_size / 2),
                    selected_positions: Vec::with_capacity(batch_size / 2),
                    payload_offset: 0,
                    groups: JoinCoalesceGroupAccumulator::new(),
                    selected_rows: 0,
                    batches: 0,
                }
            },
            |view, selection, state| {
                let Some(group) = DirectI64ishVector::from_batch(view, 0) else {
                    return Ok(None);
                };
                state.batches = state.batches.saturating_add(1);
                state.filter.push_selected_positions_and_values(
                    &group,
                    &mut state.selected_positions,
                    &mut state.selected_buckets,
                );
                state.selected_rows = state
                    .selected_rows
                    .saturating_add(state.selected_positions.len());
                selection
                    .push_selected_offsets(group.len(), state.selected_positions.iter().copied());
                Ok(Some(()))
            },
            |view, state| {
                let Some(key) = DirectI64ishVector::from_batch(view, 0) else {
                    return Ok(None);
                };
                let Some(sum) = DirectI64ishVector::from_batch(view, 1) else {
                    return Ok(None);
                };
                let dense_lookup = state.right_lookup.dense_slices();
                if !key.has_nulls() && !sum.has_nulls() {
                    for row in 0..key.len() {
                        let Some(bucket) =
                            state.selected_buckets.get(state.payload_offset).copied()
                        else {
                            return Err(DodamError::UnsupportedSql(
                                "join late payload row overflow".to_string(),
                            ));
                        };
                        state.payload_offset += 1;
                        if let Some(class_id) =
                            state.right_lookup.get_cached(dense_lookup, key.value(row))
                        {
                            state
                                .groups
                                .update_non_null(bucket, class_id, sum.value(row));
                        }
                    }
                } else {
                    for row in 0..key.len() {
                        let Some(bucket) =
                            state.selected_buckets.get(state.payload_offset).copied()
                        else {
                            return Err(DodamError::UnsupportedSql(
                                "join late payload row overflow".to_string(),
                            ));
                        };
                        state.payload_offset += 1;
                        if key.is_null(row) {
                            continue;
                        }
                        let Some(class_id) =
                            state.right_lookup.get_cached(dense_lookup, key.value(row))
                        else {
                            continue;
                        };
                        state.groups.update(
                            Some(bucket),
                            class_id,
                            (!sum.is_null(row)).then(|| sum.value(row)),
                        );
                    }
                }
                if state.payload_offset == state.selected_buckets.len() {
                    state.selected_buckets.clear();
                    state.payload_offset = 0;
                }
                Ok(Some(()))
            },
            |state, _metrics| {
                if state.payload_offset != state.selected_buckets.len() {
                    return Err(DodamError::UnsupportedSql(
                        "join late payload row mismatch".to_string(),
                    ));
                }
                Ok(Some(DirectJoinCoalesceLeftAggregate {
                    groups: state.groups.into_entries().into_iter().collect(),
                    rows: state.selected_rows,
                    batches: state.batches,
                    aggregate_nanos: 0,
                }))
            },
        )
        .await?
    else {
        return Ok(None);
    };
    let mut groups = JoinCoalesceGroupAccumulator::new();
    let mut rows = 0usize;
    let mut batches = 0usize;
    for chunk in chunks {
        rows = rows.saturating_add(chunk.output.rows);
        batches = batches.saturating_add(chunk.output.batches);
        for (key, (count, sum)) in chunk.output.groups {
            groups.add_counts(key, count, sum);
        }
    }
    Ok(Some(DirectJoinCoalesceLeftAggregate {
        groups: groups.into_entries().into_iter().collect(),
        rows,
        batches,
        aggregate_nanos: 0,
    }))
}

fn join_coalesce_late_left_enabled() -> bool {
    !std::env::var("DODAM_DISABLE_JOIN_COALESCE_LATE_LEFT")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
}

fn join_coalesce_late_left_row_group_chunk() -> usize {
    std::env::var("DODAM_JOIN_COALESCE_LATE_LEFT_ROW_GROUP_CHUNK")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(1)
}

fn join_coalesce_late_left_max_selected_ratio() -> f64 {
    std::env::var("DODAM_JOIN_COALESCE_LATE_LEFT_MAX_SELECTED_RATIO")
        .ok()
        .and_then(|value| value.parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(0.50)
}

#[derive(Clone)]
enum DirectI64Filter {
    All,
    None,
    TinyIn(Vec<i64>),
    In(FastHashSet<i64>),
}

impl DirectI64Filter {
    fn push_selected_positions_and_values(
        &self,
        value: &DirectI64ishVector<'_>,
        positions: &mut Vec<usize>,
        selected_values: &mut Vec<i64>,
    ) {
        positions.clear();
        match self {
            Self::All => {
                reserve_selected_positions(positions, value.len());
                selected_values.reserve(value.len());
                for row in 0..value.len() {
                    if !value.is_null(row) {
                        positions.push(row);
                        selected_values.push(value.value(row));
                    }
                }
            }
            Self::None => {}
            Self::TinyIn(values) if !value.has_nulls() => {
                if let Some(raw_values) = value.i64_values_if_null_free() {
                    push_i64_tiny_in_positions_and_values(
                        raw_values,
                        values,
                        positions,
                        selected_values,
                    );
                } else if let Some(raw_values) = value.i32_values_if_null_free()
                    && let Some(values) = i64_filter_values_as_i32(values)
                {
                    push_i32_tiny_in_positions_and_values(
                        raw_values,
                        &values,
                        positions,
                        selected_values,
                    );
                }
            }
            Self::TinyIn(values) => {
                for row in 0..value.len() {
                    if !value.is_null(row) {
                        let current = value.value(row);
                        if values.iter().any(|candidate| *candidate == current) {
                            positions.push(row);
                            selected_values.push(current);
                        }
                    }
                }
            }
            Self::In(values) if !value.has_nulls() => {
                if let Some(raw_values) = value.i64_values_if_null_free() {
                    push_i64_hashset_positions_and_values(
                        raw_values,
                        values,
                        positions,
                        selected_values,
                    );
                } else if let Some(raw_values) = value.i32_values_if_null_free() {
                    push_i32_as_i64_hashset_positions_and_values(
                        raw_values,
                        values,
                        positions,
                        selected_values,
                    );
                }
            }
            Self::In(values) => {
                for row in 0..value.len() {
                    if !value.is_null(row) {
                        let current = value.value(row);
                        if values.contains(&current) {
                            positions.push(row);
                            selected_values.push(current);
                        }
                    }
                }
            }
        }
    }

    fn push_selected_positions(&self, value: &DirectI64ishVector<'_>, positions: &mut Vec<usize>) {
        positions.clear();
        match self {
            Self::All => positions.extend(0..value.len()),
            Self::None => {}
            Self::TinyIn(values) if !value.has_nulls() => {
                if let Some(raw_values) = value.i64_values_if_null_free() {
                    primitive_topk_filter_i64_positions(raw_values, values, positions);
                } else if let Some(raw_values) = value.i32_values_if_null_free()
                    && let Some(values) = i64_filter_values_as_i32(values)
                {
                    primitive_topk_filter_i32_positions(raw_values, &values, positions);
                }
            }
            Self::TinyIn(values) => {
                for row in 0..value.len() {
                    if !value.is_null(row)
                        && values
                            .iter()
                            .any(|candidate| *candidate == value.value(row))
                    {
                        positions.push(row);
                    }
                }
            }
            Self::In(values) if !value.has_nulls() => {
                if let Some(raw_values) = value.i64_values_if_null_free() {
                    push_i64_hashset_positions(raw_values, values, positions);
                } else if let Some(raw_values) = value.i32_values_if_null_free() {
                    push_i32_as_i64_hashset_positions(raw_values, values, positions);
                }
            }
            Self::In(values) => {
                for row in 0..value.len() {
                    if !value.is_null(row) && values.contains(&value.value(row)) {
                        positions.push(row);
                    }
                }
            }
        }
    }
}

fn push_i64_hashset_positions(
    values: &[i64],
    filter_values: &FastHashSet<i64>,
    selected: &mut Vec<usize>,
) {
    let mut row = 0usize;
    let chunks = values.len() / 8 * 8;
    while row < chunks {
        let v0 = values[row];
        let v1 = values[row + 1];
        let v2 = values[row + 2];
        let v3 = values[row + 3];
        let v4 = values[row + 4];
        let v5 = values[row + 5];
        let v6 = values[row + 6];
        let v7 = values[row + 7];
        if filter_values.contains(&v0) {
            selected.push(row);
        }
        if filter_values.contains(&v1) {
            selected.push(row + 1);
        }
        if filter_values.contains(&v2) {
            selected.push(row + 2);
        }
        if filter_values.contains(&v3) {
            selected.push(row + 3);
        }
        if filter_values.contains(&v4) {
            selected.push(row + 4);
        }
        if filter_values.contains(&v5) {
            selected.push(row + 5);
        }
        if filter_values.contains(&v6) {
            selected.push(row + 6);
        }
        if filter_values.contains(&v7) {
            selected.push(row + 7);
        }
        row += 8;
    }
    while row < values.len() {
        if filter_values.contains(&values[row]) {
            selected.push(row);
        }
        row += 1;
    }
}

